	[109]={ lines="这些无人机都是我自己开发和制作的，你说挺漂亮的？谢谢你。", voice="hero_4503_cv_09.prefab", voice1="hero_4503_cv_09.prefab", lines1="这些无人机都是我自己开发和制作的，你说挺漂亮的？谢谢你。"
