	[111]={ lines="你知道吗？海军是个很浪漫的兵种——他们的血管里流淌着海蓝，胸腔里起浮着潮涨潮落，最终在海面上溅起无数水花，归于大海。", voice="hero_4503_cv_11.prefab", voice1="hero_4503_cv_11.prefab", lines1="你知道吗？海军是个很浪漫的兵种——他们的血管里流淌着海蓝，胸腔里起浮着潮涨潮落，最终在海面上溅起无数水花，归于大海。"
},
	[112]={ lines="我在基地最喜欢做的事？那应该是站在甲板上，吹着迎面而来的海风，看着在海面肆意翱翔的海鸟吧？", voice="hero_4503_cv_12.prefab", voice1="hero_4503_cv_12.prefab", lines1="我在基地最喜欢做的事？那应该是站在甲板上，吹着迎面而来的海风，看着在海面肆意翱翔的海鸟吧？"
},
	[113]={ lines="你问我对无人机的看法？我觉得它们并不只是冷冰冰的机器，一旦你给它赋予了既定的意义，一切都会不一样……那种感觉就像是你养了一只鸟，这样说……你能明白吗？", voice="hero_4503_cv_13.prefab", voice1="hero_4503_cv_13.prefab", lines1="你问我对无人机的看法？我觉得它们并不只是冷冰冰的机器，一旦你给它赋予了既定的意义，一切都会不一样……那种感觉就像是你养了一只鸟，这样说……你能明白吗？"
},
	[114]={ lines="告诉你一个秘密吧，其实我有一个属于空军的家庭，但是里面没什么温度，嗯……说“没有温度”也不恰当，只是……有些误会存在久了，所以我没有办法和家里人用有温度的语言去进行交流，这也使得我最后离开了家，加入了海军。", voice="hero_4503_cv_14.prefab", voice1="hero_4503_cv_14.prefab", lines1="告诉你一个秘密吧，其实我有一个属于空军的家庭，但是里面没什么温度，嗯……说“没有温度”也不恰当，只是……有些误会存在久了，所以我没有办法和家里人用有温度的语言去进行交流，这也使得我最后离开了家，加入了海军。"
},
	[115]={ lines="海军和空军……关系并不好，我刚加入海军时是有一些担心——虽然那时候的确有一些脑子不好使的人，做了一些让人不快的事情，但现在已经过去了……详细情况？呵，我会在准备好的时候告诉你的。", voice="hero_4503_cv_15.prefab", voice1="hero_4503_cv_15.prefab", lines1="海军和空军……关系并不好，我刚加入海军时是有一些担心——虽然那时候的确有一些脑子不好使的人，做了一些让人不快的事情，但现在已经过去了……详细情况？呵，我会在准备好的时候告诉你的。"
},
	[116]={ lines="今天的暴雨真是突然呢……办公室里有淋浴间吧，还是先去泡个热水澡吧~", voice="", voice1="hero_4503_cv_16.prefab", lines1="今天的暴雨真是突然呢……办公室里有淋浴间吧，要不要一起泡个热水澡？"
