	[117]={ lines="唔……等等……我的袜子湿漉漉的，不要乱动……你就想要这种？真是……随你喜欢吧。", voice="", voice1="hero_4503_cv_17.prefab", lines1="唔……等等……我的袜子湿漉漉的，不要乱动……你就想要这种？真是……随你喜欢吧。"
