	[410]={ lines="没问题！请把最困难的任务交给我吧！", voice="hero_4108_cv_10.prefab", voice1="hero_4108_cv_10.prefab", lines1="没问题！请把最困难的任务交给我吧！"
},
	[411]={ lines="链尉官！有什么需要我为您做的吗？什么都可以——诶？坐着休息？……好吧，有什么需求一定要叫我哦！", voice="hero_4108_cv_11.prefab", voice1="hero_4108_cv_11.prefab", lines1="链尉官！有什么需要我为您做的吗？什么都可以——诶？坐着休息？……好吧，有什么需求一定要叫我哦！"
},
	[412]={ lines="您要试一试来自我家乡的青柠汁吗？很——好喝的！我现在就可以给您做一杯！", voice="hero_4108_cv_12.prefab", voice1="hero_4108_cv_12.prefab", lines1="您要试一试来自我家乡的青柠汁吗？很——好喝的！我现在就可以给您做一杯！"
},
	[413]={ lines="链尉官，要是谁欺负你了，我就帮你揍回去，哼哼，我的拳头可不是吃素的！", voice="hero_4108_cv_13.prefab", voice1="hero_4108_cv_13.prefab", lines1="链尉官，要是谁欺负你了，我就帮你揍回去，哼哼，我的拳头可不是吃素的！"
},
	[414]={ lines="可以请你帮我一件事吗？骑兵团的大伙都说我踏入了人生新阶段，要我带男伴回去——我不太懂他们是什么意思啦……但我也真的很想邀请你去我的家乡，那个……可以吗？", voice="hero_4108_cv_14.prefab", voice1="hero_4108_cv_14.prefab", lines1="可以请你帮我一件事吗？骑兵团的大伙都说我踏入了人生新阶段，要我带男伴回去——我不太懂他们是什么意思啦……但我也真的很想邀请你去我的家乡，那个……可以吗？"
},
	[415]={ lines="链尉官，我觉得我们之间的关系已经不只是“相互信赖”这种程度了，我希望我们的感情能够更深入一些……唉，我果然还是不懂要怎么说那些浪漫话……诶？已经知道并且接受我的心意？嘿嘿……还是链尉官懂我……", voice="hero_4108_cv_15.prefab", voice1="hero_4108_cv_15.prefab", lines1="链尉官，我觉得我们之间的关系已经不只是“相互信赖”这种程度了，我希望我们的感情能够更深入一些……唉，我果然还是不懂要怎么说那些浪漫话……诶？已经知道并且接受我的心意？嘿嘿……还是链尉官懂我……"
},
	[501]={ lines="初次见面，我是阿戴妮，祝我们合作愉快。", voice="hero_4104_cv_01.prefab", voice1="hero_4104_cv_01.prefab", lines1="初次见面，我是阿戴妮，祝我们合作愉快。"
},
	[502]={ lines="为你效命。", voice="hero_4104_cv_02.prefab", voice1="hero_4104_cv_02.prefab", lines1="为你效命。"
},
	[503]={ lines="想看看枪之舞吗——", voice="hero_4104_cv_03.prefab", voice1="hero_4104_cv_03.prefab", lines1="想看看枪之舞吗——"
},
	[504]={ lines="喝啊——", voice="hero_4104_cv_04.prefab", voice1="hero_4104_cv_04.prefab", lines1="喝啊——"
},
	[505]={ lines="想比我的枪快？痴心妄想——", voice="hero_4104_cv_05.prefab", voice1="hero_4104_cv_05.prefab", lines1="想比我的枪快？痴心妄想——"
},
	[506]={ lines="刚才的表现，还满意吗？", voice="hero_4104_cv_06.prefab", voice1="hero_4104_cv_06.prefab", lines1="刚才的表现，还满意吗？"
},
	[507]={ lines="又见面了，今天感觉如何？", voice="hero_4104_cv_07.prefab", voice1="hero_4104_cv_07.prefab", lines1="又见面了，今天感觉如何？"
},
	[508]={ lines="我身上有灰尘？怎么可能？呵……你逗我是吧。", voice="hero_4104_cv_08.prefab", voice1="hero_4104_cv_08.prefab", lines1="我身上有灰尘？怎么可能？呵……你逗我是吧。"
},
	[509]={ lines="骑士礼？我才不会呢，不过……勉为其难给你展示一下吧。", voice="hero_4104_cv_09.prefab", voice1="hero_4104_cv_09.prefab", lines1="骑士礼？我才不会呢，不过……勉为其难给你展示一下吧。"
},
	[510]={ lines="嗯……这干花做得真不错，不愧是我……等等，你看到了？！咳咳……", voice="hero_4104_cv_10.prefab", voice1="hero_4104_cv_10.prefab", lines1="嗯……这干花做得真不错，不愧是我……等等，你看到了？！咳咳……"
},
	[511]={ lines="从维拉提亚离开之后，称得上是好事的事情真的不多，但认识你是其中很好的一件。", voice="hero_4104_cv_11.prefab", voice1="hero_4104_cv_11.prefab", lines1="从维拉提亚离开之后，称得上是好事的事情真的不多，但认识你是其中很好的一件。"
},
	[512]={ lines="就算此处的星空与维拉提亚的看起来并无不同，但终究是不一样的。至于是哪里不一样……我想，大概是一起看星星的人不一样吧？", voice="hero_4104_cv_12.prefab", voice1="hero_4104_cv_12.prefab", lines1="就算此处的星空与维拉提亚的看起来并无不同，但终究是不一样的。至于是哪里不一样……我想，大概是一起看星星的人不一样吧？"
},
	[513]={ lines="为什么离开骑士团？抱歉，我不太想谈论这个。不，不是有意隐瞒，只是，现在还不是时候……或者说——我不希望让你为我徒添烦恼，呵呵~", voice="hero_4104_cv_13.prefab", voice1="hero_4104_cv_13.prefab", lines1="为什么离开骑士团？抱歉，我不太想谈论这个。不，不是有意隐瞒，只是，现在还不是时候……或者说——我不希望让你为我徒添烦恼，呵呵~"
},
	[514]={ lines="嗯？送给我的？这是……星澜花的幼苗？谢谢你，等到花开之时，我们再一起来赏花吧。", voice="hero_4104_cv_14.prefab", voice1="hero_4104_cv_14.prefab", lines1="嗯？送给我的？这是……星澜花的幼苗？谢谢你，等到花开之时，我们再一起来赏花吧。"
},
	[515]={ lines="你对我来说，可不仅仅是并肩作战的战友……呵，你是装不懂，非要我说明白吗？", voice="hero_4104_cv_15.prefab", voice1="hero_4104_cv_15.prefab", lines1="你对我来说，可不仅仅是并肩作战的战友……呵，你是装不懂，非要我说明白吗？"
},
	[601]={ lines="您好，我是冷蛟，这是塔拉斯——话说在前，我有一点洁癖，请你最好不要离我太近，以防冻伤。", voice="hero_4506_cv_01.prefab", voice1="hero_4506_cv_01.prefab", lines1="您好，我是冷蛟，这是塔拉斯——话说在前，我有一点洁癖，请你最好不要离我太近，以防冻伤。"
},
	[602]={ lines="交给我来处理。", voice="hero_4506_cv_02.prefab", voice1="hero_4506_cv_02.prefab", lines1="交给我来处理。"
},
	[603]={ lines="冰之矛，刺穿他们。", voice="hero_4506_cv_03.prefab", voice1="hero_4506_cv_03.prefab", lines1="冰之矛，刺穿他们。"
},
	[604]={ lines="冻结吧——", voice="hero_4506_cv_04.prefab", voice1="hero_4506_cv_04.prefab", lines1="冻结吧——"
},
	[605]={ lines="让寒冷赐予你安息——", voice="hero_4506_cv_05.prefab", voice1="hero_4506_cv_05.prefab", lines1="让寒冷赐予你安息——"
},
	[606]={ lines="和我预料的一样干净。", voice="hero_4506_cv_06.prefab", voice1="hero_4506_cv_06.prefab", lines1="和我预料的一样干净。"
},
	[607]={ lines="久疏问候，链尉官。", voice="hero_4506_cv_07.prefab", voice1="hero_4506_cv_07.prefab", lines1="久疏问候，链尉官。"
},
	[608]={ lines="塔拉斯，别闹~", voice="hero_4506_cv_08.prefab", voice1="hero_4506_cv_08.prefab", lines1="塔拉斯，别闹~"
},
	[609]={ lines="你说塔拉斯有些凶？它其实很温顺，只是你感受不到而已。", voice="hero_4506_cv_09.prefab", voice1="hero_4506_cv_09.prefab", lines1="你说塔拉斯有些凶？它其实很温顺，只是你感受不到而已。"
},
	[610]={ lines="你想知道塔拉斯在想什么？……它并不想告诉你。", voice="hero_4506_cv_10.prefab", voice1="hero_4506_cv_10.prefab", lines1="你想知道塔拉斯在想什么？……它并不想告诉你。"
},
	[611]={ lines="想摸一摸塔拉斯？对不起，我不能让你这么做，抱歉。", voice="hero_4506_cv_11.prefab", voice1="hero_4506_cv_11.prefab", lines1="想摸一摸塔拉斯？对不起，我不能让你这么做，抱歉。"
},
	[612]={ lines="你还记得之前我不让你摸塔拉斯的事情吗？因为源晶兽某种程度上相当于我们的一种“分身”，让外人触摸它们是很让人害羞的一件事，所以……对不起。", voice="hero_4506_cv_12.prefab", voice1="hero_4506_cv_12.prefab", lines1="你还记得之前我不让你摸塔拉斯的事情吗？因为源晶兽某种程度上相当于我们的一种“分身”，让外人触摸它们是很让人害羞的一件事，所以……对不起。"
},
	[616]={ lines="那个……是遮着的……链尉官如果真想看……至少……先告诉我一声……我又不会拒绝你……", voice="hero_4506_cv_16.prefab", voice1="hero_4506_cv_16.prefab", lines1="那个……是遮着的……链尉官如果真想看……至少……先告诉我一声……我又不会拒绝你……"
},
	[617]={ lines="恭喜链尉官，你终于解开——唔 !……嗯……滋溜……啵……噗哈……最后的……谜题了……", voice="hero_4506_cv_17.prefab", voice1="hero_4506_cv_17.prefab", lines1="恭喜链尉官，你终于解开——唔 !……嗯……滋溜……啵……噗哈……最后的……谜题了……"
},
	[618]={ lines="链尉官，你往机器里放了什么……是给我的……“奖励”吗……唔嗯……快要变得无法思考了……", voice="hero_4506_cv_18.prefab", voice1="hero_4506_cv_18.prefab", lines1="链尉官，你往机器里放了什么……是给我的……“奖励”吗……唔嗯……快要变得无法思考了……"
},
	[613]={ lines="问我想不想家？奇怪的问题……想自然是会想的，但我更想回去看一看的，是那个不是自治区的，真正的故乡——传说那里不仅有一望无际的冰原，天空中还有被称为极光的现象……", voice="hero_4506_cv_13.prefab", voice1="hero_4506_cv_13.prefab", lines1="问我想不想家？奇怪的问题……想自然是会想的，但我更想回去看一看的，是那个不是自治区的，真正的故乡——传说那里不仅有一望无际的冰原，天空中还有被称为极光的现象……"
},
	[614]={ lines="链尉官，这个送给你……花纹很好看？谢谢你的夸奖，这是我们普洛米族的特色纹路，这一条代表生命，这一条代表灵魂，而这一条代表情感，当三条纹路集合在一起时……", voice="hero_4506_cv_14.prefab", voice1="hero_4506_cv_14.prefab", lines1="链尉官，这个送给你……花纹很好看？谢谢你的夸奖，这是我们普洛米族的特色纹路，这一条代表生命，这一条代表灵魂，而这一条代表情感，当三条纹路集合在一起时……"
},
	[615]={ lines="如果有一天，我邀请你和我一起回到故乡去，你会愿意吗？我们可以……一起去看一看那传说中的极光……", voice="hero_4506_cv_15.prefab", voice1="hero_4506_cv_15.prefab", lines1="如果有一天，我邀请你和我一起回到故乡去，你会愿意吗？我们可以……一起去看一看那传说中的极光……"
},
	[701]={ lines="莉塔前来帮忙，叫我梅鹿特也可以啦，随你怎么叫，嘿嘿，你可以先给我预支工钱哦？", voice="hero_4502_cv_01.prefab", voice1="hero_4502_cv_01.prefab", lines1="莉塔前来帮忙，叫我梅鹿特也可以啦，随你怎么叫，嘿嘿，你可以先给我预支工钱哦？"
},
	[702]={ lines="这个我熟，把他们全打穿！", voice="hero_4502_cv_02.prefab", voice1="hero_4502_cv_02.prefab", lines1="这个我熟，把他们全打穿！"
},
	[703]={ lines="把你扎成蜂窝——", voice="hero_4502_cv_03.prefab", voice1="hero_4502_cv_03.prefab", lines1="把你扎成蜂窝——"
},
	[704]={ lines="看枪——加大功率——", voice="hero_4502_cv_04.prefab", voice1="hero_4502_cv_04.prefab", lines1="看枪——加大功率——"
},
	[705]={ lines="就是那——把你们烧成灰——！", voice="hero_4502_cv_05.prefab", voice1="hero_4502_cv_05.prefab", lines1="就是那——把你们烧成灰——！"
},
	[706]={ lines="嘿嘿，轻轻松松~", voice="hero_4502_cv_06.prefab", voice1="hero_4502_cv_06.prefab", lines1="嘿嘿，轻轻松松~"
},
	[707]={ lines="你好呀！怎么来得这么晚啊？！", voice="hero_4502_cv_07.prefab", voice1="hero_4502_cv_07.prefab", lines1="你好呀！怎么来得这么晚啊？！"
},
	[708]={ lines="嘿嘿，我给你准备了十个恶作剧，猜猜哪一个会成真？", voice="hero_4502_cv_08.prefab", voice1="hero_4502_cv_08.prefab", lines1="嘿嘿，我给你准备了十个恶作剧，猜猜哪一个会成真？"
},
	[709]={ lines="有没有觉得这个姿势很帅？什么？没觉得？哼！", voice="hero_4502_cv_09.prefab", voice1="hero_4502_cv_09.prefab", lines1="有没有觉得这个姿势很帅？什么？没觉得？哼！"
},
	[710]={ lines="塔罗占卜！怎么样，要不要试一试，很准的！……大概吧？", voice="hero_4502_cv_10.prefab", voice1="hero_4502_cv_10.prefab", lines1="塔罗占卜！怎么样，要不要试一试，很准的！……大概吧？"
},
	[711]={ lines="娜娜姐交代过我要对你礼貌些，我还以为你很难相处呢，但接触下来我看你也很好欺……很好相处嘛~", voice="hero_4502_cv_11.prefab", voice1="hero_4502_cv_11.prefab", lines1="娜娜姐交代过我要对你礼貌些，我还以为你很难相处呢，但接触下来我看你也很好欺……很好相处嘛~"
},
	[712]={ lines="哎，生活真是无聊，你有没有什么好玩的东西呀？要不陪我做个塔罗占卜吧？很准的！上次只是失误，失误！", voice="hero_4502_cv_12.prefab", voice1="hero_4502_cv_12.prefab", lines1="哎，生活真是无聊，你有没有什么好玩的东西呀？要不陪我做个塔罗占卜吧？很准的！上次只是失误，失误！"
},
	[713]={ lines="偷偷告诉你一件事哦——如果你来我们这里消费，报出特定的口令，娜娜姐会给你免费哦……不要告诉她我和你说了这个口令啊！要不我这个月工资就没了！", voice="hero_4502_cv_13.prefab", voice1="hero_4502_cv_13.prefab", lines1="偷偷告诉你一件事哦——如果你来我们这里消费，报出特定的口令，娜娜姐会给你免费哦……不要告诉她我和你说了这个口令啊！要不我这个月工资就没了！"
},
	[714]={ lines="完蛋了完蛋了，把娜娜姐最喜欢的酒搞没了，一旦被她抓住……我肯定要挨罚的，你能不能……帮我买两瓶同款啊？拜托拜托——", voice="hero_4502_cv_14.prefab", voice1="hero_4502_cv_14.prefab", lines1="完蛋了完蛋了，把娜娜姐最喜欢的酒搞没了，一旦被她抓住……我肯定要挨罚的，你能不能……帮我买两瓶同款啊？拜托拜托——"
},
	[715]={ lines="问我为什么会经常做这些恶作剧，其实……不就是为了让你们都看到我嘛……尤其是你，你会看到我做的恶作剧的，对吧，也会原谅我的对吧……", voice="hero_4502_cv_15.prefab", voice1="hero_4502_cv_15.prefab", lines1="问我为什么会经常做这些恶作剧，其实……不就是为了让你们都看到我嘛……尤其是你，你会看到我做的恶作剧的，对吧，也会原谅我的对吧……"
},
	[801]={ lines="你好呀，小可爱，今后可不要让姐姐失望哦？", voice="hero_4505_cv_01.prefab", voice1="hero_4505_cv_01.prefab", lines1="你好呀，小可爱，今后可不要让姐姐失望哦？"
},
	[802]={ lines="好了，姐姐要认真咯？", voice="hero_4505_cv_02.prefab", voice1="hero_4505_cv_02.prefab", lines1="好了，姐姐要认真咯？"
},
	[803]={ lines="稍稍教训一下你~", voice="hero_4505_cv_03.prefab", voice1="hero_4505_cv_03.prefab", lines1="稍稍教训一下你~"
},
	[804]={ lines="猜猜牌面是几？呵呵~", voice="hero_4505_cv_04.prefab", voice1="hero_4505_cv_04.prefab", lines1="猜猜牌面是几？呵呵~"
},
	[805]={ lines="这一下……可是很疼的！", voice="hero_4505_cv_05.prefab", voice1="hero_4505_cv_05.prefab", lines1="这一下……可是很疼的！"
},
	[806]={ lines="打得真漂亮，想要什么奖励~", voice="hero_4505_cv_06.prefab", voice1="hero_4505_cv_06.prefab", lines1="打得真漂亮，想要什么奖励~"
},
	[807]={ lines="今天适合你的酒……是什么呢，猜一下？", voice="hero_4505_cv_07.prefab", voice1="hero_4505_cv_07.prefab", lines1="今天适合你的酒……是什么呢，猜一下？"
},
	[808]={ lines="小可爱，你在看哪呢？呵呵，目不转睛的样子，真可爱。", voice="hero_4505_cv_08.prefab", voice1="hero_4505_cv_08.prefab", lines1="小可爱，你在看哪呢？呵呵，目不转睛的样子，真可爱。"
},
	[809]={ lines="月夜之吻可以满足你的任何需求，小可爱……记住，是任何需求哦", voice="hero_4505_cv_09.prefab", voice1="hero_4505_cv_09.prefab", lines1="月夜之吻可以满足你的任何需求，小可爱……记住，是任何需求哦"
},
	[810]={ lines="今天我买单，想喝点什么呢，小可爱？", voice="hero_4505_cv_10.prefab", voice1="hero_4505_cv_10.prefab", lines1="今天我买单，想喝点什么呢，小可爱？"
},
	[811]={ lines="欢迎光临……要喝点什么？今天是姐姐我亲自调制，可不要浪费机会哦？", voice="hero_4505_cv_11.prefab", voice1="hero_4505_cv_11.prefab", lines1="欢迎光临……要喝点什么？今天是姐姐我亲自调制，可不要浪费机会哦？"
},
	[812]={ lines="今天的你，好像有一点不同呢，难道说……遇到了什么好事吗？呵呵，为了这件好事，我可以请你喝一杯哦~", voice="hero_4505_cv_12.prefab", voice1="hero_4505_cv_12.prefab", lines1="今天的你，好像有一点不同呢，难道说……遇到了什么好事吗？呵呵，为了这件好事，我可以请你喝一杯哦~"
},
	[813]={ lines="人长大了，就会徒增很多烦恼，但是有你在，感觉烦恼都会不翼而飞呢，呵呵~", voice="hero_4505_cv_13.prefab", voice1="hero_4505_cv_13.prefab", lines1="人长大了，就会徒增很多烦恼，但是有你在，感觉烦恼都会不翼而飞呢，呵呵~"
},
	[814]={ lines="说起来，待在你这里会让我感到莫名的安心呢……只是美好时光不会持续太久，还有不少孩子等着我回去呢。怎么，想让我在这继续留一会？……呵呵，想得挺美~", voice="hero_4505_cv_14.prefab", voice1="hero_4505_cv_14.prefab", lines1="说起来，待在你这里会让我感到莫名的安心呢……只是美好时光不会持续太久，还有不少孩子等着我回去呢。怎么，想让我在这继续留一会？……呵呵，想得挺美~"
},
	[815]={ lines="你呀，真会讨人开心……也许有一天，我真的会需要你的依靠，到了那一天，你会站在我身边吗，小~可~爱？", voice="hero_4505_cv_15.prefab", voice1="hero_4505_cv_15.prefab", lines1="你呀，真会讨人开心……也许有一天，我真的会需要你的依靠，到了那一天，你会站在我身边吗，小~可~爱？"
},
	[901]={ lines="艾可来为你加油打气啦！一定要加油哦！艾可会帮你打起精神来的！", voice="hero_4507_cv_01.prefab", voice1="hero_4507_cv_01.prefab", lines1="艾可来为你加油打气啦！一定要加油哦！艾可会帮你打起精神来的！"
},
	[902]={ lines="DJ台和话筒已经调试好啦~", voice="hero_4507_cv_02.prefab", voice1="hero_4507_cv_02.prefab", lines1="DJ台和话筒已经调试好啦~"
},
	[903]={ lines="大家准备嗨起来吧！", voice="hero_4507_cv_03.prefab", voice1="hero_4507_cv_03.prefab", lines1="大家准备嗨起来吧！"
},
	[904]={ lines="来个急行板怎么样？", voice="hero_4507_cv_04.prefab", voice1="hero_4507_cv_04.prefab", lines1="来个急行板怎么样？"
},
	[905]={ lines="所有目光向我看齐！3！2！1！来听我的歌吧！", voice="hero_4507_cv_05.prefab", voice1="hero_4507_cv_05.prefab", lines1="所有目光向我看齐！3！2！1！来听我的歌吧！"
},
	[906]={ lines="谢谢！给你们最好的安可！", voice="hero_4507_cv_06.prefab", voice1="hero_4507_cv_06.prefab", lines1="谢谢！给你们最好的安可！"
},
	[907]={ lines="欢迎回来，来一首轻快的音乐如何？", voice="hero_4507_cv_07.prefab", voice1="hero_4507_cv_07.prefab", lines1="欢迎回来，来一首轻快的音乐如何？"
},
	[908]={ lines="谢谢大家的应援，艾可一定会更努力的！", voice="hero_4507_cv_08.prefab", voice1="hero_4507_cv_08.prefab", lines1="谢谢大家的应援，艾可一定会更努力的！"
},
	[909]={ lines="这一首歌是专门献给你们的，谢谢你们，艾可爱你哟~", voice="hero_4507_cv_09.prefab", voice1="hero_4507_cv_09.prefab", lines1="这一首歌是专门献给你们的，谢谢你们，艾可爱你哟~"
},
	[910]={ lines="嗯……有点饿了……不行不行，艾可要保持身材，通通飞走！", voice="hero_4507_cv_10.prefab", voice1="hero_4507_cv_10.prefab", lines1="嗯……有点饿了……不行不行，艾可要保持身材，通通飞走！"
},
	[911]={ lines="我的专长就是音乐和唱歌，不管是弹琴，编曲，清唱还是DJ、RAP，都难不倒我，但是上战场嘛，唔......感觉真不是偶像歌手擅长的事情呢！", voice="hero_4507_cv_11.prefab", voice1="hero_4507_cv_11.prefab", lines1="我的专长就是音乐和唱歌，不管是弹琴，编曲，清唱还是DJ、RAP，都难不倒我，但是上战场嘛，唔......感觉真不是偶像歌手擅长的事情呢！"
},
	[912]={ lines="想听什么？艾可都可以给你唱哦？", voice="hero_4507_cv_12.prefab", voice1="hero_4507_cv_12.prefab", lines1="想听什么？艾可都可以给你唱哦？"
},
	[913]={ lines="诶？你想知道我的过去吗？过去怎么样其实不重要啦，只要我现在过得很好，而且相信以后会越来越好，这就够了~", voice="hero_4507_cv_13.prefab", voice1="hero_4507_cv_13.prefab", lines1="诶？你想知道我的过去吗？过去怎么样其实不重要啦，只要我现在过得很好，而且相信以后会越来越好，这就够了~"
},
	[914]={ lines="我最紧张的一次演出？那应该是签约之后的正式出道演唱会吧，虽然我已经非常努力地练习了，但在后台还是紧张得手心出汗，所以我就在手心写了十个100然后一口气吃下去，哈哈哈，是不是好蠢？", voice="hero_4507_cv_14.prefab", voice1="hero_4507_cv_14.prefab", lines1="我最紧张的一次演出？那应该是签约之后的正式出道演唱会吧，虽然我已经非常努力地练习了，但在后台还是紧张得手心出汗，所以我就在手心写了十个100然后一口气吃下去，哈哈哈，是不是好蠢？"
},
	[915]={ lines="偷偷告诉你一件事情哦，你不要告诉别人。其实我并不太想走可爱的偶像歌手这条路线啦，但是公司一定要把我包装成这样，还说大家肯定会喜欢的……可是我还是想能有朝一日，成为一名成熟又有实力的歌手，你会支持我吗？", voice="hero_4507_cv_15.prefab", voice1="hero_4507_cv_15.prefab", lines1="偷偷告诉你一件事情哦，你不要告诉别人。其实我并不太想走可爱的偶像歌手这条路线啦，但是公司一定要把我包装成这样，还说大家肯定会喜欢的……可是我还是想能有朝一日，成为一名成熟又有实力的歌手，你会支持我吗？"
},
	[1001]={ lines="卡兰丽莎·兰斯洛特，以个人身份为你效劳。", voice="hero_4501_cv_01.prefab", voice1="hero_4501_cv_01.prefab", lines1="卡兰丽莎·兰斯洛特，以个人身份为你效劳。"
},
	[1002]={ lines="一枪，一个。", voice="hero_4501_cv_02.prefab", voice1="hero_4501_cv_02.prefab", lines1="一枪，一个。"
},
	[1003]={ lines="……太弱了。", voice="hero_4501_cv_03.prefab", voice1="hero_4501_cv_03.prefab", lines1="……太弱了。"
},
	[1004]={ lines="吃子弹吧！", voice="hero_4501_cv_04.prefab", voice1="hero_4501_cv_04.prefab", lines1="吃子弹吧！"
},
	[1005]={ lines="哼……就给你们一个痛快。", voice="hero_4501_cv_05.prefab", voice1="hero_4501_cv_05.prefab", lines1="哼……就给你们一个痛快。"
},
	[1006]={ lines="还不错。", voice="hero_4501_cv_06.prefab", voice1="hero_4501_cv_06.prefab", lines1="还不错。"
},
	[1007]={ lines="……你来得太慢了，再有下次，我就亲自去你的房间找你。", voice="hero_4501_cv_07.prefab", voice1="hero_4501_cv_07.prefab", lines1="……你来得太慢了，再有下次，我就亲自去你的房间找你。"
},
	[1008]={ lines="我不喜欢啰嗦，幸好你也是，让我省心了不少。", voice="hero_4501_cv_08.prefab", voice1="hero_4501_cv_08.prefab", lines1="我不喜欢啰嗦，幸好你也是，让我省心了不少。"
},
	[1009]={ lines="任务？我早已经准备好了，只需要你一声令下。", voice="hero_4501_cv_09.prefab", voice1="hero_4501_cv_09.prefab", lines1="任务？我早已经准备好了，只需要你一声令下。"
},
	[1010]={ lines="我们的合作还剩不少时间，你不需要有什么顾忌，尽管下命令吧。", voice="hero_4501_cv_10.prefab", voice1="hero_4501_cv_10.prefab", lines1="我们的合作还剩不少时间，你不需要有什么顾忌，尽管下命令吧。"
},
	[1011]={ lines="我的喜好？我认为你应该自己去找，才算有诚意。", voice="hero_4501_cv_11.prefab", voice1="hero_4501_cv_11.prefab", lines1="我的喜好？我认为你应该自己去找，才算有诚意。"
},
	[1012]={ lines="这个色号不错……你在记什么？——喜好？你这人，在这种事上倒是挺用心……", voice="hero_4501_cv_12.prefab", voice1="hero_4501_cv_12.prefab", lines1="这个色号不错……你在记什么？——喜好？你这人，在这种事上倒是挺用心……"
},
	[1013]={ lines="世界口红年鉴……给我的？你怎么知道……不，没什么，谢谢，我会好好收起来。", voice="hero_4501_cv_13.prefab", voice1="hero_4501_cv_13.prefab", lines1="世界口红年鉴……给我的？你怎么知道……不，没什么，谢谢，我会好好收起来。"
},
	[1014]={ lines="有没有感觉今天我哪里不太一样？嗯……不错，看出了我口红的色号，功课做得挺足嘛——刚好我需要买新的了，我允许你帮我挑一支，你可要好·好·挑·选才行，明白吗？", voice="hero_4501_cv_14.prefab", voice1="hero_4501_cv_14.prefab", lines1="有没有感觉今天我哪里不太一样？嗯……不错，看出了我口红的色号，功课做得挺足嘛——刚好我需要买新的了，我允许你帮我挑一支，你可要好·好·挑·选才行，明白吗？"
},
	[1015]={ lines="这把枪给你，是我自己亲手改装的，人在乱世总是需要一些护身装备——我……也做了不少功课，觉得这是最适合你的，收下它，不许拒绝。", voice="hero_4501_cv_15.prefab", voice1="hero_4501_cv_15.prefab", lines1="这把枪给你，是我自己亲手改装的，人在乱世总是需要一些护身装备——我……也做了不少功课，觉得这是最适合你的，收下它，不许拒绝。"
},
	[1016]={ lines="唔……这杯酒的味道是不是不太对……不信的话你尝一口？", voice="", voice1="hero_4501_cv_16.prefab", lines1="唔……这件衣服的尺寸怎么对不上，又掉下来……你什么时候来的？！你……看到了，对吧？！"
},
	[1017]={ lines="我的腿上是不是有虫子……真的有？！那快点帮我拍走它……", voice="", voice1="hero_4501_cv_17.prefab", lines1="我的腿上是不是有虫子……真的有？！那快点帮我拍走它……呀？！不是拍那里啊你这家伙！"
},
	[1018]={ lines="你……是不是很喜欢我这一身衣服？哼，废话，你那双眼睛都找不着道了……这么想看，还站在那干什么，坐·过·来——快点！", voice="", voice1="hero_4501_cv_18.prefab", lines1="你……是不是很喜欢我这一身衣服？哼，废话，你那双眼睛都找不着道了……这么想看，还站在那干什么，坐·过·来——快点！"
},
	[1101]={ lines="夜色中的阴影和梦魇，手持利刃的无言审判者，来自深渊的渡鸦——在此向您问好，链尉官。", voice="hero_4103_cv_01.prefab", voice1="hero_4103_cv_01.prefab", lines1="夜色中的阴影和梦魇，手持利刃的无言审判者，来自深渊的渡鸦——在此向您问好，链尉官。"
},
	[1102]={ lines="我即黑夜——", voice="hero_4103_cv_02.prefab", voice1="hero_4103_cv_02.prefab", lines1="我即黑夜——"
},
	[1103]={ lines="刃出必杀！", voice="hero_4103_cv_03.prefab", voice1="hero_4103_cv_03.prefab", lines1="刃出必杀！"
},
	[1104]={ lines="这把匕首能切割的，可不止是时间和空间！", voice="hero_4103_cv_04.prefab", voice1="hero_4103_cv_04.prefab", lines1="这把匕首能切割的，可不止是时间和空间！"
},
	[1105]={ lines="渡鸦振翼之时，炼狱即临！", voice="hero_4103_cv_05.prefab", voice1="hero_4103_cv_05.prefab", lines1="渡鸦振翼之时，炼狱即临！"
},
	[1106]={ lines="无尽的纷争，血腥的胜利……", voice="hero_4103_cv_06.prefab", voice1="hero_4103_cv_06.prefab", lines1="无尽的纷争，血腥的胜利……"
},
	[1107]={ lines="你好，准备好和我一起进入黑夜之中了吗？", voice="hero_4103_cv_07.prefab", voice1="hero_4103_cv_07.prefab", lines1="你好，准备好和我一起进入黑夜之中了吗？"
},
	[1108]={ lines="……一个苹果？它鲜红得仿佛生来就带着血液的剧毒，这确实符合我的美学……", voice="hero_4103_cv_08.prefab", voice1="hero_4103_cv_08.prefab", lines1="……一个苹果？它鲜红得仿佛生来就带着血液的剧毒，这确实符合我的美学……"
},
	[1109]={ lines="你该不会以为这把刀只是拿来耍着玩的吧？", voice="hero_4103_cv_09.prefab", voice1="hero_4103_cv_09.prefab", lines1="你该不会以为这把刀只是拿来耍着玩的吧？"
},
	[1110]={ lines="渡鸦的每一根羽毛都是一枚轻薄的利刃。", voice="hero_4103_cv_10.prefab", voice1="hero_4103_cv_10.prefab", lines1="渡鸦的每一根羽毛都是一枚轻薄的利刃。"
},
	[1111]={ lines="你最好不要打听太多关于我的事，知道得越多，对你越没有好处……", voice="hero_4103_cv_11.prefab", voice1="hero_4103_cv_11.prefab", lines1="你最好不要打听太多关于我的事，知道得越多，对你越没有好处……"
},
	[1112]={ lines="学生？那只是一个身份，用来掩饰而已——我表现得越像一个平凡、普通、毫无特色的女高中生，对我正在进行的伟大事业就越有帮助……", voice="hero_4103_cv_12.prefab", voice1="hero_4103_cv_12.prefab", lines1="学生？那只是一个身份，用来掩饰而已——我表现得越像一个平凡、普通、毫无特色的女高中生，对我正在进行的伟大事业就越有帮助……"
},
	[1113]={ lines="你知道世界上有一种被选中的人吗？我就是那一类——就算满身疮痍，也会在认定的那条路上一直走下去——我是，我就是，注定要成为“渡鸦”的那个人——", voice="hero_4103_cv_13.prefab", voice1="hero_4103_cv_13.prefab", lines1="你知道世界上有一种被选中的人吗？我就是那一类——就算满身疮痍，也会在认定的那条路上一直走下去——我是，我就是，注定要成为“渡鸦”的那个人——"
},
	[1114]={ lines="糖果？是什么让你以为我会喜欢这种小孩子才爱吃的东西……啊，你别拿走啊。就、就放在这里……也许有人会想吃呢？", voice="hero_4103_cv_14.prefab", voice1="hero_4103_cv_14.prefab", lines1="糖果？是什么让你以为我会喜欢这种小孩子才爱吃的东西……啊，你别拿走啊。就、就放在这里……也许有人会想吃呢？"
},
	[1115]={ lines="……《末影黎苏根》？……这小说是谁推荐给你的？啊不，我是，我是听说里面有个角色的名字和我的代号一样。你很喜欢这个角色？啊……嗯……没什么，就是问问，品味不错。", voice="hero_4103_cv_15.prefab", voice1="hero_4103_cv_15.prefab", lines1="……《末影黎苏根》？……这小说是谁推荐给你的？啊不，我是，我是听说里面有个角色的名字和我的代号一样。你很喜欢这个角色？啊……嗯……没什么，就是问问，品味不错。"
},
	[1201]={ lines="真是没想到，我们居然会有并肩作战的一天……既然命运如此，那就请你多~多~指~教~了——", voice="hero_4101_cv_01.prefab", voice1="hero_4101_cv_01.prefab", lines1="真是没想到，我们居然会有并肩作战的一天……既然命运如此，那就请你多~多~指~教~了——"
},
	[1202]={ lines="有谁想要被处刑了吗？", voice="hero_4101_cv_02.prefab", voice1="hero_4101_cv_02.prefab", lines1="有谁想要被处刑了吗？"
},
	[1203]={ lines="哈哈哈哈哈哈——消失吧！", voice="hero_4101_cv_03.prefab", voice1="hero_4101_cv_03.prefab", lines1="哈哈哈哈哈哈——消失吧！"
},
	[1204]={ lines="触电的感觉如何？！", voice="hero_4101_cv_04.prefab", voice1="hero_4101_cv_04.prefab", lines1="触电的感觉如何？！"
},
	[1205]={ lines="再坚持一下！坚持一下！坚持一下呀！", voice="hero_4101_cv_05.prefab", voice1="hero_4101_cv_05.prefab", lines1="再坚持一下！坚持一下！坚持一下呀！"
},
	[1206]={ lines="这么快就结束了，真没劲。", voice="hero_4101_cv_06.prefab", voice1="hero_4101_cv_06.prefab", lines1="这么快就结束了，真没劲。"
},
	[1207]={ lines="你今天的状态似乎还不错，呵——", voice="hero_4101_cv_07.prefab", voice1="hero_4101_cv_07.prefab", lines1="你今天的状态似乎还不错，呵——"
},
	[1208]={ lines="如果你惹我不高兴……我可不介意鞭策你。", voice="hero_4101_cv_08.prefab", voice1="hero_4101_cv_08.prefab", lines1="如果你惹我不高兴……我可不介意鞭策你。"
},
	[1209]={ lines="怪物？很多人这么称呼我，我根本不会介意，还是说，你也和他们一样？", voice="hero_4101_cv_09.prefab", voice1="hero_4101_cv_09.prefab", lines1="怪物？很多人这么称呼我，我根本不会介意，还是说，你也和他们一样？"
},
	[1210]={ lines="想要看我的羽毛？可以——才怪，你怎么会有这种想法，想被“鞭策”一下吗。", voice="hero_4101_cv_10.prefab", voice1="hero_4101_cv_10.prefab", lines1="想要看我的羽毛？可以——才怪，你怎么会有这种想法，想被“鞭策”一下吗。"
},
	[1211]={ lines="基于我们彼此的身份，别和我走得太近，以免出现问题。", voice="hero_4101_cv_11.prefab", voice1="hero_4101_cv_11.prefab", lines1="基于我们彼此的身份，别和我走得太近，以免出现问题。"
},
	[1212]={ lines="站在我们俩组织的立场上，我不能和你交流太多东西，但如果不涉及机密的话……倒是无妨。", voice="hero_4101_cv_12.prefab", voice1="hero_4101_cv_12.prefab", lines1="站在我们俩组织的立场上，我不能和你交流太多东西，但如果不涉及机密的话……倒是无妨。"
},
	[1213]={ lines="不要妄想向我打探我们的事情，我会在这里和你并肩作战只是我个人的意愿，你 明 白 这 点 吗？！", voice="hero_4101_cv_13.prefab", voice1="hero_4101_cv_13.prefab", lines1="不要妄想向我打探我们的事情，我会在这里和你并肩作战只是我个人的意愿，你 明 白 这 点 吗？！"
},
	[1214]={ lines="我不介意别人叫我怪物，但如果你也这么认为……我只会……啊不，我不会很难过，只是会感到更生气，更 生 气 而 已——", voice="hero_4101_cv_14.prefab", voice1="hero_4101_cv_14.prefab", lines1="我不介意别人叫我怪物，但如果你也这么认为……我只会……啊不，我不会很难过，只是会感到更生气，更 生 气 而 已——"
},
	[1215]={ lines="别这么看着我……我并没有什么想和你说的，只不过……啊、没，没什么，你别想多了……", voice="hero_4101_cv_15.prefab", voice1="hero_4101_cv_15.prefab", lines1="别这么看着我……我并没有什么想和你说的，只不过……啊、没，没什么，你别想多了……"
},
	[1301]={ lines="莱蔻莎向你问好，嗯？我的笑容很可怕？哪有~", voice="hero_4107_cv_01.prefab", voice1="hero_4107_cv_01.prefab", lines1="莱蔻莎向你问好，嗯？我的笑容很可怕？哪有~"
},
	[1302]={ lines="已经……迫不及待了呢……", voice="hero_4107_cv_02.prefab", voice1="hero_4107_cv_02.prefab", lines1="已经……迫不及待了呢……"
},
	[1303]={ lines="真好玩！", voice="hero_4107_cv_03.prefab", voice1="hero_4107_cv_03.prefab", lines1="真好玩！"
},
	[1304]={ lines="好好享受吧~", voice="hero_4107_cv_04.prefab", voice1="hero_4107_cv_04.prefab", lines1="好好享受吧~"
},
	[1305]={ lines="和蛛丝玩玩吧，哈哈哈哈——", voice="hero_4107_cv_05.prefab", voice1="hero_4107_cv_05.prefab", lines1="和蛛丝玩玩吧，哈哈哈哈——"
},
	[1306]={ lines="这就结束了？啧……", voice="hero_4107_cv_06.prefab", voice1="hero_4107_cv_06.prefab", lines1="这就结束了？啧……"
},
	[1307]={ lines="你好呀~今天想和我玩什么呢？", voice="hero_4107_cv_07.prefab", voice1="hero_4107_cv_07.prefab", lines1="你好呀~今天想和我玩什么呢？"
},
	[1308]={ lines="今天要玩什么呢？玩~什~么呢？呵呵呵呵……", voice="hero_4107_cv_08.prefab", voice1="hero_4107_cv_08.prefab", lines1="今天要玩什么呢？玩~什~么呢？呵呵呵呵……"
},
	[1309]={ lines="你可不要在我做事的时候……扫~我~的~兴~哦~", voice="hero_4107_cv_09.prefab", voice1="hero_4107_cv_09.prefab", lines1="你可不要在我做事的时候……扫~我~的~兴~哦~"
},
	[1310]={ lines="呵呵……呵哈哈哈哈……切割东西的时候……总是忍不住……哈哈哈……", voice="hero_4107_cv_10.prefab", voice1="hero_4107_cv_10.prefab", lines1="呵呵……呵哈哈哈哈……切割东西的时候……总是忍不住……哈哈哈……"
},
	[1311]={ lines="你的眼睛……很漂亮……啊，只是单纯的夸奖而已哦？不要想歪了~", voice="hero_4107_cv_11.prefab", voice1="hero_4107_cv_11.prefab", lines1="你的眼睛……很漂亮……啊，只是单纯的夸奖而已哦？不要想歪了~"
},
	[1312]={ lines="我的职责，主要是铲……哦不，应该说“解决”一些肮脏、危险，且不适宜让大众知晓的“东西”，放心~你不在那个分类里。", voice="hero_4107_cv_12.prefab", voice1="hero_4107_cv_12.prefab", lines1="我的职责，主要是铲……哦不，应该说“解决”一些肮脏、危险，且不适宜让大众知晓的“东西”，放心~你不在那个分类里。"
},
	[1313]={ lines="你和我随时都是可以死的，但那应该不是我和你该有的未来，呵？听起来有哲理？大概吧，呵呵呵……", voice="hero_4107_cv_13.prefab", voice1="hero_4107_cv_13.prefab", lines1="你和我随时都是可以死的，但那应该不是我和你该有的未来，呵？听起来有哲理？大概吧，呵呵呵……"
},
	[1314]={ lines="世间万物是很离奇的，有钱的人大多很蠢，聪明的人更多痴愚，坚强的人很容易击溃，柔弱的人往往能活很久……那你呢，你是哪一种？是能让我感兴趣的那一种吗？呵呵呵呵……", voice="hero_4107_cv_14.prefab", voice1="hero_4107_cv_14.prefab", lines1="世间万物是很离奇的，有钱的人大多很蠢，聪明的人更多痴愚，坚强的人很容易击溃，柔弱的人往往能活很久……那你呢，你是哪一种？是能让我感兴趣的那一种吗？呵呵呵呵……"
},
	[1315]={ lines="觉得我有些时候的发言很老气？呵？你怎么会有这种想法？想知道我的真实年龄？哈哈哈哈——把耳朵凑过来~", voice="hero_4107_cv_15.prefab", voice1="hero_4107_cv_15.prefab", lines1="觉得我有些时候的发言很老气？呵？你怎么会有这种想法？想知道我的真实年龄？哈哈哈哈——把耳朵凑过来~"
},
	[1401]={ lines="狮刃前来报到！准备好了吗？马上开始战斗训练吧，时间可是不会等人的！", voice="hero_3102_cv_01.prefab", voice1="hero_3102_cv_01.prefab", lines1="狮刃前来报到！准备好了吗？马上开始战斗训练吧，时间可是不会等人的！"
},
	[1402]={ lines="红狮已蓄势待发！", voice="hero_3102_cv_02.prefab", voice1="hero_3102_cv_02.prefab", lines1="红狮已蓄势待发！"
},
	[1403]={ lines="上吧！喝啊——", voice="hero_3102_cv_03.prefab", voice1="hero_3102_cv_03.prefab", lines1="上吧！喝啊——"
},
	[1404]={ lines="这里就——交给我——", voice="hero_3102_cv_04.prefab", voice1="hero_3102_cv_04.prefab", lines1="这里就——交给我——"
},
	[1405]={ lines="一刀——两段！", voice="hero_3102_cv_05.prefab", voice1="hero_3102_cv_05.prefab", lines1="一刀——两段！"
},
	[1406]={ lines="训练的成果就是这样。", voice="hero_3102_cv_06.prefab", voice1="hero_3102_cv_06.prefab", lines1="训练的成果就是这样。"
},
	[1407]={ lines="今天状态很好嘛，正是适合训练的精气神。", voice="hero_3102_cv_07.prefab", voice1="hero_3102_cv_07.prefab", lines1="今天状态很好嘛，正是适合训练的精气神。"
},
	[1408]={ lines="人啊……只要不活动身体就会生锈，来，赶紧和我一起展开训练。", voice="hero_3102_cv_08.prefab", voice1="hero_3102_cv_08.prefab", lines1="人啊……只要不活动身体就会生锈，来，赶紧和我一起展开训练。"
},
	[1409]={ lines="有点累了……先来一口罢……啥？酒？功能饮料而已。", voice="hero_3102_cv_09.prefab", voice1="hero_3102_cv_09.prefab", lines1="有点累了……先来一口罢……啥？酒？功能饮料而已。"
},
	[1410]={ lines="进行训练之前要先放松身体，以免拉伤。", voice="hero_3102_cv_10.prefab", voice1="hero_3102_cv_10.prefab", lines1="进行训练之前要先放松身体，以免拉伤。"
},
	[1411]={ lines="最近一批新人的素质还算不错，如果心理承受能力再强一点就更好了，唉……不是每个人都像你一样皮实。", voice="hero_3102_cv_11.prefab", voice1="hero_3102_cv_11.prefab", lines1="最近一批新人的素质还算不错，如果心理承受能力再强一点就更好了，唉……不是每个人都像你一样皮实。"
},
	[1412]={ lines="即便是纪律再严明的军队，也会有出现腐坏的可能，并滋生出背叛和罪恶——你说莱斯坦斯不是这样？希望如此……", voice="hero_3102_cv_12.prefab", voice1="hero_3102_cv_12.prefab", lines1="即便是纪律再严明的军队，也会有出现腐坏的可能，并滋生出背叛和罪恶——你说莱斯坦斯不是这样？希望如此……"
},
	[1413]={ lines="以前的事？绝大多数都是些不堪回首的东西……向我道歉干什么？这又不是什么记忆创伤，再说了，如果这都不能直面，还怎么当你们的教官啊？", voice="hero_3102_cv_13.prefab", voice1="hero_3102_cv_13.prefab", lines1="以前的事？绝大多数都是些不堪回首的东西……向我道歉干什么？这又不是什么记忆创伤，再说了，如果这都不能直面，还怎么当你们的教官啊？"
},
	[1414]={ lines="尝尝这个吧，是我家乡的酒，就当是工作结束之后的犒劳吧，训练固然重要，但适当的放松也不可错过。受不了这个烈度？你也太菜了，哈哈哈哈……", voice="hero_3102_cv_14.prefab", voice1="hero_3102_cv_14.prefab", lines1="尝尝这个吧，是我家乡的酒，就当是工作结束之后的犒劳吧，训练固然重要，但适当的放松也不可错过。受不了这个烈度？你也太菜了，哈哈哈哈……"
},
	[1415]={ lines="和你一起训练也好，一起出任务也好，都会让我回想起那些曾经在军队的日子，虽然已经放下了过去，但那些仅有的美好回忆能被一点点重拾起来，真的，很感激你。", voice="hero_3102_cv_15.prefab", voice1="hero_3102_cv_15.prefab", lines1="和你一起训练也好，一起出任务也好，都会让我回想起那些曾经在军队的日子，虽然已经放下了过去，但那些仅有的美好回忆能被一点点重拾起来，真的，很感激你。"
},
	[1501]={ lines="莱斯坦斯安全局所属，棱镜，向你报到，如果可以的话，请给我安排一个有冷气的房间。", voice="hero_3105_cv_01.prefab", voice1="hero_3105_cv_01.prefab", lines1="莱斯坦斯安全局所属，棱镜，向你报到，如果可以的话，请给我安排一个有冷气的房间。"
},
	[1502]={ lines="我们已准备就绪。", voice="hero_3105_cv_02.prefab", voice1="hero_3105_cv_02.prefab", lines1="我们已准备就绪。"
},
	[1503]={ lines="纳西索斯——", voice="hero_3105_cv_03.prefab", voice1="hero_3105_cv_03.prefab", lines1="纳西索斯——"
},
	[1504]={ lines="纳西索斯，和我一起——", voice="hero_3105_cv_04.prefab", voice1="hero_3105_cv_04.prefab", lines1="纳西索斯，和我一起——"
},
	[1505]={ lines="消失在……我和纳西索斯的剑光下吧——", voice="hero_3105_cv_05.prefab", voice1="hero_3105_cv_05.prefab", lines1="消失在……我和纳西索斯的剑光下吧——"
},
	[1506]={ lines="我们的胜利是理所当然的。", voice="hero_3105_cv_06.prefab", voice1="hero_3105_cv_06.prefab", lines1="我们的胜利是理所当然的。"
},
	[1507]={ lines="你好，今天的冷气开得很足，我很喜欢。", voice="hero_3105_cv_07.prefab", voice1="hero_3105_cv_07.prefab", lines1="你好，今天的冷气开得很足，我很喜欢。"
},
	[1508]={ lines="纳西索斯的新衣服……应该怎么做呢……", voice="hero_3105_cv_08.prefab", voice1="hero_3105_cv_08.prefab", lines1="纳西索斯的新衣服……应该怎么做呢……"
},
	[1509]={ lines="我说了不要在我的房间里放暖炉，你怎么讲不听，气死我了。", voice="hero_3105_cv_09.prefab", voice1="hero_3105_cv_09.prefab", lines1="我说了不要在我的房间里放暖炉，你怎么讲不听，气死我了。"
},
	[1510]={ lines="（应该给纳西索斯设计一个新身体吗……哇！你干嘛突然出现，吓死我了……）", voice="hero_3105_cv_10.prefab", voice1="hero_3105_cv_10.prefab", lines1="（应该给纳西索斯设计一个新身体吗……哇！你干嘛突然出现，吓死我了……）"
},
	[1511]={ lines="人类的情绪，真的是非常复杂的东西。如果一切情绪都可以遵循某种程式稳定地运行就好了——", voice="hero_3105_cv_11.prefab", voice1="hero_3105_cv_11.prefab", lines1="人类的情绪，真的是非常复杂的东西。如果一切情绪都可以遵循某种程式稳定地运行就好了——"
},
	[1512]={ lines="啊，不，我不觉得冷，低温有助于我的思考……如果你觉得太冷的话，可以让纳西索斯把挂在那边的大衣拿过来。", voice="hero_3105_cv_12.prefab", voice1="hero_3105_cv_12.prefab", lines1="啊，不，我不觉得冷，低温有助于我的思考……如果你觉得太冷的话，可以让纳西索斯把挂在那边的大衣拿过来。"
},
	[1513]={ lines="你好呀，我是纳西索斯，米歇斯从小就一直陪着我，她创造了我，我也塑造了她，请你一定要跟她做好朋友哦~", voice="hero_3105_cv_13.prefab", voice1="hero_3105_cv_13.prefab", lines1="你好呀，我是纳西索斯，米歇斯从小就一直陪着我，她创造了我，我也塑造了她，请你一定要跟她做好朋友哦~"
},
	[1514]={ lines="……人偶？是的，我有很多，你也对人偶感兴趣吗？如果你不介意的话，我很乐意向你展示一下我的收藏——", voice="hero_3105_cv_14.prefab", voice1="hero_3105_cv_14.prefab", lines1="……人偶？是的，我有很多，你也对人偶感兴趣吗？如果你不介意的话，我很乐意向你展示一下我的收藏——"
},
	[1515]={ lines="说实话，即使在人群中，我也很难体验到与同类共处的感觉。不过，链尉官，你是例外，纳西索斯对你的评价很高，我会努力和你好好相处的。", voice="hero_3105_cv_15.prefab", voice1="hero_3105_cv_15.prefab", lines1="说实话，即使在人群中，我也很难体验到与同类共处的感觉。不过，链尉官，你是例外，纳西索斯对你的评价很高，我会努力和你好好相处的。"
},
	[1601]={ lines="艾维洛娜，代号野马，要来试试我的机车吗？是我自己组装的哦。", voice="hero_3107_cv_01.prefab", voice1="hero_3107_cv_01.prefab", lines1="艾维洛娜，代号野马，要来试试我的机车吗？是我自己组装的哦。"
},
	[1602]={ lines="我的引擎已经发动好啦！", voice="hero_3107_cv_02.prefab", voice1="hero_3107_cv_02.prefab", lines1="我的引擎已经发动好啦！"
},
	[1603]={ lines="尝尝我的厉害吧！", voice="hero_3107_cv_03.prefab", voice1="hero_3107_cv_03.prefab", lines1="尝尝我的厉害吧！"
},
	[1604]={ lines="别拦路！", voice="hero_3107_cv_04.prefab", voice1="hero_3107_cv_04.prefab", lines1="别拦路！"
},
	[1605]={ lines="在我的赛道里被碾碎吧！", voice="hero_3107_cv_05.prefab", voice1="hero_3107_cv_05.prefab", lines1="在我的赛道里被碾碎吧！"
},
	[1606]={ lines="这不是很简单的事情嘛？", voice="hero_3107_cv_06.prefab", voice1="hero_3107_cv_06.prefab", lines1="这不是很简单的事情嘛？"
},
	[1607]={ lines="嘿，你好呀，要不要我教你骑独轮机车呀，很简单的。", voice="hero_3107_cv_07.prefab", voice1="hero_3107_cv_07.prefab", lines1="嘿，你好呀，要不要我教你骑独轮机车呀，很简单的。"
},
	[1608]={ lines="给你来一个我的冠军签名。嗯！写得真不错！", voice="hero_3107_cv_08.prefab", voice1="hero_3107_cv_08.prefab", lines1="给你来一个我的冠军签名。嗯！写得真不错！"
},
	[1609]={ lines="听说一般人可做不到这个动作，你也是这样吗，哼哼~我是不是很厉害！", voice="hero_3107_cv_09.prefab", voice1="hero_3107_cv_09.prefab", lines1="听说一般人可做不到这个动作，你也是这样吗，哼哼~我是不是很厉害！"
},
	[1610]={ lines="超速罚单？不……不好意思！下次我会注意的！", voice="hero_3107_cv_10.prefab", voice1="hero_3107_cv_10.prefab", lines1="超速罚单？不……不好意思！下次我会注意的！"
},
	[1611]={ lines="独轮机车真是最完美的交通工具了，又简单，又方便，想在哪儿骑就在哪儿骑，还容易学！不信的话，你来试一试？", voice="hero_3107_cv_11.prefab", voice1="hero_3107_cv_11.prefab", lines1="独轮机车真是最完美的交通工具了，又简单，又方便，想在哪儿骑就在哪儿骑，还容易学！不信的话，你来试一试？"
},
	[1612]={ lines="不瞒你说，以前我可是镇里出了名的不良少女哦，看不出来吧？", voice="hero_3107_cv_12.prefab", voice1="hero_3107_cv_12.prefab", lines1="不瞒你说，以前我可是镇里出了名的不良少女哦，看不出来吧？"
},
	[1613]={ lines="每个人都有要背负的责任，随着时间的增长，可能要背负的东西会越来越多，你怎么看？噢，不说也没关系，我只是随口说说罢了~", voice="hero_3107_cv_13.prefab", voice1="hero_3107_cv_13.prefab", lines1="每个人都有要背负的责任，随着时间的增长，可能要背负的东西会越来越多，你怎么看？噢，不说也没关系，我只是随口说说罢了~"
},
	[1614]={ lines="你有试过在漆黑一片的荒野里兜风吗？很爽快的，当你跑起来，压力和负面情绪都会全部被吹飞！是真的！下次我带你一起去感受一下！", voice="hero_3107_cv_14.prefab", voice1="hero_3107_cv_14.prefab", lines1="你有试过在漆黑一片的荒野里兜风吗？很爽快的，当你跑起来，压力和负面情绪都会全部被吹飞！是真的！下次我带你一起去感受一下！"
},
	[1615]={ lines="不怕你笑话我，其实我一直想回到赛道上，再拿一个冠军……诶？我没有伤心啦，因为现在我的身边还有你们嘛，遗憾这种事，就让他随风去吧。", voice="hero_3107_cv_15.prefab", voice1="hero_3107_cv_15.prefab", lines1="不怕你笑话我，其实我一直想回到赛道上，再拿一个冠军……诶？我没有伤心啦，因为现在我的身边还有你们嘛，遗憾这种事，就让他随风去吧。"
},
	[1701]={ lines="您好，我是来传递大地母亲信息的信使，叫我狄俄涅就好，愿大地母亲赐予您祝福——", voice="hero_3104_cv_01.prefab", voice1="hero_3104_cv_01.prefab", lines1="您好，我是来传递大地母亲信息的信使，叫我狄俄涅就好，愿大地母亲赐予您祝福——"
},
	[1702]={ lines="我代表着大地的意志。", voice="hero_3104_cv_02.prefab", voice1="hero_3104_cv_02.prefab", lines1="我代表着大地的意志。"
},
	[1703]={ lines="退下！", voice="hero_3104_cv_03.prefab", voice1="hero_3104_cv_03.prefab", lines1="退下！"
},
	[1704]={ lines="大地母亲，赐我力量——", voice="hero_3104_cv_04.prefab", voice1="hero_3104_cv_04.prefab", lines1="大地母亲，赐我力量——"
},
	[1705]={ lines="这是——来自大地的护佑——", voice="hero_3104_cv_05.prefab", voice1="hero_3104_cv_05.prefab", lines1="这是——来自大地的护佑——"
},
	[1706]={ lines="辛苦大家了，来喝杯茶吧。", voice="hero_3104_cv_06.prefab", voice1="hero_3104_cv_06.prefab", lines1="辛苦大家了，来喝杯茶吧。"
},
	[1707]={ lines="欢迎回来，愿大地母亲赐您祝福。", voice="hero_3104_cv_07.prefab", voice1="hero_3104_cv_07.prefab", lines1="欢迎回来，愿大地母亲赐您祝福。"
},
	[1708]={ lines="为了大地母亲，我将身先士卒，您能和我一起来吗？", voice="hero_3104_cv_08.prefab", voice1="hero_3104_cv_08.prefab", lines1="为了大地母亲，我将身先士卒，您能和我一起来吗？"
},
	[1709]={ lines="让您看一个有意思的东西，如何，是不是感觉到大地母亲的伟力了？", voice="hero_3104_cv_09.prefab", voice1="hero_3104_cv_09.prefab", lines1="让您看一个有意思的东西，如何，是不是感觉到大地母亲的伟力了？"
},
	[1710]={ lines="对于那些亵渎大地母亲的人，我将不遗余力将其驱逐——", voice="hero_3104_cv_10.prefab", voice1="hero_3104_cv_10.prefab", lines1="对于那些亵渎大地母亲的人，我将不遗余力将其驱逐——"
},
	[1711]={ lines="作为大地之母的祭司，我所要做的，就是将地母的伟力与慈爱传播到所有人的心中，为此，我将走遍世界各地的每个角落。您觉得这很难？不，不难，只要有信念的话。", voice="hero_3104_cv_11.prefab", voice1="hero_3104_cv_11.prefab", lines1="作为大地之母的祭司，我所要做的，就是将地母的伟力与慈爱传播到所有人的心中，为此，我将走遍世界各地的每个角落。您觉得这很难？不，不难，只要有信念的话。"
},
	[1712]={ lines="链尉官，您好，如果您愿意的话，要不要和我一起去郊外远行？一定会让您的心情愉悦起来。", voice="hero_3104_cv_12.prefab", voice1="hero_3104_cv_12.prefab", lines1="链尉官，您好，如果您愿意的话，要不要和我一起去郊外远行？一定会让您的心情愉悦起来。"
},
	[1713]={ lines="唉？我从来没有和您说过大地之母的教义吗？呵呵，虽然很想告诉您，但现在还不是时候——等您认同我们的理念，并自愿成为我们的同路人的时候，我会把一切都告诉您的。", voice="hero_3104_cv_13.prefab", voice1="hero_3104_cv_13.prefab", lines1="唉？我从来没有和您说过大地之母的教义吗？呵呵，虽然很想告诉您，但现在还不是时候——等您认同我们的理念，并自愿成为我们的同路人的时候，我会把一切都告诉您的。"
},
	[1714]={ lines="我为什么会加入大地之母教派？您这问题可是很敏感啊——但是告诉您也无妨，我是出生在荒野之中的遗民，在我年幼无助时，教派接纳了我，并抚养我长大，很俗套吧，就是这么简单的一个故事，呵呵——", voice="hero_3104_cv_14.prefab", voice1="hero_3104_cv_14.prefab", lines1="我为什么会加入大地之母教派？您这问题可是很敏感啊——但是告诉您也无妨，我是出生在荒野之中的遗民，在我年幼无助时，教派接纳了我，并抚养我长大，很俗套吧，就是这么简单的一个故事，呵呵——"
},
	[1715]={ lines="永夜化隔绝了日光、星光和月光，让大地之母为之哭泣，啊，您不用这么紧张，我和那些想要毁掉空天星链的暴徒们不同，仁慈的大地之母不会因为自己的悲伤而想要毁灭她的子民们，她只是想要让他们感受到她的悲伤，仅此而已。", voice="hero_3104_cv_15.prefab", voice1="hero_3104_cv_15.prefab", lines1="永夜化隔绝了日光、星光和月光，让大地之母为之哭泣，啊，您不用这么紧张，我和那些想要毁掉空天星链的暴徒们不同，仁慈的大地之母不会因为自己的悲伤而想要毁灭她的子民们，她只是想要让他们感受到她的悲伤，仅此而已。"
},
	[1801]={ lines="我叫言，是圆梦人事务所派来的，请多指教。", voice="hero_3108_cv_01.prefab", voice1="hero_3108_cv_01.prefab", lines1="我叫言，是圆梦人事务所派来的，请多指教。"
},
	[1802]={ lines="只是代你打架的话……", voice="hero_3108_cv_02.prefab", voice1="hero_3108_cv_02.prefab", lines1="只是代你打架的话……"
},
	[1803]={ lines="剑来——无量——", voice="hero_3108_cv_03.prefab", voice1="hero_3108_cv_03.prefab", lines1="剑来——无量——"
},
	[1804]={ lines="七杀——骤雨——", voice="hero_3108_cv_04.prefab", voice1="hero_3108_cv_04.prefab", lines1="七杀——骤雨——"
},
	[1805]={ lines="邪物，必被诛之——", voice="hero_3108_cv_05.prefab", voice1="hero_3108_cv_05.prefab", lines1="邪物，必被诛之——"
},
	[1806]={ lines="嗯，身手没有退步……", voice="hero_3108_cv_06.prefab", voice1="hero_3108_cv_06.prefab", lines1="嗯，身手没有退步……"
},
	[1807]={ lines="你好呀，看你神色甚好，今晚定可安眠呢。", voice="hero_3108_cv_07.prefab", voice1="hero_3108_cv_07.prefab", lines1="你好呀，看你神色甚好，今晚定可安眠呢。"
},
	[1808]={ lines="想看御剑？真是奇怪……明明不是什么了不得的东西……", voice="hero_3108_cv_08.prefab", voice1="hero_3108_cv_08.prefab", lines1="想看御剑？真是奇怪……明明不是什么了不得的东西……"
},
	[1809]={ lines="（师姐交代要经常练字，不能生了手……嗯……还行，没退步，嘿嘿——）", voice="hero_3108_cv_09.prefab", voice1="hero_3108_cv_09.prefab", lines1="（师姐交代要经常练字，不能生了手……嗯……还行，没退步，嘿嘿——）"
},
	[1810]={ lines="又要看御剑？唉呀……你这么想学干脆我教你得了——不对，不是内门弟子不能学这个……", voice="hero_3108_cv_10.prefab", voice1="hero_3108_cv_10.prefab", lines1="又要看御剑？唉呀……你这么想学干脆我教你得了——不对，不是内门弟子不能学这个……"
},
	[1811]={ lines="有什么事吗？东方的宝石？想让我看看是什么？哦……一块不错的籽料，虽然不算值钱，但多盘盘应该也挺润的，盘是什么意思？润又是什么意思？嗯……这个我不太好一下子和你解释清楚……", voice="hero_3108_cv_11.prefab", voice1="hero_3108_cv_11.prefab", lines1="有什么事吗？东方的宝石？想让我看看是什么？哦……一块不错的籽料，虽然不算值钱，但多盘盘应该也挺润的，盘是什么意思？润又是什么意思？嗯……这个我不太好一下子和你解释清楚……"
},
	[1812]={ lines="你把那块玉盘出来了？让我看看……什么呀，这才哪到哪啊？我让你看看什么才是正经的“盘”，瞧好了——", voice="hero_3108_cv_12.prefab", voice1="hero_3108_cv_12.prefab", lines1="你把那块玉盘出来了？让我看看……什么呀，这才哪到哪啊？我让你看看什么才是正经的“盘”，瞧好了——"
},
	[1813]={ lines="想和我学“武术”？你确定？嗯……虽然我们门派没规定说外游弟子不得收徒，但是……感觉你身子骨不是很行啊？这么着吧，你先去锻炼锻炼，到时候我再来测测你怎么样？", voice="hero_3108_cv_13.prefab", voice1="hero_3108_cv_13.prefab", lines1="想和我学“武术”？你确定？嗯……虽然我们门派没规定说外游弟子不得收徒，但是……感觉你身子骨不是很行啊？这么着吧，你先去锻炼锻炼，到时候我再来测测你怎么样？"
},
	[1814]={ lines="哦？不错嘛，居然能一口气跑这么久，看来你是真下功夫了，还带了……喔唷？烧刀酒？你从哪里弄到的？哈哈哈……你很上道嘛，好好好，我就当你的师父罢，今晚我们喝个痛快——", voice="hero_3108_cv_14.prefab", voice1="hero_3108_cv_14.prefab", lines1="哦？不错嘛，居然能一口气跑这么久，看来你是真下功夫了，还带了……喔唷？烧刀酒？你从哪里弄到的？哈哈哈……你很上道嘛，好好好，我就当你的师父罢，今晚我们喝个痛快——"
},
	[1815]={ lines="我……完全不记得我上次喝醉后的情况了，你和我说一下究竟发生了什么事……什么？！不可能！完全不可能！我不会说这样的话！我不信！除非下次你拍视频————", voice="hero_3108_cv_15.prefab", voice1="hero_3108_cv_15.prefab", lines1="我……完全不记得我上次喝醉后的情况了，你和我说一下究竟发生了什么事……什么？！不可能！完全不可能！我不会说这样的话！我不信！除非下次你拍视频————"
},
	[1816]={ lines="我，我还是第一次穿这样的衣服……所以姑且选了个比较喜欢的样式……话说回来，你还要看到什么时候？一直看下去？……唉，假期可是很短暂的哦？", voice="", voice1="hero_3108_cv_16.prefab", lines1="我，我还是第一次穿这样的衣服……所以姑且选了个比较喜欢的样式……话说回来，你还要看到什么时候？一直看下去？……唉，假期可是很短暂的哦？"
},
	[1817]={ lines="链尉官，要是热的话就喝这杯饮料吧，我加了一些防暑的药酒进去，味道我试过了，还不错。", voice="", voice1="hero_3108_cv_17.prefab", lines1="链尉官，要是热的话就喝这杯饮料吧，我加了一些防暑的药酒进去，味道我试过了，还不错。"
},
	[1818]={ lines="海风明明很清爽，沙滩上也没有人在看着，为什么我的脸还是会这么烫……清心，清心……链尉官？！你什么时候出现在我身后的！", voice="", voice1="hero_3108_cv_18.prefab", lines1="海风明明很清爽，沙滩上也没有人在看着，为什么我的脸还是会这么烫……清心，清心……链尉官？！你什么时候出现在我身后的……还，捏着我的腰……！"
},
	[1901]={ lines="我是谁？哼，连本小姐都不认识，真没见识——听好了，本小姐叫弗洛尼可·拉蒂夫，拉蒂夫这个姓氏，你总该听过吧？", voice="hero_3503_cv_01.prefab", voice1="hero_3503_cv_01.prefab", lines1="我是谁？哼，连本小姐都不认识，真没见识——听好了，本小姐叫弗洛尼可·拉蒂夫，拉蒂夫这个姓氏，你总该听过吧？"
},
	[1902]={ lines="本小姐就勉为其难地接受你的调度吧。", voice="hero_3503_cv_02.prefab", voice1="hero_3503_cv_02.prefab", lines1="本小姐就勉为其难地接受你的调度吧。"
},
	[1903]={ lines="给本小姐退下！", voice="hero_3503_cv_03.prefab", voice1="hero_3503_cv_03.prefab", lines1="给本小姐退下！"
},
	[1904]={ lines="希里，赶紧把他干掉——", voice="hero_3503_cv_04.prefab", voice1="hero_3503_cv_04.prefab", lines1="希里，赶紧把他干掉——"
},
	[1905]={ lines="就让你们看一看，本小姐华丽的优雅——", voice="hero_3503_cv_05.prefab", voice1="hero_3503_cv_05.prefab", lines1="就让你们看一看，本小姐华丽的优雅——"
},
	[1906]={ lines="有本小姐在，胜利不是轻轻松松？", voice="hero_3503_cv_06.prefab", voice1="hero_3503_cv_06.prefab", lines1="有本小姐在，胜利不是轻轻松松？"
},
	[1907]={ lines="现在才来？哼，这个点，本小姐可是已经上完礼仪课了哦。", voice="hero_3503_cv_07.prefab", voice1="hero_3503_cv_07.prefab", lines1="现在才来？哼，这个点，本小姐可是已经上完礼仪课了哦。"
},
	[1908]={ lines="“呜哇，好大的雷声……”“小姐别怕，希里会一直在这里陪着你。”", voice="hero_3503_cv_08.prefab", voice1="hero_3503_cv_08.prefab", lines1="“呜哇，好大的雷声……”“小姐别怕，希里会一直在这里陪着你。”"
},
	[1909]={ lines="“哼，谁敢说本小姐亲自设计的服装不好看？让我看看是谁这么不长眼？”“小姐的眼光自然是最好的。”", voice="hero_3503_cv_09.prefab", voice1="hero_3503_cv_09.prefab", lines1="“哼，谁敢说本小姐亲自设计的服装不好看？让我看看是谁这么不长眼？”“小姐的眼光自然是最好的。”"
},
	[1910]={ lines="“嗯？每日进货量……耗损率？希里——”“交给我吧，小姐——您好，接下来，请允许我来为阁下说明。”", voice="hero_3503_cv_10.prefab", voice1="hero_3503_cv_10.prefab", lines1="“嗯？每日进货量……耗损率？希里——”“交给我吧，小姐——您好，接下来，请允许我来为阁下说明。”"
},
	[1911]={ lines="想要本小姐帮忙？可以哦！不过，在那之前……你的诚意呢？", voice="hero_3503_cv_11.prefab", voice1="hero_3503_cv_11.prefab", lines1="想要本小姐帮忙？可以哦！不过，在那之前……你的诚意呢？"
},
	[1912]={ lines="今年父亲把宝石展览交给本小姐来准备……唔……想起来就头疼。到时候你会帮我的吧？嗯？诚意？喂喂，你也太记仇了吧！", voice="hero_3503_cv_12.prefab", voice1="hero_3503_cv_12.prefab", lines1="今年父亲把宝石展览交给本小姐来准备……唔……想起来就头疼。到时候你会帮我的吧？嗯？诚意？喂喂，你也太记仇了吧！"
},
	[1913]={ lines="身为拉蒂夫家族的一员，本小姐的一言一行即是优雅~嗯？什么？本小姐的恶魔角歪了？你、你刚才什么都没看见！", voice="hero_3503_cv_13.prefab", voice1="hero_3503_cv_13.prefab", lines1="身为拉蒂夫家族的一员，本小姐的一言一行即是优雅~嗯？什么？本小姐的恶魔角歪了？你、你刚才什么都没看见！"
},
	[1914]={ lines="本小姐以前跟你说过吧，本小姐家的星彩源晶矿场，你一定想不到那种满坑满谷都是星彩源晶的景象，实在太漂亮了——等下次有机会，本小姐带你一起去。嗯？这可不是邀请哦，是命令，对，命令！", voice="hero_3503_cv_14.prefab", voice1="hero_3503_cv_14.prefab", lines1="本小姐以前跟你说过吧，本小姐家的星彩源晶矿场，你一定想不到那种满坑满谷都是星彩源晶的景象，实在太漂亮了——等下次有机会，本小姐带你一起去。嗯？这可不是邀请哦，是命令，对，命令！"
},
	[1915]={ lines="说起来，本小姐小时候还被绑架过呢。在一个雷雨交加的晚上，本小姐外出回家，结果一群暴徒围住了本小姐的车子……噗哈哈哈哈，你这一脸紧张的样子，不会是真的相信了吧？放心啦，刚才都是本小姐瞎编的。但你的样子，好好笑啊~", voice="hero_3503_cv_15.prefab", voice1="hero_3503_cv_15.prefab", lines1="说起来，本小姐小时候还被绑架过呢。在一个雷雨交加的晚上，本小姐外出回家，结果一群暴徒围住了本小姐的车子……噗哈哈哈哈，你这一脸紧张的样子，不会是真的相信了吧？放心啦，刚才都是本小姐瞎编的。但你的样子，好好笑啊~"
},
	[2001]={ lines="嗨，那边那个，你就是链尉官吗？记住我的名字——格林洛芬，相信我，有你用得上的时候。", voice="hero_3103_cv_01.prefab", voice1="hero_3103_cv_01.prefab", lines1="嗨，那边那个，你就是链尉官吗？记住我的名字——格林洛芬，相信我，有你用得上的时候。"
},
	[2002]={ lines="要上了要上了，准备好了吗？", voice="hero_3103_cv_02.prefab", voice1="hero_3103_cv_02.prefab", lines1="要上了要上了，准备好了吗？"
},
	[2003]={ lines="加固防御——", voice="hero_3103_cv_03.prefab", voice1="hero_3103_cv_03.prefab", lines1="加固防御——"
},
	[2004]={ lines="喔吼！吃我这招——", voice="hero_3103_cv_04.prefab", voice1="hero_3103_cv_04.prefab", lines1="喔吼！吃我这招——"
},
	[2005]={ lines="没有人能够突破我的防线！", voice="hero_3103_cv_05.prefab", voice1="hero_3103_cv_05.prefab", lines1="没有人能够突破我的防线！"
},
	[2006]={ lines="收工！下次需要帮忙，只管招呼一声就好。", voice="hero_3103_cv_06.prefab", voice1="hero_3103_cv_06.prefab", lines1="收工！下次需要帮忙，只管招呼一声就好。"
},
	[2007]={ lines="起得这么早？正好今天还有一大堆活没干呢，准备开工吧！", voice="hero_3103_cv_07.prefab", voice1="hero_3103_cv_07.prefab", lines1="起得这么早？正好今天还有一大堆活没干呢，准备开工吧！"
},
	[2008]={ lines="又有活干了？放心，不会让你失望的。", voice="hero_3103_cv_08.prefab", voice1="hero_3103_cv_08.prefab", lines1="又有活干了？放心，不会让你失望的。"
},
	[2009]={ lines="安啦，以后你和你的人，我都罩了。", voice="hero_3103_cv_09.prefab", voice1="hero_3103_cv_09.prefab", lines1="安啦，以后你和你的人，我都罩了。"
},
	[2010]={ lines="看你好像饿了，啊……不对，是这个。", voice="hero_3103_cv_10.prefab", voice1="hero_3103_cv_10.prefab", lines1="看你好像饿了，啊……不对，是这个。"
},
	[2011]={ lines="我的肤色是天生的，可不是晒出来的哦？", voice="hero_3103_cv_11.prefab", voice1="hero_3103_cv_11.prefab", lines1="我的肤色是天生的，可不是晒出来的哦？"
},
	[2012]={ lines="怎么想起来找我，惹上麻烦了吗？哈哈，开个玩笑。不过如果真有那种事情，随时都可以来找我帮忙。", voice="hero_3103_cv_12.prefab", voice1="hero_3103_cv_12.prefab", lines1="怎么想起来找我，惹上麻烦了吗？哈哈，开个玩笑。不过如果真有那种事情，随时都可以来找我帮忙。"
},
	[2013]={ lines="礼物？这是……啊，这是我找了很久的零件！哼哼，其实你比我想象中要靠谱得多嘛。", voice="hero_3103_cv_13.prefab", voice1="hero_3103_cv_13.prefab", lines1="礼物？这是……啊，这是我找了很久的零件！哼哼，其实你比我想象中要靠谱得多嘛。"
},
	[2014]={ lines="小时候把逃离家族当作冒险的人，长大之后回望过去，是否注定会产生相反的看法？嗯？感觉这不像是我会说的话？揍你哦——", voice="hero_3103_cv_14.prefab", voice1="hero_3103_cv_14.prefab", lines1="小时候把逃离家族当作冒险的人，长大之后回望过去，是否注定会产生相反的看法？嗯？感觉这不像是我会说的话？揍你哦——"
},
	[2015]={ lines="你是说，让我依靠你也可以？嗯，心意我收下了，不过还是算了——不，我不是说你能力不足，只是我更擅长做大姐头嘛，嘿嘿~", voice="hero_3103_cv_15.prefab", voice1="hero_3103_cv_15.prefab", lines1="你是说，让我依靠你也可以？嗯，心意我收下了，不过还是算了——不，我不是说你能力不足，只是我更擅长做大姐头嘛，嘿嘿~"
},
	[2101]={ lines="你好呀，初次见面，我是奈丝拉，你也可以叫我熠萤，是萤火虫的萤哦~", voice="hero_3106_cv_01.prefab", voice1="hero_3106_cv_01.prefab", lines1="你好呀，初次见面，我是奈丝拉，你也可以叫我熠萤，是萤火虫的萤哦~"
},
	[2102]={ lines="我一定可以的！", voice="hero_3106_cv_02.prefab", voice1="hero_3106_cv_02.prefab", lines1="我一定可以的！"
},
	[2103]={ lines="虫虫射线！", voice="hero_3106_cv_03.prefab", voice1="hero_3106_cv_03.prefab", lines1="虫虫射线！"
},
	[2104]={ lines="虫虫追击——", voice="hero_3106_cv_04.prefab", voice1="hero_3106_cv_04.prefab", lines1="虫虫追击——"
},
	[2105]={ lines="耶！虫虫大轰炸！", voice="hero_3106_cv_05.prefab", voice1="hero_3106_cv_05.prefab", lines1="耶！虫虫大轰炸！"
},
	[2106]={ lines="呼~也没有想象中那么难嘛。", voice="hero_3106_cv_06.prefab", voice1="hero_3106_cv_06.prefab", lines1="呼~也没有想象中那么难嘛。"
},
	[2107]={ lines="HI~又见到你了，一起来玩吧~", voice="hero_3106_cv_07.prefab", voice1="hero_3106_cv_07.prefab", lines1="HI~又见到你了，一起来玩吧~"
},
	[2108]={ lines="哈欠——好困呀。啊！这下要变笨了。", voice="hero_3106_cv_08.prefab", voice1="hero_3106_cv_08.prefab", lines1="哈欠——好困呀。啊！这下要变笨了。"
},
	[2109]={ lines="不要摸人家头嘛！会长不高的！", voice="hero_3106_cv_09.prefab", voice1="hero_3106_cv_09.prefab", lines1="不要摸人家头嘛！会长不高的！"
},
	[2110]={ lines="哈欠——如果待会有别人来了记得告诉我哦，人家想稍微睡一会儿........呼噜呼噜——", voice="hero_3106_cv_10.prefab", voice1="hero_3106_cv_10.prefab", lines1="哈欠——如果待会有别人来了记得告诉我哦，人家想稍微睡一会儿........呼噜呼噜——"
},
	[2111]={ lines="不要看我小，我也是一名战员哦，虽然还有很多要学习的地方......但我一定会努力的！", voice="hero_3106_cv_11.prefab", voice1="hero_3106_cv_11.prefab", lines1="不要看我小，我也是一名战员哦，虽然还有很多要学习的地方......但我一定会努力的！"
},
	[2112]={ lines="漂浮着的感觉其实很好玩的，只要在空中晃呀晃就能移动，一点都不会累哦！感觉飘着飘着就能去到好远的地方~", voice="hero_3106_cv_12.prefab", voice1="hero_3106_cv_12.prefab", lines1="漂浮着的感觉其实很好玩的，只要在空中晃呀晃就能移动，一点都不会累哦！感觉飘着飘着就能去到好远的地方~"
},
	[2113]={ lines="我最喜欢的就是萤火虫啦，小时候妈妈经常给我讲萤火虫的故事，我觉得它是全世界最美丽的东西。", voice="hero_3106_cv_13.prefab", voice1="hero_3106_cv_13.prefab", lines1="我最喜欢的就是萤火虫啦，小时候妈妈经常给我讲萤火虫的故事，我觉得它是全世界最美丽的东西。"
},
	[2114]={ lines="爸爸说随时会犯困是成为战员的后遗症，哎呀……好苦恼啊……不过爸爸说一定会把我治好的，我相信他！", voice="hero_3106_cv_14.prefab", voice1="hero_3106_cv_14.prefab", lines1="爸爸说随时会犯困是成为战员的后遗症，哎呀……好苦恼啊……不过爸爸说一定会把我治好的，我相信他！"
},
	[2115]={ lines="偷偷告诉你哦，我的源晶武装可以当吉祥物哦，上面特殊的符号代表了幸运值，只要摇到相同的符号今天的运势就会很好哦，你要不要试试看？", voice="hero_3106_cv_15.prefab", voice1="hero_3106_cv_15.prefab", lines1="偷偷告诉你哦，我的源晶武装可以当吉祥物哦，上面特殊的符号代表了幸运值，只要摇到相同的符号今天的运势就会很好哦，你要不要试试看？"
},
	[2201]={ lines="您好……我是安瓦诺拉，请……请多指教……", voice="hero_3109_cv_01.prefab", voice1="hero_3109_cv_01.prefab", lines1="您好……我是安瓦诺拉，请……请多指教……"
},
	[2202]={ lines="出发吧......", voice="hero_3109_cv_02.prefab", voice1="hero_3109_cv_02.prefab", lines1="出发吧......"
},
	[2203]={ lines="跃动吧……", voice="hero_3109_cv_03.prefab", voice1="hero_3109_cv_03.prefab", lines1="跃动吧……"
},
	[2204]={ lines="小心....浪来了。", voice="hero_3109_cv_04.prefab", voice1="hero_3109_cv_04.prefab", lines1="小心....浪来了。"
},
	[2205]={ lines="大海……会赐予我们……宁静——", voice="hero_3109_cv_05.prefab", voice1="hero_3109_cv_05.prefab", lines1="大海……会赐予我们……宁静——"
},
	[2206]={ lines="我做到了呢......", voice="hero_3109_cv_06.prefab", voice1="hero_3109_cv_06.prefab", lines1="我做到了呢......"
},
	[2207]={ lines="啊……你好.....", voice="hero_3109_cv_07.prefab", voice1="hero_3109_cv_07.prefab", lines1="啊……你好....."
},
	[2208]={ lines="海洋……虽然非常神秘，但那里的生物……和我们并没有什么不同……", voice="hero_3109_cv_08.prefab", voice1="hero_3109_cv_08.prefab", lines1="海洋……虽然非常神秘，但那里的生物……和我们并没有什么不同……"
},
	[2209]={ lines="那个.......我不太擅长和人交流......请你见谅……", voice="hero_3109_cv_09.prefab", voice1="hero_3109_cv_09.prefab", lines1="那个.......我不太擅长和人交流......请你见谅……"
},
	[2210]={ lines="这是我的朋友“啫喱”，它很乖巧，只要喂一点点东西就可以了。", voice="hero_3109_cv_10.prefab", voice1="hero_3109_cv_10.prefab", lines1="这是我的朋友“啫喱”，它很乖巧，只要喂一点点东西就可以了。"
},
	[2211]={ lines="你想.....和我聊什么？", voice="hero_3109_cv_11.prefab", voice1="hero_3109_cv_11.prefab", lines1="你想.....和我聊什么？"
},
	[2212]={ lines="探寻生命……是我的职责，我认为生命其实……是一种馈赠，你觉得呢？", voice="hero_3109_cv_12.prefab", voice1="hero_3109_cv_12.prefab", lines1="探寻生命……是我的职责，我认为生命其实……是一种馈赠，你觉得呢？"
},
	[2213]={ lines="“啫喱”是我的……朋友，它不是水母……虽然看上去像……但它不是……", voice="hero_3109_cv_13.prefab", voice1="hero_3109_cv_13.prefab", lines1="“啫喱”是我的……朋友，它不是水母……虽然看上去像……但它不是……"
},
	[2214]={ lines="“啫喱”是很温柔的，你可以……摸摸它，它说……它也想和你成为朋友……", voice="hero_3109_cv_14.prefab", voice1="hero_3109_cv_14.prefab", lines1="“啫喱”是很温柔的，你可以……摸摸它，它说……它也想和你成为朋友……"
},
	[2215]={ lines="在我心中……泰诺星上最安静……最美丽的地方，就是深深的……海底，在那里呆着……心灵都会得到治愈，有机会的话，真想带你……到那儿去看看。", voice="hero_3109_cv_15.prefab", voice1="hero_3109_cv_15.prefab", lines1="在我心中……泰诺星上最安静……最美丽的地方，就是深深的……海底，在那里呆着……心灵都会得到治愈，有机会的话，真想带你……到那儿去看看。"
},
	[2301]={ lines="你好，链尉官，我是艾丽西亚，我将成为你最趁手的剑，为你扫清前进道路上的一切阻碍，请多多指教。", voice="hero_3101_cv_01.prefab", voice1="hero_3101_cv_01.prefab", lines1="你好，链尉官，我是艾丽西亚，我将成为你最趁手的剑，为你扫清前进道路上的一切阻碍，请多多指教。"
},
	[2302]={ lines="我的剑准备好了。", voice="hero_3101_cv_02.prefab", voice1="hero_3101_cv_02.prefab", lines1="我的剑准备好了。"
},
	[2303]={ lines="一、二、三——斩开——", voice="hero_3101_cv_03.prefab", voice1="hero_3101_cv_03.prefab", lines1="一、二、三——斩开——"
},
	[2304]={ lines="绽放吧——", voice="hero_3101_cv_04.prefab", voice1="hero_3101_cv_04.prefab", lines1="绽放吧——"
},
	[2305]={ lines="接受裁决吧——", voice="hero_3101_cv_05.prefab", voice1="hero_3101_cv_05.prefab", lines1="接受裁决吧——"
},
	[2306]={ lines="嗯……当然的结果。", voice="hero_3101_cv_06.prefab", voice1="hero_3101_cv_06.prefab", lines1="嗯……当然的结果。"
},
	[2307]={ lines="欢迎回来，希望你今天过得开心。", voice="hero_3101_cv_07.prefab", voice1="hero_3101_cv_07.prefab", lines1="欢迎回来，希望你今天过得开心。"
},
	[2308]={ lines="Danchey已经陪伴了我10年，是我最好的朋友，怎么样，它是不是很可爱？", voice="hero_3101_cv_08.prefab", voice1="hero_3101_cv_08.prefab", lines1="Danchey已经陪伴了我10年，是我最好的朋友，怎么样，它是不是很可爱？"
},
	[2309]={ lines="我的剑……将会斩破一切敌人，这就是我的职责。", voice="hero_3101_cv_09.prefab", voice1="hero_3101_cv_09.prefab", lines1="我的剑……将会斩破一切敌人，这就是我的职责。"
},
	[2310]={ lines="保护这个星球是我们的责任，也是，我们的使命。", voice="hero_3101_cv_10.prefab", voice1="hero_3101_cv_10.prefab", lines1="保护这个星球是我们的责任，也是，我们的使命。"
},
	[2311]={ lines="链尉官，你能和我说说“大联考”是什么东西吗？我之前在书店看到了一本叫“五年联考三年练习”的书……", voice="hero_3101_cv_11.prefab", voice1="hero_3101_cv_11.prefab", lines1="链尉官，你能和我说说“大联考”是什么东西吗？我之前在书店看到了一本叫“五年联考三年练习”的书……"
},
	[2312]={ lines="很多人说我对钱没有概念？嗯……什么才叫“对钱有概念”？是指省钱吗？还是别的呢？", voice="hero_3101_cv_12.prefab", voice1="hero_3101_cv_12.prefab", lines1="很多人说我对钱没有概念？嗯……什么才叫“对钱有概念”？是指省钱吗？还是别的呢？"
},
	[2313]={ lines="Danchey~Danchey~Danchey~……啊，你看到了？！我，我在哼《小驴家族》的主题曲，别、别传出去啊……", voice="hero_3101_cv_13.prefab", voice1="hero_3101_cv_13.prefab", lines1="Danchey~Danchey~Danchey~……啊，你看到了？！我，我在哼《小驴家族》的主题曲，别、别传出去啊……"
},
	[2314]={ lines="当当~送你个礼物，这可是我最喜欢的Danchey的同款，限~定~版~哦~，喜不喜欢喜不喜欢？", voice="hero_3101_cv_14.prefab", voice1="hero_3101_cv_14.prefab", lines1="当当~送你个礼物，这可是我最喜欢的Danchey的同款，限~定~版~哦~，喜不喜欢喜不喜欢？"
},
	[2315]={ lines="链尉官，你有什么特别喜欢而且可以用钱买到的东西吗？如果有的话可以告诉我，我会买下来送给你的。", voice="hero_3101_cv_15.prefab", voice1="hero_3101_cv_15.prefab", lines1="链尉官，你有什么特别喜欢而且可以用钱买到的东西吗？如果有的话可以告诉我，我会买下来送给你的。"
},
	[2401]={ lines="我是凯米娅，博士让我来这里协助你，请下命令。", voice="hero_1102_cv_01.prefab", voice1="hero_1102_cv_01.prefab", lines1="我是凯米娅，博士让我来这里协助你，请下命令。"
},
	[2402]={ lines="等待命令。", voice="hero_1102_cv_02.prefab", voice1="hero_1102_cv_02.prefab", lines1="等待命令。"
},
	[2403]={ lines="失礼了。", voice="hero_1102_cv_03.prefab", voice1="hero_1102_cv_03.prefab", lines1="失礼了。"
},
	[2404]={ lines="对不起。", voice="hero_1102_cv_04.prefab", voice1="hero_1102_cv_04.prefab", lines1="对不起。"
},
	[2405]={ lines="失礼了，但是对不起。", voice="hero_1102_cv_05.prefab", voice1="hero_1102_cv_05.prefab", lines1="失礼了，但是对不起。"
},
	[2406]={ lines="谢谢你的夸奖。", voice="hero_1102_cv_06.prefab", voice1="hero_1102_cv_06.prefab", lines1="谢谢你的夸奖。"
},
	[2407]={ lines="你好，需要我为你做些什么？", voice="hero_1102_cv_07.prefab", voice1="hero_1102_cv_07.prefab", lines1="你好，需要我为你做些什么？"
},
	[2408]={ lines="我的身体偶尔会行动不太顺畅，他们说这是“生锈”，但我没有发现锈迹，非常奇怪。", voice="hero_1102_cv_08.prefab", voice1="hero_1102_cv_08.prefab", lines1="我的身体偶尔会行动不太顺畅，他们说这是“生锈”，但我没有发现锈迹，非常奇怪。"
},
	[2409]={ lines="………………没什么。", voice="hero_1102_cv_09.prefab", voice1="hero_1102_cv_09.prefab", lines1="………………没什么。"
},
	[2410]={ lines="身体运动状态良好，可以进行战斗。", voice="hero_1102_cv_10.prefab", voice1="hero_1102_cv_10.prefab", lines1="身体运动状态良好，可以进行战斗。"
},
	[2411]={ lines="人类的情感……很有趣，我虽然正在学习，但真的很难理解。", voice="hero_1102_cv_11.prefab", voice1="hero_1102_cv_11.prefab", lines1="人类的情感……很有趣，我虽然正在学习，但真的很难理解。"
},
	[2412]={ lines="链尉官，我想问你一个问题——你生活的意义是什么？如果你觉得困扰，不回答也没关系。", voice="hero_1102_cv_12.prefab", voice1="hero_1102_cv_12.prefab", lines1="链尉官，我想问你一个问题——你生活的意义是什么？如果你觉得困扰，不回答也没关系。"
},
	[2413]={ lines="我听说人类都能用语言表达出自己的情绪，但我却做不到，链尉官，你有什么方法可以教教我吗？", voice="hero_1102_cv_13.prefab", voice1="hero_1102_cv_13.prefab", lines1="我听说人类都能用语言表达出自己的情绪，但我却做不到，链尉官，你有什么方法可以教教我吗？"
},
	[2414]={ lines="链尉官，你介意我靠得近一些吗？我想近距离观察一下你的反应和情绪。", voice="hero_1102_cv_14.prefab", voice1="hero_1102_cv_14.prefab", lines1="链尉官，你介意我靠得近一些吗？我想近距离观察一下你的反应和情绪。"
},
	[2415]={ lines="链尉官，我有一种感觉，如果一直和你待在一起的话，我应该就能够更快地理解人类的情感，找到生活的意义。", voice="hero_1102_cv_15.prefab", voice1="hero_1102_cv_15.prefab", lines1="链尉官，我有一种感觉，如果一直和你待在一起的话，我应该就能够更快地理解人类的情感，找到生活的意义。"
},
	[2501]={ lines="叫我斯翠涅就行了，别的不用管那么多，放心，不会让你死掉的。", voice="hero_3501_cv_01.prefab", voice1="hero_3501_cv_01.prefab", lines1="叫我斯翠涅就行了，别的不用管那么多，放心，不会让你死掉的。"
},
	[2502]={ lines="有谁想要被“治疗”？", voice="hero_3501_cv_02.prefab", voice1="hero_3501_cv_02.prefab", lines1="有谁想要被“治疗”？"
},
	[2503]={ lines="谁想要来一发？", voice="hero_3501_cv_03.prefab", voice1="hero_3501_cv_03.prefab", lines1="谁想要来一发？"
},
	[2504]={ lines="乖乖站好——", voice="hero_3501_cv_04.prefab", voice1="hero_3501_cv_04.prefab", lines1="乖乖站好——"
},
	[2505]={ lines="发生什么效果我可不保证——", voice="hero_3501_cv_05.prefab", voice1="hero_3501_cv_05.prefab", lines1="发生什么效果我可不保证——"
},
	[2506]={ lines="起码……没有死人。", voice="hero_3501_cv_06.prefab", voice1="hero_3501_cv_06.prefab", lines1="起码……没有死人。"
},
	[2507]={ lines="欢迎来到这个即好又坏的世界。", voice="hero_3501_cv_07.prefab", voice1="hero_3501_cv_07.prefab", lines1="欢迎来到这个即好又坏的世界。"
},
	[2508]={ lines="有没有患者需要治疗一下……", voice="hero_3501_cv_08.prefab", voice1="hero_3501_cv_08.prefab", lines1="有没有患者需要治疗一下……"
},
	[2509]={ lines="你需要我表现出笑容给你看吗？也不是不行——", voice="hero_3501_cv_09.prefab", voice1="hero_3501_cv_09.prefab", lines1="你需要我表现出笑容给你看吗？也不是不行——"
},
	[2510]={ lines="治疗多了，你就不知道什么是痛了，对吧？", voice="hero_3501_cv_10.prefab", voice1="hero_3501_cv_10.prefab", lines1="治疗多了，你就不知道什么是痛了，对吧？"
},
	[2511]={ lines="最好不要和我随便搭话，这是为了你好，你难道不明白我这个代号的含义吗？", voice="hero_3501_cv_11.prefab", voice1="hero_3501_cv_11.prefab", lines1="最好不要和我随便搭话，这是为了你好，你难道不明白我这个代号的含义吗？"
},
	[2512]={ lines="性格古怪？呵，这不是理所当然的嘛，离我远点，要不你就该猜猜下次我会给你用什么药了。", voice="hero_3501_cv_12.prefab", voice1="hero_3501_cv_12.prefab", lines1="性格古怪？呵，这不是理所当然的嘛，离我远点，要不你就该猜猜下次我会给你用什么药了。"
},
	[2513]={ lines="你应该了解了，我精神上有异常，所以最好别找我的麻烦……我也不需要治疗，因为我自己就是医生，虽然是没有执照的那种。", voice="hero_3501_cv_13.prefab", voice1="hero_3501_cv_13.prefab", lines1="你应该了解了，我精神上有异常，所以最好别找我的麻烦……我也不需要治疗，因为我自己就是医生，虽然是没有执照的那种。"
},
	[2514]={ lines="每隔21天我就需要找个地方把自己关起来，处理一些“不必要的东西”，这是当下最好的解决办法……所以你最好能乖乖识趣，否则我不能保证不对你“做些什么”。", voice="hero_3501_cv_14.prefab", voice1="hero_3501_cv_14.prefab", lines1="每隔21天我就需要找个地方把自己关起来，处理一些“不必要的东西”，这是当下最好的解决办法……所以你最好能乖乖识趣，否则我不能保证不对你“做些什么”。"
},
	[2515]={ lines="你是不是和我靠的太近了……你明白我有问题的吧？这样啊……我会考虑我们之间的关系……换句话说——我不会让你死掉的。", voice="hero_3501_cv_15.prefab", voice1="hero_3501_cv_15.prefab", lines1="你是不是和我靠的太近了……你明白我有问题的吧？这样啊……我会考虑我们之间的关系……换句话说——我不会让你死掉的。"
},
	[2601]={ lines="你好，我叫洛塔......这位是我的AI朋友，我叫它“零”，希望你也能够和它成为朋友……", voice="hero_2502_cv_01.prefab", voice1="hero_2502_cv_01.prefab", lines1="你好，我叫洛塔......这位是我的AI朋友，我叫它“零”，希望你也能够和它成为朋友……"
},
	[2602]={ lines="我会努力加油的。", voice="hero_2502_cv_02.prefab", voice1="hero_2502_cv_02.prefab", lines1="我会努力加油的。"
},
	[2603]={ lines="开始清理恶性数据——", voice="hero_2502_cv_03.prefab", voice1="hero_2502_cv_03.prefab", lines1="开始清理恶性数据——"
},
	[2604]={ lines="量子数据防御，开启！", voice="hero_2502_cv_04.prefab", voice1="hero_2502_cv_04.prefab", lines1="量子数据防御，开启！"
},
	[2605]={ lines="虚数演算展开，开始骇入，给你们点厉害尝尝——", voice="hero_2502_cv_05.prefab", voice1="hero_2502_cv_05.prefab", lines1="虚数演算展开，开始骇入，给你们点厉害尝尝——"
},
	[2606]={ lines="我的演算……为你带来帮助了吗？", voice="hero_2502_cv_06.prefab", voice1="hero_2502_cv_06.prefab", lines1="我的演算……为你带来帮助了吗？"
},
	[2607]={ lines="你好，你要喝牛奶吗?", voice="hero_2502_cv_07.prefab", voice1="hero_2502_cv_07.prefab", lines1="你好，你要喝牛奶吗?"
},
	[2608]={ lines="别看我这样，在网络中的我，可是身高一米八呢。", voice="hero_2502_cv_08.prefab", voice1="hero_2502_cv_08.prefab", lines1="别看我这样，在网络中的我，可是身高一米八呢。"
},
	[2609]={ lines="话说，我稍微偷懒休息一会，应该也是……可以的吧？", voice="hero_2502_cv_09.prefab", voice1="hero_2502_cv_09.prefab", lines1="话说，我稍微偷懒休息一会，应该也是……可以的吧？"
},
	[2610]={ lines="唔……又有新的工作要处理了，链尉官，要不你帮我做一些嘛……", voice="hero_2502_cv_10.prefab", voice1="hero_2502_cv_10.prefab", lines1="唔……又有新的工作要处理了，链尉官，要不你帮我做一些嘛……"
},
	[2611]={ lines="如果你遇到网络相关的问题，可以来问我的，伊西丝说过，同事之间是要互相帮忙的。", voice="hero_2502_cv_11.prefab", voice1="hero_2502_cv_11.prefab", lines1="如果你遇到网络相关的问题，可以来问我的，伊西丝说过，同事之间是要互相帮忙的。"
},
	[2612]={ lines="啊……你好……你要喝牛奶吗……....", voice="hero_2502_cv_12.prefab", voice1="hero_2502_cv_12.prefab", lines1="啊……你好……你要喝牛奶吗……...."
},
	[2613]={ lines="网络骇入……很简单啊，就和看星星的拼图一样，从这里——挪到这里——“咻”的一下就可以了——", voice="hero_2502_cv_13.prefab", voice1="hero_2502_cv_13.prefab", lines1="网络骇入……很简单啊，就和看星星的拼图一样，从这里——挪到这里——“咻”的一下就可以了——"
},
	[2614]={ lines="链尉官，你喜欢看星星吗？我的数据库里有整个泰诺星历史上出现的所有星星的信息，你想不想看一看？", voice="hero_2502_cv_14.prefab", voice1="hero_2502_cv_14.prefab", lines1="链尉官，你喜欢看星星吗？我的数据库里有整个泰诺星历史上出现的所有星星的信息，你想不想看一看？"
},
	[2615]={ lines="我的代号是伊西丝给我起的，一开始我并不知道这个代号的含义，后来我才知道这是一个传说中的星云的名字，这也太酷了！链尉官，快看，这就是那个星云的样子，是不是很漂亮？嘿嘿……", voice="hero_2502_cv_15.prefab", voice1="hero_2502_cv_15.prefab", lines1="我的代号是伊西丝给我起的，一开始我并不知道这个代号的含义，后来我才知道这是一个传说中的星云的名字，这也太酷了！链尉官，快看，这就是那个星云的样子，是不是很漂亮？嘿嘿……"
},
	[2701]={ lines="元雅来报到咯~先说好，重活累活不干的哦？除非……零食管够！", voice="hero_2501_cv_01.prefab", voice1="hero_2501_cv_01.prefab", lines1="元雅来报到咯~先说好，重活累活不干的哦？除非……零食管够！"
},
	[2702]={ lines="赶紧打完，我还要回去玩儿呢。", voice="hero_2501_cv_02.prefab", voice1="hero_2501_cv_02.prefab", lines1="赶紧打完，我还要回去玩儿呢。"
},
	[2703]={ lines="去吧，蜂群导弹。", voice="hero_2501_cv_03.prefab", voice1="hero_2501_cv_03.prefab", lines1="去吧，蜂群导弹。"
},
	[2704]={ lines="心情不错，再多来点儿导弹~", voice="hero_2501_cv_04.prefab", voice1="hero_2501_cv_04.prefab", lines1="心情不错，再多来点儿导弹~"
},
	[2705]={ lines="别客气，量大管饱哦~", voice="hero_2501_cv_05.prefab", voice1="hero_2501_cv_05.prefab", lines1="别客气，量大管饱哦~"
},
	[2706]={ lines="有我在，轻轻松松啦~", voice="hero_2501_cv_06.prefab", voice1="hero_2501_cv_06.prefab", lines1="有我在，轻轻松松啦~"
},
	[2707]={ lines="HI~请给可爱的我今天的零食~", voice="hero_2501_cv_07.prefab", voice1="hero_2501_cv_07.prefab", lines1="HI~请给可爱的我今天的零食~"
},
	[2708]={ lines="汽水是人类最伟大的发明之一，咕咚咕咚~", voice="hero_2501_cv_08.prefab", voice1="hero_2501_cv_08.prefab", lines1="汽水是人类最伟大的发明之一，咕咚咕咚~"
},
	[2709]={ lines="想讨好我？那就先给我零食吧，我要吃番茄味的薯片~", voice="hero_2501_cv_09.prefab", voice1="hero_2501_cv_09.prefab", lines1="想讨好我？那就先给我零食吧，我要吃番茄味的薯片~"
},
	[2710]={ lines="哼唧，什么叫吃零食不利于生长，你那是偏见，偏见！", voice="hero_2501_cv_10.prefab", voice1="hero_2501_cv_10.prefab", lines1="哼唧，什么叫吃零食不利于生长，你那是偏见，偏见！"
},
	[2711]={ lines="嗯？你有事要找我吗？帮忙可以，但是奖励也不能少哦。", voice="hero_2501_cv_11.prefab", voice1="hero_2501_cv_11.prefab", lines1="嗯？你有事要找我吗？帮忙可以，但是奖励也不能少哦。"
},
	[2712]={ lines="可拉兹？虽然我叫她蠢猫，但我俩的关系可是密不可分的，别看我们个子小，但我们可是很强的哦。", voice="hero_2501_cv_12.prefab", voice1="hero_2501_cv_12.prefab", lines1="可拉兹？虽然我叫她蠢猫，但我俩的关系可是密不可分的，别看我们个子小，但我们可是很强的哦。"
},
	[2713]={ lines="链尉官，你能给我买零食吗？这个月发放的补给都让我买吃的用完了，但是新出了一款好吃的巧克力，包装上还有很可爱的兔兔.....", voice="hero_2501_cv_13.prefab", voice1="hero_2501_cv_13.prefab", lines1="链尉官，你能给我买零食吗？这个月发放的补给都让我买吃的用完了，但是新出了一款好吃的巧克力，包装上还有很可爱的兔兔....."
},
	[2714]={ lines="平时我喜欢做什么？吃零食，喝饮料，听歌打游戏看漫画，那么多有意思的事等着我去做呢~科研？那是工作的时候才要做的事情，闲下来谁要干活啊？", voice="hero_2501_cv_14.prefab", voice1="hero_2501_cv_14.prefab", lines1="平时我喜欢做什么？吃零食，喝饮料，听歌打游戏看漫画，那么多有意思的事等着我去做呢~科研？那是工作的时候才要做的事情，闲下来谁要干活啊？"
},
	[2715]={ lines="以前和妈妈在一起的时候，她不让我吃零食，说会蛀牙，也没有好玩的，还总是要我学习，现在在这里，我有了很多同伴，姐姐们对我可好了，也可以吃好多好多零食......但是，我真的很想妈妈......", voice="hero_2501_cv_15.prefab", voice1="hero_2501_cv_15.prefab", lines1="以前和妈妈在一起的时候，她不让我吃零食，说会蛀牙，也没有好玩的，还总是要我学习，现在在这里，我有了很多同伴，姐姐们对我可好了，也可以吃好多好多零食......但是，我真的很想妈妈......"
},
	[2801]={ lines="嗯……我也不知道该自称梓绿还是安达娜，你想怎么叫就怎么叫吧，有什么事要帮忙说一声就好。", voice="hero_2104_cv_01.prefab", voice1="hero_2104_cv_01.prefab", lines1="嗯……我也不知道该自称梓绿还是安达娜，你想怎么叫就怎么叫吧，有什么事要帮忙说一声就好。"
},
	[2802]={ lines="这可是试验的好时机。", voice="hero_2104_cv_02.prefab", voice1="hero_2104_cv_02.prefab", lines1="这可是试验的好时机。"
},
	[2803]={ lines="布鲁，给他长点草——", voice="hero_2104_cv_03.prefab", voice1="hero_2104_cv_03.prefab", lines1="布鲁，给他长点草——"
},
	[2804]={ lines="来点荆棘——", voice="hero_2104_cv_04.prefab", voice1="hero_2104_cv_04.prefab", lines1="来点荆棘——"
},
	[2805]={ lines="看看这个的效果如何？噢哟？超出预期——", voice="hero_2104_cv_05.prefab", voice1="hero_2104_cv_05.prefab", lines1="看看这个的效果如何？噢哟？超出预期——"
},
	[2806]={ lines="好像的确得到了很多数据的样子……", voice="hero_2104_cv_06.prefab", voice1="hero_2104_cv_06.prefab", lines1="好像的确得到了很多数据的样子……"
},
	[2807]={ lines="早上好，啊……好困，啊不是，我不是在说你……", voice="hero_2104_cv_07.prefab", voice1="hero_2104_cv_07.prefab", lines1="早上好，啊……好困，啊不是，我不是在说你……"
},
	[2808]={ lines="嘿嘿，这一期的学分肯定没问……啊！我的学分啊——", voice="hero_2104_cv_08.prefab", voice1="hero_2104_cv_08.prefab", lines1="嘿嘿，这一期的学分肯定没问……啊！我的学分啊——"
},
	[2809]={ lines="听说给人扮可爱，就能让人帮忙写论文，你看你看——看我可爱的眼神——", voice="hero_2104_cv_09.prefab", voice1="hero_2104_cv_09.prefab", lines1="听说给人扮可爱，就能让人帮忙写论文，你看你看——看我可爱的眼神——"
},
	[2810]={ lines="（只要把这个要素挪到那边……就可以形成……布鲁？你出来干什么，你又不能帮我写论文——）", voice="hero_2104_cv_10.prefab", voice1="hero_2104_cv_10.prefab", lines1="（只要把这个要素挪到那边……就可以形成……布鲁？你出来干什么，你又不能帮我写论文——）"
},
	[2811]={ lines="这本书？它的名字是《塞洛维植物变化史》，是一本我还没有完成的百科书籍。作者为什么不是我的名字？嗯……如果有机会，我会告诉你原因的。", voice="hero_2104_cv_11.prefab", voice1="hero_2104_cv_11.prefab", lines1="这本书？它的名字是《塞洛维植物变化史》，是一本我还没有完成的百科书籍。作者为什么不是我的名字？嗯……如果有机会，我会告诉你原因的。"
},
	[2812]={ lines="这个实验室有很多发生异变了的植物，进来的时候请小心——啊，你的头上有——不要动！动了你就会死的！让我来处理。", voice="hero_2104_cv_12.prefab", voice1="hero_2104_cv_12.prefab", lines1="这个实验室有很多发生异变了的植物，进来的时候请小心——啊，你的头上有——不要动！动了你就会死的！让我来处理。"
},
	[2813]={ lines="《塞洛维植物变化史》的作者薇薇安，是我的一个很重要的朋友，但是她现在就像这间实验室里的植物们一样，不能说话，也不能感知到情绪……唔，请当我什么都没说……", voice="hero_2104_cv_13.prefab", voice1="hero_2104_cv_13.prefab", lines1="《塞洛维植物变化史》的作者薇薇安，是我的一个很重要的朋友，但是她现在就像这间实验室里的植物们一样，不能说话，也不能感知到情绪……唔，请当我什么都没说……"
},
	[2814]={ lines="我知道研究所里很多人都不待见我，我只是不在意而已，而且我知道……你和他们都不一样……我知道你对我的支持，谢谢你。", voice="hero_2104_cv_14.prefab", voice1="hero_2104_cv_14.prefab", lines1="我知道研究所里很多人都不待见我，我只是不在意而已，而且我知道……你和他们都不一样……我知道你对我的支持，谢谢你。"
},
	[2815]={ lines="如果，我是说如果，薇薇安能够醒来的话，你能和我一起去看她吗？我想告诉她，有你和许多人都在支持着我，鼓励着我。真的？太好了……", voice="hero_2104_cv_15.prefab", voice1="hero_2104_cv_15.prefab", lines1="如果，我是说如果，薇薇安能够醒来的话，你能和我一起去看她吗？我想告诉她，有你和许多人都在支持着我，鼓励着我。真的？太好了……"
},
	[2901]={ lines="帕迪娅向您致以问候！想不想看烟火？没问题，马上为您安排！魔术也会很多哦？", voice="hero_2102_cv_01.prefab", voice1="hero_2102_cv_01.prefab", lines1="帕迪娅向您致以问候！想不想看烟火？没问题，马上为您安排！魔术也会很多哦？"
},
	[2902]={ lines="虽然不知道怎么回事，但是先上场吧——", voice="hero_2102_cv_02.prefab", voice1="hero_2102_cv_02.prefab", lines1="虽然不知道怎么回事，但是先上场吧——"
},
	[2903]={ lines="噢啦噢啦噢啦噢啦——BOOM~", voice="hero_2102_cv_03.prefab", voice1="hero_2102_cv_03.prefab", lines1="噢啦噢啦噢啦噢啦——BOOM~"
},
	[2904]={ lines="嘿~是帽子戏法哟~", voice="hero_2102_cv_04.prefab", voice1="hero_2102_cv_04.prefab", lines1="嘿~是帽子戏法哟~"
},
	[2905]={ lines="烟火秀——开幕！", voice="hero_2102_cv_05.prefab", voice1="hero_2102_cv_05.prefab", lines1="烟火秀——开幕！"
},
	[2906]={ lines="嘿嘿，看来干得还不错~", voice="hero_2102_cv_06.prefab", voice1="hero_2102_cv_06.prefab", lines1="嘿嘿，看来干得还不错~"
},
	[2907]={ lines="早呀早呀，今天也要保持好心情哦~", voice="hero_2102_cv_07.prefab", voice1="hero_2102_cv_07.prefab", lines1="早呀早呀，今天也要保持好心情哦~"
},
	[2908]={ lines="帽子戏法！什么？只是转帽子而已，不算戏法？啧啧啧，这你就不懂了——", voice="hero_2102_cv_08.prefab", voice1="hero_2102_cv_08.prefab", lines1="帽子戏法！什么？只是转帽子而已，不算戏法？啧啧啧，这你就不懂了——"
},
	[2909]={ lines="锵锵~看好喽，我要先这样，再——这样！怎么样，是不是注意力都被吸引了？", voice="hero_2102_cv_09.prefab", voice1="hero_2102_cv_09.prefab", lines1="锵锵~看好喽，我要先这样，再——这样！怎么样，是不是注意力都被吸引了？"
},
	[2910]={ lines="看好咯，我要变出拐杖来啦~哈哈，只是普通地变出来，没有多余的戏法啦~", voice="hero_2102_cv_10.prefab", voice1="hero_2102_cv_10.prefab", lines1="看好咯，我要变出拐杖来啦~哈哈，只是普通地变出来，没有多余的戏法啦~"
},
	[2911]={ lines="我的工作就是让人不断地惊讶——当看到大家从惊讶变成开心，他们脸上绽放出的笑颜会让我很有满足感。", voice="hero_2102_cv_11.prefab", voice1="hero_2102_cv_11.prefab", lines1="我的工作就是让人不断地惊讶——当看到大家从惊讶变成开心，他们脸上绽放出的笑颜会让我很有满足感。"
},
	[2912]={ lines="你知道吗？魔术带来的新奇和好奇的感觉会让人变得越来越年轻，真的，不骗你哦？", voice="hero_2102_cv_12.prefab", voice1="hero_2102_cv_12.prefab", lines1="你知道吗？魔术带来的新奇和好奇的感觉会让人变得越来越年轻，真的，不骗你哦？"
},
	[2913]={ lines="我的梦想？那当然是举办全球巡回演出啦，魔术改变了我的人生，我也想用魔术去影响其他人的人生，让他们感受到梦幻与爱，这是多美好的一件事呀。", voice="hero_2102_cv_13.prefab", voice1="hero_2102_cv_13.prefab", lines1="我的梦想？那当然是举办全球巡回演出啦，魔术改变了我的人生，我也想用魔术去影响其他人的人生，让他们感受到梦幻与爱，这是多美好的一件事呀。"
},
	[2914]={ lines="能不能靠变戏法过一辈子？难道你觉得不能？那你也太没有爱了耶……只要我还继续站在舞台上，不管是一年，十年......只要我活着，表演就会继续下去。", voice="hero_2102_cv_14.prefab", voice1="hero_2102_cv_14.prefab", lines1="能不能靠变戏法过一辈子？难道你觉得不能？那你也太没有爱了耶……只要我还继续站在舞台上，不管是一年，十年......只要我活着，表演就会继续下去。"
},
	[2915]={ lines="不怕告诉你，这些年来，我听到很多观众叫我魔女，说我和精灵签订了契约，施展的都是魔法而不是魔术的时候，我内心可骄傲啦！那种感觉真的会上瘾的，可惜呀，你不会变戏法，体会不到咯，嘻嘻~", voice="hero_2102_cv_15.prefab", voice1="hero_2102_cv_15.prefab", lines1="不怕告诉你，这些年来，我听到很多观众叫我魔女，说我和精灵签订了契约，施展的都是魔法而不是魔术的时候，我内心可骄傲啦！那种感觉真的会上瘾的，可惜呀，你不会变戏法，体会不到咯，嘻嘻~"
},
	[3001]={ lines="可拉兹来报到了，有什么需要我做的事情喵？", voice="hero_2101_cv_01.prefab", voice1="hero_2101_cv_01.prefab", lines1="可拉兹来报到了，有什么需要我做的事情喵？"
},
	[3002]={ lines="把他们锤扁喵——", voice="hero_2101_cv_02.prefab", voice1="hero_2101_cv_02.prefab", lines1="把他们锤扁喵——"
},
	[3003]={ lines="尝尝我的厉害喵~", voice="hero_2101_cv_03.prefab", voice1="hero_2101_cv_03.prefab", lines1="尝尝我的厉害喵~"
},
	[3004]={ lines="吃我一锤喵~", voice="hero_2101_cv_04.prefab", voice1="hero_2101_cv_04.prefab", lines1="吃我一锤喵~"
},
	[3005]={ lines="喵喵流星锤——变成星星吧！", voice="hero_2101_cv_05.prefab", voice1="hero_2101_cv_05.prefab", lines1="喵喵流星锤——变成星星吧！"
},
	[3006]={ lines="嘻嘻，小事一桩喵。", voice="hero_2101_cv_06.prefab", voice1="hero_2101_cv_06.prefab", lines1="嘻嘻，小事一桩喵。"
},
	[3007]={ lines="你好喵~", voice="hero_2101_cv_07.prefab", voice1="hero_2101_cv_07.prefab", lines1="你好喵~"
},
	[3008]={ lines="喵喵之舞喵！", voice="hero_2101_cv_08.prefab", voice1="hero_2101_cv_08.prefab", lines1="喵喵之舞喵！"
},
	[3009]={ lines="喵喵模仿术喵！", voice="hero_2101_cv_09.prefab", voice1="hero_2101_cv_09.prefab", lines1="喵喵模仿术喵！"
},
	[3010]={ lines="吓你一跳喵！", voice="hero_2101_cv_10.prefab", voice1="hero_2101_cv_10.prefab", lines1="吓你一跳喵！"
},
	[3011]={ lines="别看可拉兹个头不大，力气可是不小的喵。不管怎样可怕的敌人，可拉兹都能用喵喵锤把他们锤得七荤八素的喵！", voice="hero_2101_cv_11.prefab", voice1="hero_2101_cv_11.prefab", lines1="别看可拉兹个头不大，力气可是不小的喵。不管怎样可怕的敌人，可拉兹都能用喵喵锤把他们锤得七荤八素的喵！"
},
	[3012]={ lines="链尉官，想和可拉兹掰手腕喵！唔，你说你会放水？嘻嘻~可拉兹建议你最好不要这样做喵……", voice="hero_2101_cv_12.prefab", voice1="hero_2101_cv_12.prefab", lines1="链尉官，想和可拉兹掰手腕喵！唔，你说你会放水？嘻嘻~可拉兹建议你最好不要这样做喵……"
},
	[3013]={ lines="……虽然大家都说可拉兹吃得很多，但可拉兹也不是什么都能吃的喵。没办法吃辣……苦的也不行，酸的也不行……太烫的也不行，太冰的也不行……猫舌头就是这样的喵……", voice="hero_2101_cv_13.prefab", voice1="hero_2101_cv_13.prefab", lines1="……虽然大家都说可拉兹吃得很多，但可拉兹也不是什么都能吃的喵。没办法吃辣……苦的也不行，酸的也不行……太烫的也不行，太冰的也不行……猫舌头就是这样的喵……"
},
	[3014]={ lines="雅雅是可拉兹最重要的家人喵，可拉兹最大的梦想，就是成为能够守护雅雅的存在喵！现在可拉兹已经是一名战员了，这个梦想已经实现了一半了喵~链尉官，你的梦想是什么喵？悄悄告诉我的话，可拉兹会为你加油鼓劲喵！", voice="hero_2101_cv_14.prefab", voice1="hero_2101_cv_14.prefab", lines1="雅雅是可拉兹最重要的家人喵，可拉兹最大的梦想，就是成为能够守护雅雅的存在喵！现在可拉兹已经是一名战员了，这个梦想已经实现了一半了喵~链尉官，你的梦想是什么喵？悄悄告诉我的话，可拉兹会为你加油鼓劲喵！"
},
	[3015]={ lines="链尉官会有感觉到辛苦的时候喵？其实可拉兹也会在有些时候觉得辛苦喵……但是苦恼也没有什么用，最好的方法就是把这些有的没的烦恼抛到脑后喵，因为每一天都是新的一天，每一天都值得用最高的热情去对待喵！今后，链尉官也要和可拉兹一起努力向前喵~", voice="hero_2101_cv_15.prefab", voice1="hero_2101_cv_15.prefab", lines1="链尉官会有感觉到辛苦的时候喵？其实可拉兹也会在有些时候觉得辛苦喵……但是苦恼也没有什么用，最好的方法就是把这些有的没的烦恼抛到脑后喵，因为每一天都是新的一天，每一天都值得用最高的热情去对待喵！今后，链尉官也要和可拉兹一起努力向前喵~"
},
	[3101]={ lines="洛可丝，代号巧匠，需要进行义体改造吗？可以给你打对折哦？", voice="hero_2503_cv_01.prefab", voice1="hero_2503_cv_01.prefab", lines1="洛可丝，代号巧匠，需要进行义体改造吗？可以给你打对折哦？"
},
	[3102]={ lines="战斗吗？虽然不太擅长……", voice="hero_2503_cv_02.prefab", voice1="hero_2503_cv_02.prefab", lines1="战斗吗？虽然不太擅长……"
},
	[3103]={ lines="触电吧。", voice="hero_2503_cv_03.prefab", voice1="hero_2503_cv_03.prefab", lines1="触电吧。"
},
	[3104]={ lines="尝尝这个。", voice="hero_2503_cv_04.prefab", voice1="hero_2503_cv_04.prefab", lines1="尝尝这个。"
},
	[3105]={ lines="既然如此，只能把你们全部先消灭了——", voice="hero_2503_cv_05.prefab", voice1="hero_2503_cv_05.prefab", lines1="既然如此，只能把你们全部先消灭了——"
},
	[3106]={ lines="真遗憾……居然没有人需要义体化……", voice="hero_2503_cv_06.prefab", voice1="hero_2503_cv_06.prefab", lines1="真遗憾……居然没有人需要义体化……"
},
	[3107]={ lines="早上好，今天您想替换身上的哪个部位呢？", voice="hero_2503_cv_07.prefab", voice1="hero_2503_cv_07.prefab", lines1="早上好，今天您想替换身上的哪个部位呢？"
},
	[3108]={ lines="嗯……新研发的外骨骼还有一些地方要调整……", voice="hero_2503_cv_08.prefab", voice1="hero_2503_cv_08.prefab", lines1="嗯……新研发的外骨骼还有一些地方要调整……"
},
	[3109]={ lines="机械是很直接的，如果它们不舒服的话马上就能看出来了，比人类要单纯得多呢。", voice="hero_2503_cv_09.prefab", voice1="hero_2503_cv_09.prefab", lines1="机械是很直接的，如果它们不舒服的话马上就能看出来了，比人类要单纯得多呢。"
},
	[3110]={ lines="我做了一套新肢体的方案，要来我的工作室试试看吗？放心，一点都不会痛的。", voice="hero_2503_cv_10.prefab", voice1="hero_2503_cv_10.prefab", lines1="我做了一套新肢体的方案，要来我的工作室试试看吗？放心，一点都不会痛的。"
},
	[3111]={ lines="你听说过我？关于什么的？哎呀……什么疯狂的医生？太没礼貌了吧？", voice="hero_2503_cv_11.prefab", voice1="hero_2503_cv_11.prefab", lines1="你听说过我？关于什么的？哎呀……什么疯狂的医生？太没礼貌了吧？"
},
	[3112]={ lines="我为什么总是待在工作室里？嗯……顺其自然的原因？我可没有敷衍你啊，因为我很忙的嘛。", voice="hero_2503_cv_12.prefab", voice1="hero_2503_cv_12.prefab", lines1="我为什么总是待在工作室里？嗯……顺其自然的原因？我可没有敷衍你啊，因为我很忙的嘛。"
},
	[3113]={ lines="这是什么？——舒尔茨式座钟历史全图鉴？！你你你你从哪弄来的？快，快给我看看——哇哇哇，这一款——太棒了——呜哇——", voice="hero_2503_cv_13.prefab", voice1="hero_2503_cv_13.prefab", lines1="这是什么？——舒尔茨式座钟历史全图鉴？！你你你你从哪弄来的？快，快给我看看——哇哇哇，这一款——太棒了——呜哇——"
},
	[3114]={ lines="……呃……上次你的那本图鉴……是从哪里拿到的啊……可以的话能送给我吗？作为回报我可以给你专门定制一套外骨骼，怎么样？", voice="hero_2503_cv_14.prefab", voice1="hero_2503_cv_14.prefab", lines1="……呃……上次你的那本图鉴……是从哪里拿到的啊……可以的话能送给我吗？作为回报我可以给你专门定制一套外骨骼，怎么样？"
},
	[3115]={ lines="找我预约“做东西”要提前很长时间？嗯……的确吧？一年起？也没那么久就是了，但是如果你有需求的话，我可以让你插个队哦？", voice="hero_2503_cv_15.prefab", voice1="hero_2503_cv_15.prefab", lines1="找我预约“做东西”要提前很长时间？嗯……的确吧？一年起？也没那么久就是了，但是如果你有需求的话，我可以让你插个队哦？"
},
	[3201]={ lines="矢车菊为您效劳，无论祈愿还是告解还是做法事，都没问题哦，不过……你的钱准备好了吗？", voice="hero_2504_cv_01.prefab", voice1="hero_2504_cv_01.prefab", lines1="矢车菊为您效劳，无论祈愿还是告解还是做法事，都没问题哦，不过……你的钱准备好了吗？"
},
	[3202]={ lines="你确定这个是有工资的哦？", voice="hero_2504_cv_02.prefab", voice1="hero_2504_cv_02.prefab", lines1="你确定这个是有工资的哦？"
},
	[3203]={ lines="只会有一点点痛——", voice="hero_2504_cv_03.prefab", voice1="hero_2504_cv_03.prefab", lines1="只会有一点点痛——"
},
	[3204]={ lines="免费医疗来啦——", voice="hero_2504_cv_04.prefab", voice1="hero_2504_cv_04.prefab", lines1="免费医疗来啦——"
},
	[3205]={ lines="好吧，来个免费的福利。", voice="hero_2504_cv_05.prefab", voice1="hero_2504_cv_05.prefab", lines1="好吧，来个免费的福利。"
},
	[3206]={ lines="出工费记得结哦？", voice="hero_2504_cv_06.prefab", voice1="hero_2504_cv_06.prefab", lines1="出工费记得结哦？"
},
	[3207]={ lines="愿星辰赐你今日吉运——这句话不收费哦?", voice="hero_2504_cv_07.prefab", voice1="hero_2504_cv_07.prefab", lines1="愿星辰赐你今日吉运——这句话不收费哦?"
},
	[3208]={ lines="时间就是金钱，我的朋友，想要我加班就得给钱，可以给你打7折哦？", voice="hero_2504_cv_08.prefab", voice1="hero_2504_cv_08.prefab", lines1="时间就是金钱，我的朋友，想要我加班就得给钱，可以给你打7折哦？"
},
	[3209]={ lines="别看我这样，我也会做本职工作的——你说这动作也像是在搞钱？！", voice="hero_2504_cv_09.prefab", voice1="hero_2504_cv_09.prefab", lines1="别看我这样，我也会做本职工作的——你说这动作也像是在搞钱？！"
},
	[3210]={ lines="复习一下维拉提亚教义……嗯？这是我什么时候夹在里面的……算了，意外之喜~", voice="hero_2504_cv_10.prefab", voice1="hero_2504_cv_10.prefab", lines1="复习一下维拉提亚教义……嗯？这是我什么时候夹在里面的……算了，意外之喜~"
},
	[3211]={ lines="那啥，我能耽误你几分钟时间，给你介绍一下我们的教义吗？呃，你不用真的答应，我也不是真的要讲……", voice="hero_2504_cv_11.prefab", voice1="hero_2504_cv_11.prefab", lines1="那啥，我能耽误你几分钟时间，给你介绍一下我们的教义吗？呃，你不用真的答应，我也不是真的要讲……"
},
	[3212]={ lines="是的，没问题，任何事情都可以先问问我能不能帮得上忙——只要钱给够，绝对不会让你失望的哦。", voice="hero_2504_cv_12.prefab", voice1="hero_2504_cv_12.prefab", lines1="是的，没问题，任何事情都可以先问问我能不能帮得上忙——只要钱给够，绝对不会让你失望的哦。"
},
	[3213]={ lines="不，我不想回到维拉提亚……原因……那当然是因为我还在为修道院的传教事业鞠躬尽瘁……嗯，就是这样，你懂我的意思吧？哈哈哈哈……", voice="hero_2504_cv_13.prefab", voice1="hero_2504_cv_13.prefab", lines1="不，我不想回到维拉提亚……原因……那当然是因为我还在为修道院的传教事业鞠躬尽瘁……嗯，就是这样，你懂我的意思吧？哈哈哈哈……"
},
	[3214]={ lines="喜欢钱有什么不对吗？我觉得也没什么不好意思承认的——这世界上确实会有钱做不到的事，但没钱……做不到的事更多啊。", voice="hero_2504_cv_14.prefab", voice1="hero_2504_cv_14.prefab", lines1="喜欢钱有什么不对吗？我觉得也没什么不好意思承认的——这世界上确实会有钱做不到的事，但没钱……做不到的事更多啊。"
},
	[3215]={ lines="有时候你是不是会觉得——这一切真的有意义吗？无论是与修格尔作战，搞钱，还是追寻自由什么的……老实说哦？我以前对这类问题一直都蛮悲观的，不过和你相处这么久下来，我又觉得……好像也没有那么糟糕嘛，嘿嘿。", voice="hero_2504_cv_15.prefab", voice1="hero_2504_cv_15.prefab", lines1="有时候你是不是会觉得——这一切真的有意义吗？无论是与修格尔作战，搞钱，还是追寻自由什么的……老实说哦？我以前对这类问题一直都蛮悲观的，不过和你相处这么久下来，我又觉得……好像也没有那么糟糕嘛，嘿嘿。"
},
	[3301]={ lines="拯救世界的闪光！黑暗之中最耀眼的明星！你可以永远信任的英雄弧光前来拜访！啊？不要这么冷淡啊，给点应景的反应好不好，好不好嘛……", voice="hero_2103_cv_01.prefab", voice1="hero_2103_cv_01.prefab", lines1="拯救世界的闪光！黑暗之中最耀眼的明星！你可以永远信任的英雄弧光前来拜访！啊？不要这么冷淡啊，给点应景的反应好不好，好不好嘛……"
},
	[3302]={ lines="来吧，好戏开场了。", voice="hero_2103_cv_02.prefab", voice1="hero_2103_cv_02.prefab", lines1="来吧，好戏开场了。"
},
	[3303]={ lines="打完这波就能收工啦！", voice="hero_2103_cv_03.prefab", voice1="hero_2103_cv_03.prefab", lines1="打完这波就能收工啦！"
},
	[3304]={ lines="旋转，跳跃！", voice="hero_2103_cv_04.prefab", voice1="hero_2103_cv_04.prefab", lines1="旋转，跳跃！"
},
	[3305]={ lines="不要拦路！", voice="hero_2103_cv_05.prefab", voice1="hero_2103_cv_05.prefab", lines1="不要拦路！"
},
	[3306]={ lines="哼哼，英雄出马没有做不到的。", voice="hero_2103_cv_06.prefab", voice1="hero_2103_cv_06.prefab", lines1="哼哼，英雄出马没有做不到的。"
},
	[3307]={ lines="欢迎英雄归来！英雄是谁？当然是你和我啊——", voice="hero_2103_cv_07.prefab", voice1="hero_2103_cv_07.prefab", lines1="欢迎英雄归来！英雄是谁？当然是你和我啊——"
},
	[3308]={ lines="嗯……这么看的话，我还真是挺帅气的……", voice="hero_2103_cv_08.prefab", voice1="hero_2103_cv_08.prefab", lines1="嗯……这么看的话，我还真是挺帅气的……"
},
	[3309]={ lines="打游戏？不不不，这个是在锻炼英雄的反应速度……YES！赢了！", voice="hero_2103_cv_09.prefab", voice1="hero_2103_cv_09.prefab", lines1="打游戏？不不不，这个是在锻炼英雄的反应速度……YES！赢了！"
},
	[3310]={ lines="马上出任务？等下，还有一分钟，等一下，电子竞技没有暂停——让我存个档——啊——", voice="hero_2103_cv_10.prefab", voice1="hero_2103_cv_10.prefab", lines1="马上出任务？等下，还有一分钟，等一下，电子竞技没有暂停——让我存个档——啊——"
},
	[3311]={ lines="你喜欢打游戏？NICE！不、不是啊，我身边才不是没人和我一起玩呢，只是他们都太菜了而已。", voice="hero_2103_cv_11.prefab", voice1="hero_2103_cv_11.prefab", lines1="你喜欢打游戏？NICE！不、不是啊，我身边才不是没人和我一起玩呢，只是他们都太菜了而已。"
},
	[3312]={ lines="这个游戏借你，还有这个和这个，一定要好好体验，玩完之后我们就可以……PK了啊，嘻嘻嘻，单方面碾压太没意思了啊。", voice="hero_2103_cv_12.prefab", voice1="hero_2103_cv_12.prefab", lines1="这个游戏借你，还有这个和这个，一定要好好体验，玩完之后我们就可以……PK了啊，嘻嘻嘻，单方面碾压太没意思了啊。"
},
	[3313]={ lines="我就不明白了，为什么那么多人认为“玩游戏”不需要任何技术啊，开玩笑，想要玩得好可是要付出不知道多少心血的，你……该不会也是那种人吧？不会吧不会吧？", voice="hero_2103_cv_13.prefab", voice1="hero_2103_cv_13.prefab", lines1="我就不明白了，为什么那么多人认为“玩游戏”不需要任何技术啊，开玩笑，想要玩得好可是要付出不知道多少心血的，你……该不会也是那种人吧？不会吧不会吧？"
},
	[3314]={ lines="一起打网游？也……也不是不行啦……但是……现在的网游，不都很肝吗，又没有亲友团……你说你带我？开！开什么玩笑？！我要你带我？！哼！", voice="hero_2103_cv_14.prefab", voice1="hero_2103_cv_14.prefab", lines1="一起打网游？也……也不是不行啦……但是……现在的网游，不都很肝吗，又没有亲友团……你说你带我？开！开什么玩笑？！我要你带我？！哼！"
},
	[3315]={ lines="别打游戏啦！为什么你会这么沉迷啊！你为什么这么熟练啊！搞什么！你这不是抢了我的人设吗！呜……气死我了！想叫我原谅你，除非你……除非你带我去吃那款炒面面包——", voice="hero_2103_cv_15.prefab", voice1="hero_2103_cv_15.prefab", lines1="别打游戏啦！为什么你会这么沉迷啊！你为什么这么熟练啊！搞什么！你这不是抢了我的人设吗！呜……气死我了！想叫我原谅你，除非你……除非你带我去吃那款炒面面包——"
},
	[3401]={ lines="您好，我是莉丽拉，接下来的时间我将会负责您的健康管理和治疗支援，请多指教。", voice="hero_1503_cv_01.prefab", voice1="hero_1503_cv_01.prefab", lines1="您好，我是莉丽拉，接下来的时间我将会负责您的健康管理和治疗支援，请多指教。"
},
	[3402]={ lines="我会处理好的，请相信我。", voice="hero_1503_cv_02.prefab", voice1="hero_1503_cv_02.prefab", lines1="我会处理好的，请相信我。"
},
	[3403]={ lines="马上就好，你会没事的。", voice="hero_1503_cv_03.prefab", voice1="hero_1503_cv_03.prefab", lines1="马上就好，你会没事的。"
},
	[3404]={ lines="我不会让大家受伤的——", voice="hero_1503_cv_04.prefab", voice1="hero_1503_cv_04.prefab", lines1="我不会让大家受伤的——"
},
	[3405]={ lines="战斗还未结束，大家振作起来！", voice="hero_1503_cv_05.prefab", voice1="hero_1503_cv_05.prefab", lines1="战斗还未结束，大家振作起来！"
},
	[3406]={ lines="辛苦大家了，我来给各位检查一下吧。", voice="hero_1503_cv_06.prefab", voice1="hero_1503_cv_06.prefab", lines1="辛苦大家了，我来给各位检查一下吧。"
},
	[3407]={ lines="欢迎回来，今天也请保持好心情哦~", voice="hero_1503_cv_07.prefab", voice1="hero_1503_cv_07.prefab", lines1="欢迎回来，今天也请保持好心情哦~"
},
	[3408]={ lines="可拉兹说的猫咪伸展操是这样做的吗……\n——呀！太……太丢脸了……", voice="hero_1503_cv_08.prefab", voice1="hero_1503_cv_08.prefab", lines1="可拉兹说的猫咪伸展操是这样做的吗……\n——呀！太……太丢脸了……"
},
	[3409]={ lines="限定款的玩偶？！……啊哈哈，抱歉，我太激动了……不过，真的可以送给我吗？", voice="hero_1503_cv_09.prefab", voice1="hero_1503_cv_09.prefab", lines1="限定款的玩偶？！……啊哈哈，抱歉，我太激动了……不过，真的可以送给我吗？"
},
	[3410]={ lines="休假单顺利批下来真是太好了——那……您有空能陪我一起去中央医院看看病人们吗？", voice="hero_1503_cv_10.prefab", voice1="hero_1503_cv_10.prefab", lines1="休假单顺利批下来真是太好了——那……您有空能陪我一起去中央医院看看病人们吗？"
},
	[3411]={ lines="和大家在一起的时光很快乐，希望这样的日子能一直持续下去……", voice="hero_1503_cv_11.prefab", voice1="hero_1503_cv_11.prefab", lines1="和大家在一起的时光很快乐，希望这样的日子能一直持续下去……"
},
	[3412]={ lines="战场瞬息万变，但是……我也不会因此而退缩，因为队友们都需要我。", voice="hero_1503_cv_12.prefab", voice1="hero_1503_cv_12.prefab", lines1="战场瞬息万变，但是……我也不会因此而退缩，因为队友们都需要我。"
},
	[3413]={ lines="最近收到了很多中央医院送来的礼物呢——嗯，是那些我在照顾的小孩子们送来的，我会给他们讲故事，做些手工，虽然不能直接在身体上治疗他们，但我总希望能给他们精神上带去一些抚慰，嗯……得想想回礼是什么才行。", voice="hero_1503_cv_13.prefab", voice1="hero_1503_cv_13.prefab", lines1="最近收到了很多中央医院送来的礼物呢——嗯，是那些我在照顾的小孩子们送来的，我会给他们讲故事，做些手工，虽然不能直接在身体上治疗他们，但我总希望能给他们精神上带去一些抚慰，嗯……得想想回礼是什么才行。"
},
	[3414]={ lines="问我将来想干什么？如果可以的话，我当然是想要成为一名主治医生的，但在那之前……我要学习和努力的方面还很多呢。", voice="hero_1503_cv_14.prefab", voice1="hero_1503_cv_14.prefab", lines1="问我将来想干什么？如果可以的话，我当然是想要成为一名主治医生的，但在那之前……我要学习和努力的方面还很多呢。"
},
	[3415]={ lines="我和大家都很重视您，如果失去您的话，我不敢去想象那会是什么样子……所以，请不要勉强自己，好吗？", voice="hero_1503_cv_15.prefab", voice1="hero_1503_cv_15.prefab", lines1="我和大家都很重视您，如果失去您的话，我不敢去想象那会是什么样子……所以，请不要勉强自己，好吗？"
},
	[3416]={ lines="难得的假期，可以和最喜欢的链尉官一起度过，莉丽拉觉得现在很幸福哦，呵呵~", voice="hero_1503_cv_16.prefab", voice1="hero_1503_cv_16.prefab", lines1="难得的假期，可以和最喜欢的链尉官一起度过，莉丽拉觉得现在很幸福哦，呵呵~"
},
	[3417]={ lines="链尉官也到了休假的时间吗？呵呵，可以哦，让我们一起渡过这段美好的时间吧。", voice="", voice1="hero_1503_cv_17.prefab", lines1="呜嗯……链尉官要从这里开始吗？咿呀？！没，没关系，只是有点痒……可以玩一整天？呜~~~链尉官真是的~~！"
},
	[3418]={ lines="链尉官喜欢看书吗？那我向你推荐这一本，里面的故事和我们的经历非常像呢。", voice="", voice1="hero_1503_cv_18.prefab", lines1="……链尉官也想感，感受一下？！嗯……可以哦……"
},
	[3430]={ lines="链尉官……醒来了吗？早上好，新的一天开始了呢~", voice="", voice1="hero_1503_cv_1001.prefab", lines1="链尉官……醒来了吗？早上好，新的一天开始了呢~"
},
	[3431]={ lines="——唔啊？！哈哈，早上的你精力真好呢~", voice="", voice1="hero_1503_cv_1002.prefab", lines1="——唔啊？！嗯呜……早上的你也这么有活力呢……"
},
	[3432]={ lines="悠闲的时光想要和链尉官一起度过呢……嗯啊——链尉官也是这么想的吗？", voice="", voice1="hero_1503_cv_1003.prefab", lines1="悠闲的时光想要和链尉官一起度过呢……嗯啊——链尉官也是这么想的吗？"
},
	[3433]={ lines="精心准备的蛋糕马上就要完成了呢，最后这一步……就交给链尉官来吧？", voice="", voice1="hero_1503_cv_1004.prefab", lines1="精心准备的蛋糕马上就要完成了呢，最后这一步……就交给链尉官来吧？"
},
	[3434]={ lines="大功告成~！", voice="", voice1="hero_1503_cv_1005.prefab", lines1="大功告成~！"
},
	[3435]={ lines="就是这样！", voice="", voice1="hero_1503_cv_1006.prefab", lines1="就是这样！"
},
	[3436]={ lines="太棒啦！", voice="", voice1="hero_1503_cv_1007.prefab", lines1="太棒啦！"
},
	[3437]={ lines="唔……链尉官……", voice="", voice1="hero_1503_cv_1008.prefab", lines1="唔……链尉官……"
},
	[3438]={ lines="怎么了吗？", voice="", voice1="hero_1503_cv_1009_1.prefab", lines1="啊嗯……！"
},
	[3439]={ lines="怎么了吗？", voice="", voice1="hero_1503_cv_1009_2.prefab", lines1="啊嗯……！"
},
	[3440]={ lines="怎么了吗？", voice="", voice1="hero_1503_cv_1009_3.prefab", lines1="啊嗯……！"
},
	[3441]={ lines="怎么了吗？", voice="", voice1="hero_1503_cv_1009_4.prefab", lines1="啊嗯……！"
},
	[3442]={ lines="链尉官在做什么呢？", voice="", voice1="hero_1503_cv_1010.prefab", lines1="这里……也要吗……"
},
	[3443]={ lines="链尉官在做什么呢？", voice="", voice1="hero_1503_cv_1011_1.prefab", lines1="呜嗯……！"
},
	[3444]={ lines="链尉官在做什么呢？", voice="", voice1="hero_1503_cv_1011_2.prefab", lines1="呜嗯……！"
},
	[3445]={ lines="链尉官在做什么呢？", voice="", voice1="hero_1503_cv_1011_3.prefab", lines1="呜嗯……！"
},
	[3446]={ lines="链尉官在做什么呢？", voice="", voice1="hero_1503_cv_1011_4.prefab", lines1="呜嗯……！"
},
	[3447]={ lines="蛋糕做好了，链尉官会给我什么样的奖励呢？嘿嘿，希望是可爱的东西呢。", voice="", voice1="hero_1503_cv_1012.prefab", lines1="不只是蛋糕，还想要“把我也吃掉”吗……呜……链尉官总是欺负我……哈啊？！呜嗯……！我也……准备好了……❤"
},
	[3448]={ lines="……呀？！水怎么变凉了……链尉官你在吗？可以帮我……调一下水温吗？", voice="", voice1="hero_1503_cv_1013.prefab", lines1="……呀？！水怎么变凉了……链尉官你在吗？可以帮我……调一下水温吗？"
},
	[3449]={ lines="呀？！好冷呀！", voice="", voice1="hero_1503_cv_1014_1.prefab", lines1="呀？！好冷呀！"
},
	[3450]={ lines="呀？！好冷呀！", voice="", voice1="hero_1503_cv_1014_2.prefab", lines1="呀？！好冷呀！"
},
	[3451]={ lines="呜呜？！好烫呀！", voice="", voice1="hero_1503_cv_1015_1.prefab", lines1="呜呜？！好烫呀！"
},
	[3452]={ lines="呜呜？！好烫呀！", voice="", voice1="hero_1503_cv_1015_2.prefab", lines1="呜呜？！好烫呀！"
},
	[3453]={ lines="水温真舒服呢，洗完以后，会有一天的好心情了~", voice="", voice1="hero_1503_cv_1016.prefab", lines1="诶？背后也要按摩一下……？呜嗯？！嗯啊？！等等……嗯啊——！！！哈……哈……"
},
	[3454]={ lines="链尉官~！", voice="", voice1="hero_1503_cv_1017.prefab", lines1="链尉官~！"
},
	[3455]={ lines="哎呀~！", voice="", voice1="hero_1503_cv_1018_1.prefab", lines1="哎呀~！"
},
	[3456]={ lines="哎呀~！", voice="", voice1="hero_1503_cv_1018_2.prefab", lines1="哎呀~！"
},
	[3457]={ lines="哎呀~！", voice="", voice1="hero_1503_cv_1018_3.prefab", lines1="哎呀~！"
},
	[3458]={ lines="呵呵呵~~现在到我的回合了呢，要闭上眼睛哦……", voice="", voice1="hero_1503_cv_1019.prefab", lines1="呜嗯？嗯啊！……嗯呵呵呵~~现在到我的回合了呢，要闭上眼睛哦……"
},
	[3459]={ lines="真是的，链尉官真调皮……", voice="", voice1="hero_1503_cv_1020_1.prefab", lines1="呜~真是的，链尉官真调皮……"
},
	[3460]={ lines="真是的，链尉官真调皮……", voice="", voice1="hero_1503_cv_1020_2.prefab", lines1="呜~真是的，链尉官真调皮……"
},
	[3461]={ lines="呵呵~", voice="", voice1="hero_1503_cv_1021_1.prefab", lines1="嗯啊~"
},
	[3462]={ lines="呵呵~", voice="", voice1="hero_1503_cv_1021_2.prefab", lines1="嗯啊~"
},
	[3463]={ lines="呵呵~", voice="", voice1="hero_1503_cv_1021_3.prefab", lines1="嗯啊~"
},
	[3464]={ lines="呵呵~", voice="", voice1="hero_1503_cv_1022_1.prefab", lines1="呜嗯……哈……"
},
	[3465]={ lines="呵呵~", voice="", voice1="hero_1503_cv_1022_2.prefab", lines1="呜嗯……哈……"
},
	[3466]={ lines="呵呵~", voice="", voice1="hero_1503_cv_1022_3.prefab", lines1="呜嗯……哈……"
},
	[3501]={ lines="我叫劳瑞拉，他们都叫我野猫，你也这么叫好了？", voice="hero_1103_cv_01.prefab", voice1="hero_1103_cv_01.prefab", lines1="我叫劳瑞拉，他们都叫我野猫，你也这么叫好了？"
},
	[3502]={ lines="要和他们玩吗？", voice="hero_1103_cv_02.prefab", voice1="hero_1103_cv_02.prefab", lines1="要和他们玩吗？"
},
	[3503]={ lines="挠死你！", voice="hero_1103_cv_03.prefab", voice1="hero_1103_cv_03.prefab", lines1="挠死你！"
},
	[3504]={ lines="不要……小看我！", voice="hero_1103_cv_04.prefab", voice1="hero_1103_cv_04.prefab", lines1="不要……小看我！"
},
	[3505]={ lines="别想逃！打爆你！", voice="hero_1103_cv_05.prefab", voice1="hero_1103_cv_05.prefab", lines1="别想逃！打爆你！"
},
	[3506]={ lines="轻轻松松，嗯~", voice="hero_1103_cv_06.prefab", voice1="hero_1103_cv_06.prefab", lines1="轻轻松松，嗯~"
},
	[3507]={ lines="你好，小鱼干，要吃吗？", voice="hero_1103_cv_07.prefab", voice1="hero_1103_cv_07.prefab", lines1="你好，小鱼干，要吃吗？"
},
	[3508]={ lines="看我给你喷一个……嗯，不错，真不愧是我。", voice="hero_1103_cv_08.prefab", voice1="hero_1103_cv_08.prefab", lines1="看我给你喷一个……嗯，不错，真不愧是我。"
},
	[3509]={ lines="今天要玩什么？要不和我打个拳吧？", voice="hero_1103_cv_09.prefab", voice1="hero_1103_cv_09.prefab", lines1="今天要玩什么？要不和我打个拳吧？"
},
	[3510]={ lines="爪子好像有点脏了……要不要洗一下呢？", voice="hero_1103_cv_10.prefab", voice1="hero_1103_cv_10.prefab", lines1="爪子好像有点脏了……要不要洗一下呢？"
},
	[3511]={ lines="哼，不认识的家伙，不想理你。", voice="hero_1103_cv_11.prefab", voice1="hero_1103_cv_11.prefab", lines1="哼，不认识的家伙，不想理你。"
},
	[3512]={ lines="要不要吃小鱼干？虽然我也有点饿，但是给你吃两条还行。", voice="hero_1103_cv_12.prefab", voice1="hero_1103_cv_12.prefab", lines1="要不要吃小鱼干？虽然我也有点饿，但是给你吃两条还行。"
},
	[3513]={ lines="想和我并肩作战？我的爪子打起来可没有眼睛哦。", voice="hero_1103_cv_13.prefab", voice1="hero_1103_cv_13.prefab", lines1="想和我并肩作战？我的爪子打起来可没有眼睛哦。"
},
	[3514]={ lines="这里能吃饱饭，也不会有人强迫我去战斗，我可以做自己喜欢的事情，比如一直晒太阳……你饿了吗？好吧，我可以分你一条小鱼干。", voice="hero_1103_cv_14.prefab", voice1="hero_1103_cv_14.prefab", lines1="这里能吃饱饭，也不会有人强迫我去战斗，我可以做自己喜欢的事情，比如一直晒太阳……你饿了吗？好吧，我可以分你一条小鱼干。"
},
	[3515]={ lines="我以前不是这样的，我也不想发脾气，可是我控制不了自己，不过现在这样也好吧，至少大家都不敢随意欺负我——你很像那个喂过我的人，我不会随意揍你的，我向你保证。", voice="hero_1103_cv_15.prefab", voice1="hero_1103_cv_15.prefab", lines1="我以前不是这样的，我也不想发脾气，可是我控制不了自己，不过现在这样也好吧，至少大家都不敢随意欺负我——你很像那个喂过我的人，我不会随意揍你的，我向你保证。"
},
	[3601]={ lines="我是“圆梦人”事务所的老板，纽卡斯尔，我可以成为你的眼睛，你的耳朵，为你带来一切你想要的信息，只要价格合适的话。", voice="hero_1105_cv_01.prefab", voice1="hero_1105_cv_01.prefab", lines1="我是“圆梦人”事务所的老板，纽卡斯尔，我可以成为你的眼睛，你的耳朵，为你带来一切你想要的信息，只要价格合适的话。"
},
	[3602]={ lines="准备好落子了吗？", voice="hero_1105_cv_02.prefab", voice1="hero_1105_cv_02.prefab", lines1="准备好落子了吗？"
},
	[3603]={ lines="压制？是碾压——", voice="hero_1105_cv_03.prefab", voice1="hero_1105_cv_03.prefab", lines1="压制？是碾压——"
},
	[3604]={ lines="走错棋的后果是很严重的！", voice="hero_1105_cv_04.prefab", voice1="hero_1105_cv_04.prefab", lines1="走错棋的后果是很严重的！"
},
	[3605]={ lines="结局已定——将军——", voice="hero_1105_cv_05.prefab", voice1="hero_1105_cv_05.prefab", lines1="结局已定——将军——"
},
	[3606]={ lines="业务结束，账单回头会发给你的。", voice="hero_1105_cv_06.prefab", voice1="hero_1105_cv_06.prefab", lines1="业务结束，账单回头会发给你的。"
},
	[3607]={ lines="你好呀，时间就是金钱，金主老板，请尽快开始我们的工作吧。", voice="hero_1105_cv_07.prefab", voice1="hero_1105_cv_07.prefab", lines1="你好呀，时间就是金钱，金主老板，请尽快开始我们的工作吧。"
},
	[3608]={ lines="新的委托？本所当然可以接下，不如说还可以再来多点。", voice="hero_1105_cv_08.prefab", voice1="hero_1105_cv_08.prefab", lines1="新的委托？本所当然可以接下，不如说还可以再来多点。"
},
	[3609]={ lines="最近所内的业务越来越频繁了，从某些角度来说，算是一件“坏事”？", voice="hero_1105_cv_09.prefab", voice1="hero_1105_cv_09.prefab", lines1="最近所内的业务越来越频繁了，从某些角度来说，算是一件“坏事”？"
},
	[3610]={ lines="情报是任何时代的底牌，只有掌握了情报，才能打开通往财富的大门。", voice="hero_1105_cv_10.prefab", voice1="hero_1105_cv_10.prefab", lines1="情报是任何时代的底牌，只有掌握了情报，才能打开通往财富的大门。"
},
	[3611]={ lines="定金应该准备好了吧？——嗯，数额没错，准备开工了。", voice="hero_1105_cv_11.prefab", voice1="hero_1105_cv_11.prefab", lines1="定金应该准备好了吧？——嗯，数额没错，准备开工了。"
},
	[3612]={ lines="天下攘攘皆为利往——虽然这句话放到现在也不过时，但也有与之观念相反的人存在，你呢？你怎么认为？", voice="hero_1105_cv_12.prefab", voice1="hero_1105_cv_12.prefab", lines1="天下攘攘皆为利往——虽然这句话放到现在也不过时，但也有与之观念相反的人存在，你呢？你怎么认为？"
},
	[3613]={ lines="也许有一天，我会拜托你帮我保护好这家事务所。……不，这是我的个人请求，当然，我也希望这一天永远不会到来。", voice="hero_1105_cv_13.prefab", voice1="hero_1105_cv_13.prefab", lines1="也许有一天，我会拜托你帮我保护好这家事务所。……不，这是我的个人请求，当然，我也希望这一天永远不会到来。"
},
	[3614]={ lines="这是我的名片，一般客户可拿不到这个——你还不明白？拿着它，你就是我的私人VIP了", voice="hero_1105_cv_14.prefab", voice1="hero_1105_cv_14.prefab", lines1="这是我的名片，一般客户可拿不到这个——你还不明白？拿着它，你就是我的私人VIP了"
},
	[3615]={ lines="要来事务所坐一坐吗？这次……算是私人邀请吧，也许我们能从聊生意发展到聊生活？", voice="hero_1105_cv_15.prefab", voice1="hero_1105_cv_15.prefab", lines1="要来事务所坐一坐吗？这次……算是私人邀请吧，也许我们能从聊生意发展到聊生活？"
},
	[3616]={ lines="唔，我好像动弹不得了呢……帮帮我好吗？链尉官~", voice="hero_1105_cv_16.prefab", voice1="hero_1105_cv_16.prefab", lines1="唔，我好像动弹不得了呢……帮帮我好吗？链尉官~"
},
	[3617]={ lines="起风了啊……是不是很懂你的心呢？想看更多的话，就亲自动手吧~", voice="hero_1105_cv_17.prefab", voice1="hero_1105_cv_17.prefab", lines1="起风了啊……是不是很懂你的心呢？想看更多的话，就亲自动手吧~"
},
	[3618]={ lines="要和我共舞一曲吗？作为一点沟通心灵的小小把戏……然后，你可以尽情索取自己想要的报酬~", voice="hero_1105_cv_18.prefab", voice1="hero_1105_cv_18.prefab", lines1="要和我共舞一曲吗？作为一点沟通心灵的小小把戏……然后，你可以尽情索取自己想要的报酬~"
},
	[3701]={ lines="初次见面，主人。我是珂尔，所有的工作都可以交给我！", voice="hero_1504_cv_01.prefab", voice1="hero_1504_cv_01.prefab", lines1="初次见面，主人。我是珂尔，所有的工作都可以交给我！"
},
	[3702]={ lines="保证完成所有工作！", voice="hero_1504_cv_02.prefab", voice1="hero_1504_cv_02.prefab", lines1="保证完成所有工作！"
},
	[3703]={ lines="绝对不允许你妨碍主人。", voice="hero_1504_cv_03.prefab", voice1="hero_1504_cv_03.prefab", lines1="绝对不允许你妨碍主人。"
},
	[3704]={ lines="小事一桩——", voice="hero_1504_cv_04.prefab", voice1="hero_1504_cv_04.prefab", lines1="小事一桩——"
},
	[3705]={ lines="瑞比，去，把他们都干掉——", voice="hero_1504_cv_05.prefab", voice1="hero_1504_cv_05.prefab", lines1="瑞比，去，把他们都干掉——"
},
	[3706]={ lines="今天的珂尔，也为主人排忧解难了！", voice="hero_1504_cv_06.prefab", voice1="hero_1504_cv_06.prefab", lines1="今天的珂尔，也为主人排忧解难了！"
},
	[3707]={ lines="早安，主人~珂、珂尔早就起来了，绝对不是刚刚才起床哦！", voice="hero_1504_cv_07.prefab", voice1="hero_1504_cv_07.prefab", lines1="早安，主人~珂、珂尔早就起来了，绝对不是刚刚才起床哦！"
},
	[3708]={ lines="珂尔这个样子……有什么能为主人做的么？", voice="hero_1504_cv_08.prefab", voice1="hero_1504_cv_08.prefab", lines1="珂尔这个样子……有什么能为主人做的么？"
},
	[3709]={ lines="今天的日程，没问题，这就为主人安排！", voice="hero_1504_cv_09.prefab", voice1="hero_1504_cv_09.prefab", lines1="今天的日程，没问题，这就为主人安排！"
},
	[3710]={ lines="诶？珂尔的头饰，主人也喜欢吗？", voice="hero_1504_cv_10.prefab", voice1="hero_1504_cv_10.prefab", lines1="诶？珂尔的头饰，主人也喜欢吗？"
},
	[3711]={ lines="如果主人觉得累了，请记得随时来找珂尔哦！", voice="hero_1504_cv_11.prefab", voice1="hero_1504_cv_11.prefab", lines1="如果主人觉得累了，请记得随时来找珂尔哦！"
},
	[3712]={ lines="所有的工作，主人都吩咐给珂尔吧！诶？什么，没有？呜……难道主人已经不再信任珂尔了吗？", voice="hero_1504_cv_12.prefab", voice1="hero_1504_cv_12.prefab", lines1="所有的工作，主人都吩咐给珂尔吧！诶？什么，没有？呜……难道主人已经不再信任珂尔了吗？"
},
	[3713]={ lines="要成为一名优秀的万能女仆，珂尔还需要再努力一下呢！今天的目标就先从看完这本《女仆工作指南》开始吧……欸？！什么？已经到开店时间了？！", voice="hero_1504_cv_13.prefab", voice1="hero_1504_cv_13.prefab", lines1="要成为一名优秀的万能女仆，珂尔还需要再努力一下呢！今天的目标就先从看完这本《女仆工作指南》开始吧……欸？！什么？已经到开店时间了？！"
},
	[3714]={ lines="珂尔因为躲避以前朋友所以缺勤的传闻……居然传到主人这里了吗……嗯……其实……其实……诶？主人让我别在意其他人的想法？嗯！珂尔会记住主人的话的！", voice="hero_1504_cv_14.prefab", voice1="hero_1504_cv_14.prefab", lines1="珂尔因为躲避以前朋友所以缺勤的传闻……居然传到主人这里了吗……嗯……其实……其实……诶？主人让我别在意其他人的想法？嗯！珂尔会记住主人的话的！"
},
	[3715]={ lines="要是事情没办好，主人会惩罚我吗？不……不是……珂尔没有那方面的想法……", voice="hero_1504_cv_15.prefab", voice1="hero_1504_cv_15.prefab", lines1="要是事情没办好，主人会惩罚我吗？不……不是……珂尔没有那方面的想法……"
},
	[3801]={ lines="莱斯坦斯工程部所属，战员戈米娅，代号扳机，前来报到，以上是正式的自我介绍——哎呀，真是不习惯。", voice="hero_1502_cv_01.prefab", voice1="hero_1502_cv_01.prefab", lines1="莱斯坦斯工程部所属，战员戈米娅，代号扳机，前来报到，以上是正式的自我介绍——哎呀，真是不习惯。"
},
	[3802]={ lines="热机完成，随时待命。", voice="hero_1502_cv_02.prefab", voice1="hero_1502_cv_02.prefab", lines1="热机完成，随时待命。"
},
	[3803]={ lines="电磁霰弹，发射！", voice="hero_1502_cv_03.prefab", voice1="hero_1502_cv_03.prefab", lines1="电磁霰弹，发射！"
},
	[3804]={ lines="这样如何？", voice="hero_1502_cv_04.prefab", voice1="hero_1502_cv_04.prefab", lines1="这样如何？"
},
	[3805]={ lines="饱和式轰炸——好像不是很饱和的样子？！", voice="hero_1502_cv_05.prefab", voice1="hero_1502_cv_05.prefab", lines1="饱和式轰炸——好像不是很饱和的样子？！"
},
	[3806]={ lines="装备热值都在可控范围内，辛苦了。", voice="hero_1502_cv_06.prefab", voice1="hero_1502_cv_06.prefab", lines1="装备热值都在可控范围内，辛苦了。"
},
	[3807]={ lines="嗨，你好呀，你也准备开工了吗？", voice="hero_1502_cv_07.prefab", voice1="hero_1502_cv_07.prefab", lines1="嗨，你好呀，你也准备开工了吗？"
},
	[3808]={ lines="这份图纸……这样……然后这样……啊！没，没什么，你什么时候过来的？", voice="hero_1502_cv_08.prefab", voice1="hero_1502_cv_08.prefab", lines1="这份图纸……这样……然后这样……啊！没，没什么，你什么时候过来的？"
},
	[3809]={ lines="那次测试到底是哪里出了问题……为什么会爆炸……想不通啊真是想不通啊啊！！", voice="hero_1502_cv_09.prefab", voice1="hero_1502_cv_09.prefab", lines1="那次测试到底是哪里出了问题……为什么会爆炸……想不通啊真是想不通啊啊！！"
},
	[3810]={ lines="那什么……链尉官，嘻嘻……这次的订单预算能不能再通融一些……拜托了！就这一次！一次！", voice="hero_1502_cv_10.prefab", voice1="hero_1502_cv_10.prefab", lines1="那什么……链尉官，嘻嘻……这次的订单预算能不能再通融一些……拜托了！就这一次！一次！"
},
	[3811]={ lines="链尉官，休息的时候可以来我的工作间坐一坐，虽然有点乱就是啦，嘿嘿……", voice="hero_1502_cv_11.prefab", voice1="hero_1502_cv_11.prefab", lines1="链尉官，休息的时候可以来我的工作间坐一坐，虽然有点乱就是啦，嘿嘿……"
},
	[3812]={ lines="源晶武装？啊，你说我背后的这个机械臂吗？这是我自己制作出来的，原理的话就是……你真的有在听吗？", voice="hero_1502_cv_12.prefab", voice1="hero_1502_cv_12.prefab", lines1="源晶武装？啊，你说我背后的这个机械臂吗？这是我自己制作出来的，原理的话就是……你真的有在听吗？"
},
	[3813]={ lines="为什么要选择上战场？不为什么啊……总是有人要做事的嘛，而且我的能力适合做这个，就这么简单嘛，倒是链尉官你呀，老是想这想那的，会长白头发的哦？", voice="hero_1502_cv_13.prefab", voice1="hero_1502_cv_13.prefab", lines1="为什么要选择上战场？不为什么啊……总是有人要做事的嘛，而且我的能力适合做这个，就这么简单嘛，倒是链尉官你呀，老是想这想那的，会长白头发的哦？"
},
	[3814]={ lines="双硕士学位？啊，我的确是双硕士学位，就……挺简单的吧？不是啊我真的不是在自夸，我是享受学习的那种类型，学着学着学分就修满了，真的，真的是这样的，哎呀我真的不是在吹嘘呀你要相信我啊——", voice="hero_1502_cv_14.prefab", voice1="hero_1502_cv_14.prefab", lines1="双硕士学位？啊，我的确是双硕士学位，就……挺简单的吧？不是啊我真的不是在自夸，我是享受学习的那种类型，学着学着学分就修满了，真的，真的是这样的，哎呀我真的不是在吹嘘呀你要相信我啊——"
},
	[3815]={ lines="我经常会想啊，如果有一天，当所有的纷争都落下帷幕，我制造的这些武器，能怎么转化到民用的和平领域呢？……你不要觉得这是个沉重的话题，这是很有意思的事情，而且这不也代表着，我相信着那一天一定会到来吗？要不你和我一起想一想吧？怎么样啊？", voice="hero_1502_cv_15.prefab", voice1="hero_1502_cv_15.prefab", lines1="我经常会想啊，如果有一天，当所有的纷争都落下帷幕，我制造的这些武器，能怎么转化到民用的和平领域呢？……你不要觉得这是个沉重的话题，这是很有意思的事情，而且这不也代表着，我相信着那一天一定会到来吗？要不你和我一起想一想吧？怎么样啊？"
},
	[3901]={ lines="哈喽哈喽，你就是链尉官吗？我是凯伦蒂洛，大家都喜欢喊我雪狐，哎？！可不是因为头上的耳朵唉！你可别不相信呀！", voice="hero_1501_cv_01.prefab", voice1="hero_1501_cv_01.prefab", lines1="哈喽哈喽，你就是链尉官吗？我是凯伦蒂洛，大家都喜欢喊我雪狐，哎？！可不是因为头上的耳朵唉！你可别不相信呀！"
},
	[3902]={ lines="看我把它们全部打飞！", voice="hero_1501_cv_02.prefab", voice1="hero_1501_cv_02.prefab", lines1="看我把它们全部打飞！"
},
	[3903]={ lines="看招！", voice="hero_1501_cv_03.prefab", voice1="hero_1501_cv_03.prefab", lines1="看招！"
},
	[3904]={ lines="小心流弹——", voice="hero_1501_cv_04.prefab", voice1="hero_1501_cv_04.prefab", lines1="小心流弹——"
},
	[3905]={ lines="看上面，小心咯——", voice="hero_1501_cv_05.prefab", voice1="hero_1501_cv_05.prefab", lines1="看上面，小心咯——"
},
	[3906]={ lines="怎么样，我的表现还好吧？下次也放心交给我哦！", voice="hero_1501_cv_06.prefab", voice1="hero_1501_cv_06.prefab", lines1="怎么样，我的表现还好吧？下次也放心交给我哦！"
},
	[3907]={ lines="你好呀！要不要一起吃饭！哎？你有事哦，那算了……", voice="hero_1501_cv_07.prefab", voice1="hero_1501_cv_07.prefab", lines1="你好呀！要不要一起吃饭！哎？你有事哦，那算了……"
},
	[3908]={ lines="唔……早上起来面向太阳……还是好困啊，要不要再去睡一会呢？", voice="hero_1501_cv_08.prefab", voice1="hero_1501_cv_08.prefab", lines1="唔……早上起来面向太阳……还是好困啊，要不要再去睡一会呢？"
},
	[3909]={ lines="你知道兔子是怎么跳舞的嘛……就像这样……", voice="hero_1501_cv_09.prefab", voice1="hero_1501_cv_09.prefab", lines1="你知道兔子是怎么跳舞的嘛……就像这样……"
},
	[3910]={ lines="好热好热，制冷到底有没有生效呀？", voice="hero_1501_cv_10.prefab", voice1="hero_1501_cv_10.prefab", lines1="好热好热，制冷到底有没有生效呀？"
},
	[3911]={ lines="她们说我每天总是话很多，有吗，我觉得还好啊。你觉得呢，链尉官？我话很多吗？我只是有好多好多的想法想要跟大家一起分享而已嘛！", voice="hero_1501_cv_11.prefab", voice1="hero_1501_cv_11.prefab", lines1="她们说我每天总是话很多，有吗，我觉得还好啊。你觉得呢，链尉官？我话很多吗？我只是有好多好多的想法想要跟大家一起分享而已嘛！"
},
	[3912]={ lines="嗨~链尉官，要不要带我去参观一下？诶？你也不太熟悉，没关系啦，刚好我们可以一起逛逛，不过……你真的是在这里工作的？要不然怎么会不熟呢？", voice="hero_1501_cv_12.prefab", voice1="hero_1501_cv_12.prefab", lines1="嗨~链尉官，要不要带我去参观一下？诶？你也不太熟悉，没关系啦，刚好我们可以一起逛逛，不过……你真的是在这里工作的？要不然怎么会不熟呢？"
},
	[3913]={ lines="为什么戴这个雪狐头饰？因为我想要混进雪狐群里啦——我小时候在雪原上碰到过一只能听懂我话的雪狐……啊这个故事上次说过了？那……那再听一次嘛？！", voice="hero_1501_cv_13.prefab", voice1="hero_1501_cv_13.prefab", lines1="为什么戴这个雪狐头饰？因为我想要混进雪狐群里啦——我小时候在雪原上碰到过一只能听懂我话的雪狐……啊这个故事上次说过了？那……那再听一次嘛？！"
},
	[3914]={ lines="据说对着极光许愿就可以实现心愿哦。你有什么心愿吗？诶，不告诉我？不要这么小气嘛！那我把我的心愿告诉你，咱们交换秘密，好不好？", voice="hero_1501_cv_14.prefab", voice1="hero_1501_cv_14.prefab", lines1="据说对着极光许愿就可以实现心愿哦。你有什么心愿吗？诶，不告诉我？不要这么小气嘛！那我把我的心愿告诉你，咱们交换秘密，好不好？"
},
	[3915]={ lines="咳……别看我平时大大咧咧，其实我知道的，极北那边越来越不平静了……不过也没事啦，真的出事的时候，你一定会和我一起回去守护大家对吧？", voice="hero_1501_cv_15.prefab", voice1="hero_1501_cv_15.prefab", lines1="咳……别看我平时大大咧咧，其实我知道的，极北那边越来越不平静了……不过也没事啦，真的出事的时候，你一定会和我一起回去守护大家对吧？"
},
	[4001]={ lines="卡苏丽·赫拉克勒斯，代号焰羽，有什么需要我做的都可以吩咐，我会尽力做好的。", voice="hero_1104_cv_01.prefab", voice1="hero_1104_cv_01.prefab", lines1="卡苏丽·赫拉克勒斯，代号焰羽，有什么需要我做的都可以吩咐，我会尽力做好的。"
},
	[4002]={ lines="我一定会好好完成任务。", voice="hero_1104_cv_02.prefab", voice1="hero_1104_cv_02.prefab", lines1="我一定会好好完成任务。"
},
	[4003]={ lines="被火焰吞没吧。", voice="hero_1104_cv_03.prefab", voice1="hero_1104_cv_03.prefab", lines1="被火焰吞没吧。"
},
	[4004]={ lines="炎羽，席卷目标。", voice="hero_1104_cv_04.prefab", voice1="hero_1104_cv_04.prefab", lines1="炎羽，席卷目标。"
},
	[4005]={ lines="能量填充溢出——消失吧——", voice="hero_1104_cv_05.prefab", voice1="hero_1104_cv_05.prefab", lines1="能量填充溢出——消失吧——"
},
	[4006]={ lines="太好了，没有辜负您的期望。", voice="hero_1104_cv_06.prefab", voice1="hero_1104_cv_06.prefab", lines1="太好了，没有辜负您的期望。"
},
	[4007]={ lines="早安，今天的天气很好呢，希望您的心情也是如此。", voice="hero_1104_cv_07.prefab", voice1="hero_1104_cv_07.prefab", lines1="早安，今天的天气很好呢，希望您的心情也是如此。"
},
	[4008]={ lines="好和煦的风……和我故乡的风一样呢……", voice="hero_1104_cv_08.prefab", voice1="hero_1104_cv_08.prefab", lines1="好和煦的风……和我故乡的风一样呢……"
},
	[4009]={ lines="送您一个小礼物，它可是能飞的哦~", voice="hero_1104_cv_09.prefab", voice1="hero_1104_cv_09.prefab", lines1="送您一个小礼物，它可是能飞的哦~"
},
	[4010]={ lines="他们说这个姿势做起来很帅气，是这样么……", voice="hero_1104_cv_10.prefab", voice1="hero_1104_cv_10.prefab", lines1="他们说这个姿势做起来很帅气，是这样么……"
},
	[4011]={ lines="如果有任何需要我帮忙的事情，请尽管来找我吧", voice="hero_1104_cv_11.prefab", voice1="hero_1104_cv_11.prefab", lines1="如果有任何需要我帮忙的事情，请尽管来找我吧"
},
	[4012]={ lines="我会不会想念家乡？……偶尔也会呢，主要是……想念我的弟弟妹妹们，也不知道她们现在怎么样了……啊，抱歉，说了些会让您担心的话。", voice="hero_1104_cv_12.prefab", voice1="hero_1104_cv_12.prefab", lines1="我会不会想念家乡？……偶尔也会呢，主要是……想念我的弟弟妹妹们，也不知道她们现在怎么样了……啊，抱歉，说了些会让您担心的话。"
},
	[4013]={ lines="不知道为什么，看到您，总会让我想起我的弟弟妹妹们……啊，不，不是说长相……是那种相处时的感觉，很亲切，又很安心。", voice="hero_1104_cv_13.prefab", voice1="hero_1104_cv_13.prefab", lines1="不知道为什么，看到您，总会让我想起我的弟弟妹妹们……啊，不，不是说长相……是那种相处时的感觉，很亲切，又很安心。"
},
	[4014]={ lines="我在折什么东西？是专属于您的纸鹤，在我的故乡，纸鹤意味着祝福，希望它能为您带来幸运。", voice="hero_1104_cv_14.prefab", voice1="hero_1104_cv_14.prefab", lines1="我在折什么东西？是专属于您的纸鹤，在我的故乡，纸鹤意味着祝福，希望它能为您带来幸运。"
},
	[4015]={ lines="您累了吧？要不要我帮您按摩一下肩膀？呵呵，不会显得您孩子气的，倒不如说，我希望您能更依赖我一点。", voice="hero_1104_cv_15.prefab", voice1="hero_1104_cv_15.prefab", lines1="您累了吧？要不要我帮您按摩一下肩膀？呵呵，不会显得您孩子气的，倒不如说，我希望您能更依赖我一点。"
},
	[4101]={ lines="初次见面，我是“灵鹿祭司”——达瓦林。", voice="hero_4508_cv_01.prefab", voice1="hero_4508_cv_01.prefab", lines1="初次见面，我是“灵鹿祭司”——达瓦林。"
},
	[4102]={ lines="我一定可以帮上忙的...", voice="hero_4508_cv_02.prefab", voice1="hero_4508_cv_02.prefab", lines1="我一定可以帮上忙的..."
},
	[4103]={ lines="生长——", voice="hero_4508_cv_03.prefab", voice1="hero_4508_cv_03.prefab", lines1="生长——"
},
	[4104]={ lines="绽放吧——绿意！", voice="hero_4508_cv_04.prefab", voice1="hero_4508_cv_04.prefab", lines1="绽放吧——绿意！"
},
	[4105]={ lines="感受灵鹿的力量吧！", voice="hero_4508_cv_05.prefab", voice1="hero_4508_cv_05.prefab", lines1="感受灵鹿的力量吧！"
},
	[4106]={ lines="任务完成了！", voice="hero_4508_cv_06.prefab", voice1="hero_4508_cv_06.prefab", lines1="任务完成了！"
},
	[4107]={ lines="又见到你了，真好。", voice="hero_4508_cv_07.prefab", voice1="hero_4508_cv_07.prefab", lines1="又见到你了，真好。"
},
	[4108]={ lines="好久没见到我的花花草草了……", voice="hero_4508_cv_08.prefab", voice1="hero_4508_cv_08.prefab", lines1="好久没见到我的花花草草了……"
},
	[4109]={ lines="链尉官，有兴趣和我去斯利普尼尔吗？那里有很大一片草原。", voice="hero_4508_cv_09.prefab", voice1="hero_4508_cv_09.prefab", lines1="链尉官，有兴趣和我去斯利普尼尔吗？那里有很大一片草原。"
},
	[4110]={ lines="哪里可以种花呢？", voice="hero_4508_cv_10.prefab", voice1="hero_4508_cv_10.prefab", lines1="哪里可以种花呢？"
},
	[4111]={ lines="链尉官，您喜欢小动物吗？哪种都行，不管是毛茸茸的，还是滑溜溜的……", voice="hero_4508_cv_11.prefab", voice1="hero_4508_cv_11.prefab", lines1="链尉官，您喜欢小动物吗？哪种都行，不管是毛茸茸的，还是滑溜溜的……"
},
	[4112]={ lines="要放松一下吗，链尉官？不嫌弃的话，可以和我一起去浇灌植物，看着那些花草，心情会感觉很愉悦，至少我是这样的。", voice="hero_4508_cv_12.prefab", voice1="hero_4508_cv_12.prefab", lines1="要放松一下吗，链尉官？不嫌弃的话，可以和我一起去浇灌植物，看着那些花草，心情会感觉很愉悦，至少我是这样的。"
},
	[4113]={ lines="我很喜欢在静谧的夜晚，坐在草原上聆听大地的低语，望着小动物们嬉戏不休，感受勃发的生机，这样的世界真美好。", voice="hero_4508_cv_13.prefab", voice1="hero_4508_cv_13.prefab", lines1="我很喜欢在静谧的夜晚，坐在草原上聆听大地的低语，望着小动物们嬉戏不休，感受勃发的生机，这样的世界真美好。"
},
	[4114]={ lines="感觉外面的温度和在部落时的温度差异很大，难道……是因为和链尉官在一起吗？", voice="hero_4508_cv_14.prefab", voice1="hero_4508_cv_14.prefab", lines1="感觉外面的温度和在部落时的温度差异很大，难道……是因为和链尉官在一起吗？"
},
	[4115]={ lines="感觉我们的距离稍微近了些……我指的并不是身体间的距离，而是内心……", voice="hero_4508_cv_15.prefab", voice1="hero_4508_cv_15.prefab", lines1="感觉我们的距离稍微近了些……我指的并不是身体间的距离，而是内心……"
},
	[4116]={ lines="链尉官，你知道吗，我头上的花是春天的象征呢！如果看到它盛开了，就说明春天马上要来啦。", voice="hero_4508_cv_16.prefab", voice1="hero_4508_cv_16.prefab", lines1="链尉官，你知道吗，我头上的花是春天的象征呢！如果看到它盛开了，就说明春天马上要来啦。"
},
	[4117]={ lines="星火的图样和装饰漂亮又特别，据说还有很多特别的寓意在，一点都不比我们部落的差呢！", voice="hero_4508_cv_17.prefab", voice1="hero_4508_cv_17.prefab", lines1="星火的图样和装饰漂亮又特别，据说还有很多特别的寓意在，一点都不比我们部落的差呢！"
},
	[4118]={ lines="我这身装扮会让链尉官感到不习惯吗？嗯？你说很好看...那...谢谢...", voice="hero_4508_cv_18.prefab", voice1="hero_4508_cv_18.prefab", lines1="我这身装扮会让链尉官感到不习惯吗？嗯？你说很好看...那...谢谢..."
},
	[4201]={ lines="维拉提亚代理骑士长蒂雅，希望能与阁下合作愉快。", voice="hero_4509_cv_01.prefab", voice1="hero_4509_cv_01.prefab", lines1="维拉提亚代理骑士长蒂雅，希望能与阁下合作愉快。"
},
	[4202]={ lines="新的任务吗？请不要让我对阁下的指挥能力感到失望。", voice="hero_4509_cv_02.prefab", voice1="hero_4509_cv_02.prefab", lines1="新的任务吗？请不要让我对阁下的指挥能力感到失望。"
},
	[4203]={ lines="看见流星了吗？", voice="hero_4509_cv_03.prefab", voice1="hero_4509_cv_03.prefab", lines1="看见流星了吗？"
},
	[4204]={ lines="窥伺群星可是很危险的", voice="hero_4509_cv_04.prefab", voice1="hero_4509_cv_04.prefab", lines1="窥伺群星可是很危险的"
},
	[4205]={ lines="准备好感受星空的神秘了吗？", voice="hero_4509_cv_05.prefab", voice1="hero_4509_cv_05.prefab", lines1="准备好感受星空的神秘了吗？"
},
	[4206]={ lines="嗯……只是这种程度的战斗吗？", voice="hero_4509_cv_06.prefab", voice1="hero_4509_cv_06.prefab", lines1="嗯……只是这种程度的战斗吗？"
},
	[4207]={ lines="日安，阁下。", voice="hero_4509_cv_07.prefab", voice1="hero_4509_cv_07.prefab", lines1="日安，阁下。"
},
	[4208]={ lines="维拉提亚真正的星空吗？要是能看到这片虚假天幕外的真实也不错呢。", voice="hero_4509_cv_08.prefab", voice1="hero_4509_cv_08.prefab", lines1="维拉提亚真正的星空吗？要是能看到这片虚假天幕外的真实也不错呢。"
},
	[4209]={ lines="嗯……错别字？这么珍贵的古籍手抄本上面竟然有错别字？……啊，署名怎么是我？", voice="hero_4509_cv_09.prefab", voice1="hero_4509_cv_09.prefab", lines1="嗯……错别字？这么珍贵的古籍手抄本上面竟然有错别字？……啊，署名怎么是我？"
},
	[4210]={ lines="日常汇报放在右边，工作审批放在左边……我之后会看的——嗯？怎么这么多？", voice="hero_4509_cv_10.prefab", voice1="hero_4509_cv_10.prefab", lines1="日常汇报放在右边，工作审批放在左边……我之后会看的——嗯？怎么这么多？"
},
	[4211]={ lines="请严格按照维拉提亚贵族礼仪标准与骑士团交流，询问私事是严令禁止的行为。", voice="hero_4509_cv_11.prefab", voice1="hero_4509_cv_11.prefab", lines1="请严格按照维拉提亚贵族礼仪标准与骑士团交流，询问私事是严令禁止的行为。"
},
	[4212]={ lines="骑士团也不是一直都很忙，偶尔没有工作的时候我会去商店街逛逛……你说那个偶尔出现的白发占卜巫女？那是什么？我什么都不知道哦。", voice="hero_4509_cv_12.prefab", voice1="hero_4509_cv_12.prefab", lines1="骑士团也不是一直都很忙，偶尔没有工作的时候我会去商店街逛逛……你说那个偶尔出现的白发占卜巫女？那是什么？我什么都不知道哦。"
},
	[4213]={ lines="我的书房吗？你就这么好奇那里？没什么特别的，只是一些古旧的东西堆在那里，还有一些我做的笔记和炼金材料，如果你是想要查看维拉提亚的古籍，我倒是可以给你开个借书的后门。", voice="hero_4509_cv_13.prefab", voice1="hero_4509_cv_13.prefab", lines1="我的书房吗？你就这么好奇那里？没什么特别的，只是一些古旧的东西堆在那里，还有一些我做的笔记和炼金材料，如果你是想要查看维拉提亚的古籍，我倒是可以给你开个借书的后门。"
},
	[4214]={ lines="维拉提亚人坚信星空指引着命途的方向，在真实的星空下不存在任何秘密，你想知道的一切星星都会告诉你。如若不介意的话，等到最美的星空出现时，你可以来维拉提亚找我，我会给你留最好的观星位置。", voice="hero_4509_cv_14.prefab", voice1="hero_4509_cv_14.prefab", lines1="维拉提亚人坚信星空指引着命途的方向，在真实的星空下不存在任何秘密，你想知道的一切星星都会告诉你。如若不介意的话，等到最美的星空出现时，你可以来维拉提亚找我，我会给你留最好的观星位置。"
},
	[4215]={ lines="偶尔我也想过，如果我不是出生在阿斯特利亚家的话，现在会过着什么样的生活……或许是在维拉提亚最高的山上安家，成为一名神秘的观星师吧，只有对星空的爱这一点不会改变——当然，这其中还有您。", voice="hero_4509_cv_15.prefab", voice1="hero_4509_cv_15.prefab", lines1="偶尔我也想过，如果我不是出生在阿斯特利亚家的话，现在会过着什么样的生活……或许是在维拉提亚最高的山上安家，成为一名神秘的观星师吧，只有对星空的爱这一点不会改变——当然，这其中还有您。"
},
	[4216]={ lines="今夜月影朦胧，是个观星的好时候。", voice="", voice1="hero_4509_cv_16.prefab", lines1="阁下所说的观星……是要从这里开始么……"
},
	[4217]={ lines="试试新的玩法？…….好啊，阁下再靠近我些，我悄悄说给你听。", voice="", voice1="hero_4509_cv_17.prefab", lines1="试试新的玩法？……哈嗯？！我……我还不太习惯……阁下，请温柔一些……"
},
	[4218]={ lines="阁下似乎很喜欢这儿的水温呢，我也喜欢，我们一起去泡一泡怎么样？", voice="", voice1="hero_4509_cv_18.prefab", lines1="阁下充沛的精力，我想要品尝更多呢……唔唔唔？唔嗯！……噗哈……哈……"
},
	[4301]={ lines="终于见到你了，和我的命运交汇之人……来和祂也打个招呼吧，祂也很喜欢你呢，呵呵。", voice="hero_4510_cv_01.prefab", voice1="hero_4510_cv_01.prefab", lines1="终于见到你了，和我的命运交汇之人……来和祂也打个招呼吧，祂也很喜欢你呢，呵呵。"
},
	[4302]={ lines="麻烦的事情就交给祂吧，我可不擅长打架呢。", voice="hero_4510_cv_02.prefab", voice1="hero_4510_cv_02.prefab", lines1="麻烦的事情就交给祂吧，我可不擅长打架呢。"
},
	[4303]={ lines="去吧，给它们一点教训瞧瞧~", voice="hero_4510_cv_03.prefab", voice1="hero_4510_cv_03.prefab", lines1="去吧，给它们一点教训瞧瞧~"
},
	[4304]={ lines="一点小礼物，不能拒绝哦~", voice="hero_4510_cv_04.prefab", voice1="hero_4510_cv_04.prefab", lines1="一点小礼物，不能拒绝哦~"
},
	[4305]={ lines="把它惹生气了，后果我可不负责哦~", voice="hero_4510_cv_05.prefab", voice1="hero_4510_cv_05.prefab", lines1="把它惹生气了，后果我可不负责哦~"
},
	[4306]={ lines="来，跟它们打声再见的招呼吧~", voice="hero_4510_cv_06.prefab", voice1="hero_4510_cv_06.prefab", lines1="来，跟它们打声再见的招呼吧~"
},
	[4307]={ lines="……醒了吗？睡得这么香甜，做了个什么样的美梦呢？", voice="hero_4510_cv_07.prefab", voice1="hero_4510_cv_07.prefab", lines1="……醒了吗？睡得这么香甜，做了个什么样的美梦呢？"
},
	[4308]={ lines="塞入棉花，然后把嘴巴缝好……一个新的“玩偶”诞生了。呵呵，可爱吗？送给你。", voice="hero_4510_cv_08.prefab", voice1="hero_4510_cv_08.prefab", lines1="塞入棉花，然后把嘴巴缝好……一个新的“玩偶”诞生了。呵呵，可爱吗？送给你。"
},
	[4309]={ lines="祂没有名字，只是一个属于我的玩偶，没错，只是一个……玩偶。", voice="hero_4510_cv_09.prefab", voice1="hero_4510_cv_09.prefab", lines1="祂没有名字，只是一个属于我的玩偶，没错，只是一个……玩偶。"
},
	[4310]={ lines="（哈欠）……有点困倦了呢，要一起安睡吗？链尉官？", voice="hero_4510_cv_10.prefab", voice1="hero_4510_cv_10.prefab", lines1="（哈欠）……有点困倦了呢，要一起安睡吗？链尉官？"
},
	[4311]={ lines="梦境映射了命运的可能性，却也因此不会被人所记住……你记得曾经做了什么梦吗？链尉官？", voice="hero_4510_cv_11.prefab", voice1="hero_4510_cv_11.prefab", lines1="梦境映射了命运的可能性，却也因此不会被人所记住……你记得曾经做了什么梦吗？链尉官？"
},
	[4312]={ lines="那座如同牢笼般的房间，只有祂一直在陪伴着我，玩偶只是祂的表象，而看清祂的真实之人……除了我以外，只有你，链尉官。", voice="hero_4510_cv_12.prefab", voice1="hero_4510_cv_12.prefab", lines1="那座如同牢笼般的房间，只有祂一直在陪伴着我，玩偶只是祂的表象，而看清祂的真实之人……除了我以外，只有你，链尉官。"
},
	[4313]={ lines="想知道我更多的秘密么……？当然可以，对于你，我不会有什么保留，不过……得一起做梦才行呢。", voice="hero_4510_cv_13.prefab", voice1="hero_4510_cv_13.prefab", lines1="想知道我更多的秘密么……？当然可以，对于你，我不会有什么保留，不过……得一起做梦才行呢。"
},
	[4314]={ lines="偶尔，我也会怀念自己还未曾变得这副模样的时候，那时候的我……刚好能触碰到你的下巴呢，呵呵。", voice="hero_4510_cv_14.prefab", voice1="hero_4510_cv_14.prefab", lines1="偶尔，我也会怀念自己还未曾变得这副模样的时候，那时候的我……刚好能触碰到你的下巴呢，呵呵。"
},
	[4315]={ lines="与我而言，那段过去，如同梦境一般朦胧且悲伤，但现在……我想要触碰你，让我知道自己正在做一个真实、幸福的梦，所以……我想要你抱住我，可以……吗？", voice="hero_4510_cv_15.prefab", voice1="hero_4510_cv_15.prefab", lines1="与我而言，那段过去，如同梦境一般朦胧且悲伤，但现在……我想要触碰你，让我知道自己正在做一个真实、幸福的梦，所以……我想要你抱住我，可以……吗？"
},
	[4401]={ lines="你就是大名鼎鼎的链尉官吧？我叫艾尔西妲，是一名义体商人，要是缺胳膊少腿了可以来找我，给你个友情价~", voice="hero_4511_cv_01.prefab", voice1="hero_4511_cv_01.prefab", lines1="你就是大名鼎鼎的链尉官吧？我叫艾尔西妲，是一名义体商人，要是缺胳膊少腿了可以来找我，给你个友情价~"
},
	[4402]={ lines="终于有机会活动活动筋骨了！", voice="hero_4511_cv_02.prefab", voice1="hero_4511_cv_02.prefab", lines1="终于有机会活动活动筋骨了！"
},
	[4403]={ lines="到我了！", voice="hero_4511_cv_03.prefab", voice1="hero_4511_cv_03.prefab", lines1="到我了！"
},
	[4404]={ lines="站在我的身边！", voice="hero_4511_cv_04.prefab", voice1="hero_4511_cv_04.prefab", lines1="站在我的身边！"
},
	[4405]={ lines="久等了！全功率阵列——展开！", voice="hero_4511_cv_05.prefab", voice1="hero_4511_cv_05.prefab", lines1="久等了！全功率阵列——展开！"
},
	[4406]={ lines="轻轻松松……话说，我的义体损耗是不是能找你们买单？", voice="hero_4511_cv_06.prefab", voice1="hero_4511_cv_06.prefab", lines1="轻轻松松……话说，我的义体损耗是不是能找你们买单？"
},
	[4407]={ lines="哟，你来了，今天想要做些什么刺激事儿？", voice="hero_4511_cv_07.prefab", voice1="hero_4511_cv_07.prefab", lines1="哟，你来了，今天想要做些什么刺激事儿？"
},
	[4408]={ lines="嗯……是部件有些松动了么？要不现在卸下来修一修好了……", voice="hero_4511_cv_08.prefab", voice1="hero_4511_cv_08.prefab", lines1="嗯……是部件有些松动了么？要不现在卸下来修一修好了……"
},
	[4409]={ lines="唉，你这地方太安静，安静地有些无聊了，不适合我这性子。", voice="hero_4511_cv_09.prefab", voice1="hero_4511_cv_09.prefab", lines1="唉，你这地方太安静，安静地有些无聊了，不适合我这性子。"
},
	[4410]={ lines="别看我的武器是一面盾，我这个人还挺能打的——不信？嚯，要比划比划吗？", voice="hero_4511_cv_10.prefab", voice1="hero_4511_cv_10.prefab", lines1="别看我的武器是一面盾，我这个人还挺能打的——不信？嚯，要比划比划吗？"
},
	[4411]={ lines="听说你们这有一位擅长做外骨骼的医生，能不能介绍给我认识认识？别紧张，我只是想要多结交一位可能存在的商业伙伴，不是挖墙脚~", voice="hero_4511_cv_11.prefab", voice1="hero_4511_cv_11.prefab", lines1="听说你们这有一位擅长做外骨骼的医生，能不能介绍给我认识认识？别紧张，我只是想要多结交一位可能存在的商业伙伴，不是挖墙脚~"
},
	[4412]={ lines="虽然我是一名义体商人，但我其实还有个身份，简单来说呢就是我家里有矿——你不信？改天来福登城，让你见见世面~", voice="hero_4511_cv_12.prefab", voice1="hero_4511_cv_12.prefab", lines1="虽然我是一名义体商人，但我其实还有个身份，简单来说呢就是我家里有矿——你不信？改天来福登城，让你见见世面~"
},
	[4413]={ lines="以前需要我来做决断的事情并不多，但现在背负起许多人的期待后，我才知道这个世界到底有多宽广——也许在这层认知上，咱俩说不定很有共鸣呢，呵呵。", voice="hero_4511_cv_13.prefab", voice1="hero_4511_cv_13.prefab", lines1="以前需要我来做决断的事情并不多，但现在背负起许多人的期待后，我才知道这个世界到底有多宽广——也许在这层认知上，咱俩说不定很有共鸣呢，呵呵。"
},
	[4414]={ lines="虽然身体的三分之一都被机械替代，但我的心脏还在，和你的心一样热忱且跳动着……看你的眼神，是想要感受一下吗？胆子挺大的嘛~", voice="hero_4511_cv_14.prefab", voice1="hero_4511_cv_14.prefab", lines1="虽然身体的三分之一都被机械替代，但我的心脏还在，和你的心一样热忱且跳动着……看你的眼神，是想要感受一下吗？胆子挺大的嘛~"
},
	[4415]={ lines="有的时候，我也会想干脆抛掉所有的念想和目标，就这样自由下去——但是在你身边待得久了，却让我觉得又可以再努力一下……你问努力做什么？这是秘密~", voice="hero_4511_cv_15.prefab", voice1="hero_4511_cv_15.prefab", lines1="有的时候，我也会想干脆抛掉所有的念想和目标，就这样自由下去——但是在你身边待得久了，却让我觉得又可以再努力一下……你问努力做什么？这是秘密~"
},
	[4416]={ lines="不要惊讶，我只是给自己的身体换了更适合节日的配件——你很喜欢？那就来摸摸看？呵呵。", voice="hero_4511_cv_16.prefab", voice1="hero_4511_cv_16.prefab", lines1="不要惊讶，我只是给自己的身体换了更适合节日的配件——你很喜欢？那就来摸摸看？呵呵。"
},
	[4417]={ lines="珍贵的瓷器往往被用作收藏，因为它过于脆弱……你问我为什么要用它来制造义体？这个问题嘛……或许这也是寻求刺激的一部分吧。", voice="hero_4511_cv_17.prefab", voice1="hero_4511_cv_17.prefab", lines1="珍贵的瓷器往往被用作收藏，因为它过于脆弱……你问我为什么要用它来制造义体？这个问题嘛……或许这也是寻求刺激的一部分吧。"
},
	[4418]={ lines="我对那个传说中的星火可是越来越感兴趣了呢，你有渠道介绍一点那边的生意吗？当然，我会给出让你满意的报酬。", voice="hero_4511_cv_18.prefab", voice1="hero_4511_cv_18.prefab", lines1="我对那个传说中的星火可是越来越感兴趣了呢，你有渠道介绍一点那边的生意吗？当然，我会给出让你满意的报酬。"
},
	[4501]={ lines="你好啊，我是伊芙特，暂时加入你的队伍了。不过先说好，没什么很重要的事情可不要麻烦我。", voice="hero_3504_cv_01.prefab", voice1="hero_3504_cv_01.prefab", lines1="你好啊，我是伊芙特，暂时加入你的队伍了。不过先说好，没什么很重要的事情可不要麻烦我。"
},
	[4502]={ lines="又有任务了？我可不可以拒绝？……不可以？好吧。", voice="hero_3504_cv_02.prefab", voice1="hero_3504_cv_02.prefab", lines1="又有任务了？我可不可以拒绝？……不可以？好吧。"
},
	[4503]={ lines="吃我一炮！", voice="hero_3504_cv_03.prefab", voice1="hero_3504_cv_03.prefab", lines1="吃我一炮！"
},
	[4504]={ lines="给你们加个BUFF，好让我轻松些。", voice="hero_3504_cv_04.prefab", voice1="hero_3504_cv_04.prefab", lines1="给你们加个BUFF，好让我轻松些。"
},
	[4505]={ lines="看这招——天降正义！", voice="hero_3504_cv_05.prefab", voice1="hero_3504_cv_05.prefab", lines1="看这招——天降正义！"
},
	[4506]={ lines="结束了结束了，该回去打卡下班咯。", voice="hero_3504_cv_06.prefab", voice1="hero_3504_cv_06.prefab", lines1="结束了结束了，该回去打卡下班咯。"
},
	[4507]={ lines="你的心情不错嘛，一定是碰上什么高兴的事情了，快说来听听，我可以和你交换！", voice="hero_3504_cv_07.prefab", voice1="hero_3504_cv_07.prefab", lines1="你的心情不错嘛，一定是碰上什么高兴的事情了，快说来听听，我可以和你交换！"
},
	[4508]={ lines="赛洛维第三区生物信息检测的数据是......嗯？这是什么？！——呼，还好没什么问题。", voice="hero_3504_cv_08.prefab", voice1="hero_3504_cv_08.prefab", lines1="赛洛维第三区生物信息检测的数据是......嗯？这是什么？！——呼，还好没什么问题。"
},
	[4509]={ lines="（听歌中……）嗯，这曲子不错，收藏一下。", voice="hero_3504_cv_09.prefab", voice1="hero_3504_cv_09.prefab", lines1="（听歌中……）嗯，这曲子不错，收藏一下。"
},
	[4510]={ lines="别沉迷工作了，站起来跟我一起活动活动，然后摸鱼摸个爽怎么样？", voice="hero_3504_cv_10.prefab", voice1="hero_3504_cv_10.prefab", lines1="别沉迷工作了，站起来跟我一起活动活动，然后摸鱼摸个爽怎么样？"
},
	[4511]={ lines="这么好的天气却要出来巡查，打工人真是艰难……你可不要拖后腿，我才不想加班。", voice="hero_3504_cv_11.prefab", voice1="hero_3504_cv_11.prefab", lines1="这么好的天气却要出来巡查，打工人真是艰难……你可不要拖后腿，我才不想加班。"
},
	[4512]={ lines="你问我为什么不换个在城市里的工作？一开始我对巡林员这个职业确实没什么热情，但时间长了也就习惯了，在森林里面放松偷会闲也挺不错的……啊，这点你可不能说出去！", voice="hero_3504_cv_12.prefab", voice1="hero_3504_cv_12.prefab", lines1="你问我为什么不换个在城市里的工作？一开始我对巡林员这个职业确实没什么热情，但时间长了也就习惯了，在森林里面放松偷会闲也挺不错的……啊，这点你可不能说出去！"
},
	[4513]={ lines="唉，这个月的迟到次数又超过最高记录了……总觉得我的闹钟没有响过似的。链尉官，你能不能试试明天叫我起床？哼哼，我要证明这一定不是我起不来的问题！", voice="hero_3504_cv_13.prefab", voice1="hero_3504_cv_13.prefab", lines1="唉，这个月的迟到次数又超过最高记录了……总觉得我的闹钟没有响过似的。链尉官，你能不能试试明天叫我起床？哼哼，我要证明这一定不是我起不来的问题！"
},
	[4514]={ lines="听我说！我申请调休的审批通过了，而且还是连着休息日一起呢！要不要去城里大玩特玩一番？嘿嘿，我有几个很推荐的地方，保证你一定没去过！", voice="hero_3504_cv_14.prefab", voice1="hero_3504_cv_14.prefab", lines1="听我说！我申请调休的审批通过了，而且还是连着休息日一起呢！要不要去城里大玩特玩一番？嘿嘿，我有几个很推荐的地方，保证你一定没去过！"
},
	[4515]={ lines="最近的工作好像没那么无聊了，至于原因......可能是能听到你说各种有意思的事情吧，所以为了让我提高工作效率，记得多和我联络啊！实在不行，你自己过来跟我讲怎么样？", voice="hero_3504_cv_15.prefab", voice1="hero_3504_cv_15.prefab", lines1="最近的工作好像没那么无聊了，至于原因......可能是能听到你说各种有意思的事情吧，所以为了让我提高工作效率，记得多和我联络啊！实在不行，你自己过来跟我讲怎么样？"
},
	[4601]={ lines="承蒙抬爱，以后就和您一起作战了。", voice="hero_4512_cv_01.prefab", voice1="hero_4512_cv_01.prefab", lines1="承蒙抬爱，以后就和您一起作战了。"
},
	[4602]={ lines="要去验证一下修行的成果吗....也好，一起行动吧。", voice="hero_4512_cv_02.prefab", voice1="hero_4512_cv_02.prefab", lines1="要去验证一下修行的成果吗....也好，一起行动吧。"
},
	[4603]={ lines="霜雪加护于我等。", voice="hero_4512_cv_03.prefab", voice1="hero_4512_cv_03.prefab", lines1="霜雪加护于我等。"
},
	[4604]={ lines="于此，妖邪退散。", voice="hero_4512_cv_04.prefab", voice1="hero_4512_cv_04.prefab", lines1="于此，妖邪退散。"
},
	[4605]={ lines="朔风既起，我便凭此落梅助您一臂之力。", voice="hero_4512_cv_05.prefab", voice1="hero_4512_cv_05.prefab", lines1="朔风既起，我便凭此落梅助您一臂之力。"
},
	[4606]={ lines="看来近日修行并无松懈。", voice="hero_4512_cv_06.prefab", voice1="hero_4512_cv_06.prefab", lines1="看来近日修行并无松懈。"
},
	[4607]={ lines="您近况似乎不错，真好奇您最近做了些什么事呢！", voice="hero_4512_cv_07.prefab", voice1="hero_4512_cv_07.prefab", lines1="您近况似乎不错，真好奇您最近做了些什么事呢！"
},
	[4608]={ lines="比起用剑，还是这把扇子与我更相称。", voice="hero_4512_cv_08.prefab", voice1="hero_4512_cv_08.prefab", lines1="比起用剑，还是这把扇子与我更相称。"
},
	[4609]={ lines="工作累了的话，就来我这里喝杯茶吧，它能让您放松一下", voice="hero_4512_cv_09.prefab", voice1="hero_4512_cv_09.prefab", lines1="工作累了的话，就来我这里喝杯茶吧，它能让您放松一下"
},
	[4610]={ lines="这场远行只是我历练的一部分，我最终还是要回去师门的，到那时我想邀请您去做客。", voice="hero_4512_cv_10.prefab", voice1="hero_4512_cv_10.prefab", lines1="这场远行只是我历练的一部分，我最终还是要回去师门的，到那时我想邀请您去做客。"
},
	[4611]={ lines="我仔细查看了一些修格尔的战斗数据和资料，总还有些疑问....链尉官作战经验丰富，您可以为我解答疑惑吗？", voice="hero_4512_cv_11.prefab", voice1="hero_4512_cv_11.prefab", lines1="我仔细查看了一些修格尔的战斗数据和资料，总还有些疑问....链尉官作战经验丰富，您可以为我解答疑惑吗？"
},
	[4612]={ lines="感觉越和您接触，我越能感受到您内里的有趣......难怪小师妹总说您是个很特别的人。", voice="hero_4512_cv_12.prefab", voice1="hero_4512_cv_12.prefab", lines1="感觉越和您接触，我越能感受到您内里的有趣......难怪小师妹总说您是个很特别的人。"
},
	[4613]={ lines="您下次休假是什么时候？最近从家乡寄来一些点心，想和您一起分享...当然，这次没有公事，只是朋友间的小聚。", voice="hero_4512_cv_13.prefab", voice1="hero_4512_cv_13.prefab", lines1="您下次休假是什么时候？最近从家乡寄来一些点心，想和您一起分享...当然，这次没有公事，只是朋友间的小聚。"
},
	[4614]={ lines="我想为师门的大家寄一点礼物回去，您有什么推荐吗？另外想请您与我拍一张合照，我要把您介绍给他们认识。", voice="hero_4512_cv_14.prefab", voice1="hero_4512_cv_14.prefab", lines1="我想为师门的大家寄一点礼物回去，您有什么推荐吗？另外想请您与我拍一张合照，我要把您介绍给他们认识。"
},
	[4615]={ lines="与您呆在一起的时间总是过得那么快，好像还没开始就结束了...我一直觉得顺其自然就能得到最好的结果，但现在我必须要做点什么...我的意思是，我可以随时去见你吗？", voice="hero_4512_cv_15.prefab", voice1="hero_4512_cv_15.prefab", lines1="与您呆在一起的时间总是过得那么快，好像还没开始就结束了...我一直觉得顺其自然就能得到最好的结果，但现在我必须要做点什么...我的意思是，我可以随时去见你吗？"
},
	[4616]={ lines="一年将近夜，万里未归人，身在他乡，难免会思念故友亲朋……幸好还有您在我身边。", voice="hero_4512_cv_16.prefab", voice1="hero_4512_cv_16.prefab", lines1="一年将近夜，万里未归人，身在他乡，难免会思念故友亲朋……幸好还有您在我身边。"
},
	[4617]={ lines="好奇我的武术？虽说我更精于仙法，但既然是您的要求，我便大胆献丑，还请您不要嫌弃。", voice="hero_4512_cv_17.prefab", voice1="hero_4512_cv_17.prefab", lines1="好奇我的武术？虽说我更精于仙法，但既然是您的要求，我便大胆献丑，还请您不要嫌弃。"
},
	[4618]={ lines="值此佳节，烹一壶好茶，约一位知己，寻一处闲暇地，谈三两桩趣事——您说，世上还有人会比你我更舒心么？", voice="hero_4512_cv_18.prefab", voice1="hero_4512_cv_18.prefab", lines1="值此佳节，烹一壶好茶，约一位知己，寻一处闲暇地，谈三两桩趣事——您说，世上还有人会比你我更舒心么？"
},
	[4619]={ lines="链尉官，您也来此处歇息一会吗？这里的水潭清冽宜人，适合消解酒气和疲惫呢……您要是不介意湿了衣服，那便坐我旁边，一起享受此刻吧。", voice="hero_4512_cv_19.prefab", voice1="hero_4512_cv_19.prefab", lines1="链尉官，您也来此处歇息一会吗？这里的水潭清冽宜人，适合消解酒气和疲惫呢……您要是不介意湿了衣服，那便坐我旁边，一起享受此刻吧。"
},
	[4620]={ lines="您不要闹我了，我怕痒……不是您？原来是池潭中的鱼儿……它似乎在本能地寻找热源，嗯……是我的身子热的厉害吗……", voice="hero_4512_cv_20.prefab", voice1="hero_4512_cv_20.prefab", lines1="您不要闹我了，我怕痒……不是您？原来是池潭中的鱼儿……它似乎在本能地寻找热源，嗯……是我的身子热的厉害吗……"
},
	[4621]={ lines="小师妹知道我应您的邀请前来赴宴后，神神秘秘地给我送来一套新的衣裳，据说是您让工匠以星火的文化来设计的……您呀，其实直接跟我说就好，既然是您的好意，我不会拒绝。", voice="hero_4512_cv_21.prefab", voice1="hero_4512_cv_21.prefab", lines1="小师妹知道我应您的邀请前来赴宴后，神神秘秘地给我送来一套新的衣裳，据说是您让工匠以星火的文化来设计的……您呀，其实直接跟我说就好，既然是您的好意，我不会拒绝。"
},
	[4701]={ lines="尤加利，这是我的名字，我是活在虚蚀域里的猎人，也是你从此要仰望的存在，给我记住了。", voice="hero_4513_cv_01.prefab", voice1="hero_4513_cv_01.prefab", lines1="尤加利，这是我的名字，我是活在虚蚀域里的猎人，也是你从此要仰望的存在，给我记住了。"
},
	[4702]={ lines="从现在起，我将是这场战斗的主角。", voice="hero_4513_cv_02.prefab", voice1="hero_4513_cv_02.prefab", lines1="从现在起，我将是这场战斗的主角。"
},
	[4703]={ lines="哼，破绽百出！", voice="hero_4513_cv_03.prefab", voice1="hero_4513_cv_03.prefab", lines1="哼，破绽百出！"
},
	[4704]={ lines="呵，你要往哪里逃？", voice="hero_4513_cv_04.prefab", voice1="hero_4513_cv_04.prefab", lines1="呵，你要往哪里逃？"
},
	[4705]={ lines="这一刀，将是你的终结！", voice="hero_4513_cv_05.prefab", voice1="hero_4513_cv_05.prefab", lines1="这一刀，将是你的终结！"
},
	[4706]={ lines="呵，一场完美的胜利也只是我的陪衬。", voice="hero_4513_cv_06.prefab", voice1="hero_4513_cv_06.prefab", lines1="呵，一场完美的胜利也只是我的陪衬。"
},
	[4707]={ lines="是你啊，看到我后不想说点什么吗？来吧，我会认真倾听你的赞美。", voice="hero_4513_cv_07.prefab", voice1="hero_4513_cv_07.prefab", lines1="是你啊，看到我后不想说点什么吗？来吧，我会认真倾听你的赞美。"
},
	[4708]={ lines="别把我和那些提不起兴趣的家伙放在一起，明白吗？我天生就和他们不一样。", voice="hero_4513_cv_08.prefab", voice1="hero_4513_cv_08.prefab", lines1="别把我和那些提不起兴趣的家伙放在一起，明白吗？我天生就和他们不一样。"
},
	[4709]={ lines="人类和修格尔都是无聊的生物，但你好像不是，你值得让我的视线多停留一会。", voice="hero_4513_cv_09.prefab", voice1="hero_4513_cv_09.prefab", lines1="人类和修格尔都是无聊的生物，但你好像不是，你值得让我的视线多停留一会。"
},
	[4710]={ lines="想要我听你的指挥？你要搞清楚，是你需要我，不是我需要你……明白吗？", voice="hero_4513_cv_10.prefab", voice1="hero_4513_cv_10.prefab", lines1="想要我听你的指挥？你要搞清楚，是你需要我，不是我需要你……明白吗？"
},
	[4711]={ lines="这个世界是一个巨大的舞台，有的人扮演游行尘土的蝼蚁，有的人则是翱翔天空的雄鹰……你问我是什么角色？呵呵，我不扮演任何事物，我要成为……制定规则者。", voice="hero_4513_cv_11.prefab", voice1="hero_4513_cv_11.prefab", lines1="这个世界是一个巨大的舞台，有的人扮演游行尘土的蝼蚁，有的人则是翱翔天空的雄鹰……你问我是什么角色？呵呵，我不扮演任何事物，我要成为……制定规则者。"
},
	[4712]={ lines="身为主角的我负责战斗，在这期间你就完成做为一个听众的责任，嗯，就这么决定了。", voice="hero_4513_cv_12.prefab", voice1="hero_4513_cv_12.prefab", lines1="身为主角的我负责战斗，在这期间你就完成做为一个听众的责任，嗯，就这么决定了。"
},
	[4713]={ lines="链尉官，我需要一个能记录我的伟大功绩之人，并将赐予你这个机会——你不会拒绝我的，对吗？", voice="hero_4513_cv_13.prefab", voice1="hero_4513_cv_13.prefab", lines1="链尉官，我需要一个能记录我的伟大功绩之人，并将赐予你这个机会——你不会拒绝我的，对吗？"
},
	[4714]={ lines="身为我的记录者，你要以自己的身份感到自豪，我不允许时刻都在我身旁的你有哪怕一点不如别人的地方。", voice="hero_4513_cv_14.prefab", voice1="hero_4513_cv_14.prefab", lines1="身为我的记录者，你要以自己的身份感到自豪，我不允许时刻都在我身旁的你有哪怕一点不如别人的地方。"
},
	[4715]={ lines="我尤加利，居然会输给你这样的家伙……！你到底是何方神圣？！如果就这样被你压制住，我会变得……不，不行！绝对不行！你，你要做什么？！呜……！", voice="hero_4513_cv_15.prefab", voice1="hero_4513_cv_15.prefab", lines1="我尤加利，居然会输给你这样的家伙……！你到底是何方神圣？！如果就这样被你压制住，我会变得……不，不行！绝对不行！你，你要做什么？！呜……！"
},
	[4716]={ lines="这个房间只有我有使用权，所以能坐在我的身边的你，应该为这份荣幸感到骄傲，链尉官。", voice="hero_4513_cv_16.prefab", voice1="hero_4513_cv_16.prefab", lines1="这个房间只有我有使用权，所以能坐在我的身边的你，应该为这份荣幸感到骄傲，链尉官。"
},
	[4717]={ lines="哎呀，我的袜子好像湿了呢……换一双？不行，我要你来给我擦干净……这是命令，你不能回绝。", voice="hero_4513_cv_17.prefab", voice1="hero_4513_cv_17.prefab", lines1="哎呀，我的袜子好像湿了呢……换一双？不行，我要你来给我擦干净……这是命令，你不能回绝。"
},
	[4718]={ lines="为了换上这身衣服，你知道要占用我多少宝贵的时间吗？所以，你要用你的时间来补偿我才行……我会好好享受的，呵呵。", voice="hero_4513_cv_18.prefab", voice1="hero_4513_cv_18.prefab", lines1="为了换上这身衣服，你知道要占用我多少宝贵的时间吗？所以，你要用你的时间来补偿我才行……我会好好享受的，呵呵。"
},
	[4801]={ lines="嗨你好啊，我是危峭，当然，如果你愿意的话，也可以叫我的名字，波哈露……呃，念起来有点奇怪吗……哈哈，很多人都这么说。", voice="hero_4514_cv_01.prefab", voice1="hero_4514_cv_01.prefab", lines1="嗨你好啊，我是危峭，当然，如果你愿意的话，也可以叫我的名字，波哈露……呃，念起来有点奇怪吗……哈哈，很多人都这么说。"
},
	[4802]={ lines="嘿，是要去战斗吗？我可是干劲满满呢！", voice="hero_4514_cv_02.prefab", voice1="hero_4514_cv_02.prefab", lines1="嘿，是要去战斗吗？我可是干劲满满呢！"
},
	[4803]={ lines="试试这个——嘿哈——", voice="hero_4514_cv_03.prefab", voice1="hero_4514_cv_03.prefab", lines1="试试这个——嘿哈——"
},
	[4804]={ lines="哼，看我这一招！", voice="hero_4514_cv_04.prefab", voice1="hero_4514_cv_04.prefab", lines1="哼，看我这一招！"
},
	[4805]={ lines="妄图对我的伙伴们出手？等着挨揍吧！", voice="hero_4514_cv_05.prefab", voice1="hero_4514_cv_05.prefab", lines1="妄图对我的伙伴们出手？等着挨揍吧！"
},
	[4806]={ lines="都是小意思，可以继续增加任务强度啊。", voice="hero_4514_cv_06.prefab", voice1="hero_4514_cv_06.prefab", lines1="都是小意思，可以继续增加任务强度啊。"
},
	[4807]={ lines="做什么去了？怎么才回来，要和你说的事情有点多，让我组织下语言。", voice="hero_4514_cv_07.prefab", voice1="hero_4514_cv_07.prefab", lines1="做什么去了？怎么才回来，要和你说的事情有点多，让我组织下语言。"
},
	[4808]={ lines="哎，在这边待太久感觉骨头都要生锈了，你听，都在嘎吱嘎吱响了……附近有攀岩馆之类的地方吗？有的话推荐一下，我请客。", voice="hero_4514_cv_08.prefab", voice1="hero_4514_cv_08.prefab", lines1="哎，在这边待太久感觉骨头都要生锈了，你听，都在嘎吱嘎吱响了……附近有攀岩馆之类的地方吗？有的话推荐一下，我请客。"
},
	[4809]={ lines="刚下载的这部电影有点刺激啊，开屏一个贴脸杀，的确有点吓到了……被你看到也是没办法的事情啦，要不要来和我一起看？说不定你也会喜欢的。", voice="hero_4514_cv_09.prefab", voice1="hero_4514_cv_09.prefab", lines1="刚下载的这部电影有点刺激啊，开屏一个贴脸杀，的确有点吓到了……被你看到也是没办法的事情啦，要不要来和我一起看？说不定你也会喜欢的。"
},
	[4810]={ lines="最近事情这么多全挤在一起了，很久没有去论坛灌水了……这样下去我的声望值也会降低的，得想个办法……喂链尉官来的正好，你有没有一些能放在怪谈论坛的事件分享？我会码掉你的身份的！", voice="hero_4514_cv_10.prefab", voice1="hero_4514_cv_10.prefab", lines1="最近事情这么多全挤在一起了，很久没有去论坛灌水了……这样下去我的声望值也会降低的，得想个办法……喂链尉官来的正好，你有没有一些能放在怪谈论坛的事件分享？我会码掉你的身份的！"
},
	[4811]={ lines="喂，我说，你见识那么广，有没有见过一种奇怪的东西，让我想想，虽然确实很想称呼它是生物，不过它应该不算是活的吧。", voice="hero_4514_cv_11.prefab", voice1="hero_4514_cv_11.prefab", lines1="喂，我说，你见识那么广，有没有见过一种奇怪的东西，让我想想，虽然确实很想称呼它是生物，不过它应该不算是活的吧。"
},
	[4812]={ lines="高空的冷风偶尔会让我有种顺利攀上山顶的感觉，这就是莱斯坦斯本舰的气氛吗？还真不赖呢，有机会我试试吹着风打游戏，说不定也是环绕式立体的体验。欸我这个想法是不是很有创意？", voice="hero_4514_cv_12.prefab", voice1="hero_4514_cv_12.prefab", lines1="高空的冷风偶尔会让我有种顺利攀上山顶的感觉，这就是莱斯坦斯本舰的气氛吗？还真不赖呢，有机会我试试吹着风打游戏，说不定也是环绕式立体的体验。欸我这个想法是不是很有创意？"
},
	[4813]={ lines="虽然我总是尽力避免深夜运动，但总会有工作太忙迫不得已的时候，那个时候就会忍不住胡思乱想，总觉得有什么东西就在旁边，说起来你有体验过深夜的健身房吗？下次一起怎么样？", voice="hero_4514_cv_13.prefab", voice1="hero_4514_cv_13.prefab", lines1="虽然我总是尽力避免深夜运动，但总会有工作太忙迫不得已的时候，那个时候就会忍不住胡思乱想，总觉得有什么东西就在旁边，说起来你有体验过深夜的健身房吗？下次一起怎么样？"
},
	[4814]={ lines="有空吗？也没什么大事啦，有部幻想灵异题材新作刚好在下次放假的时候发售，想找你陪我一起玩……呃，请你一定要抽出时间来拜托了！我不能没有你。", voice="hero_4514_cv_14.prefab", voice1="hero_4514_cv_14.prefab", lines1="有空吗？也没什么大事啦，有部幻想灵异题材新作刚好在下次放假的时候发售，想找你陪我一起玩……呃，请你一定要抽出时间来拜托了！我不能没有你。"
},
	[4815]={ lines="不知道有没有和你说过，我一直想做一些极限运动，欸可不是驱鬼，就是想和重要的人一起，用滑翔翼从泰诺星的最高峰飞下来，很大胆对吧？我认真做过规划了所以安全是不用担心的，要是你实在不愿意我也可以换一个。", voice="hero_4514_cv_15.prefab", voice1="hero_4514_cv_15.prefab", lines1="不知道有没有和你说过，我一直想做一些极限运动，欸可不是驱鬼，就是想和重要的人一起，用滑翔翼从泰诺星的最高峰飞下来，很大胆对吧？我认真做过规划了所以安全是不用担心的，要是你实在不愿意我也可以换一个。"
},
	[4816]={ lines="这座废弃的学校听说有鬼怪出没，看我先自拍一张作为纪念，嗯，好，完成，链尉官看这边！给你也来一张——咔擦！", voice="hero_4514_cv_16.prefab", voice1="hero_4514_cv_16.prefab", lines1="这座废弃的学校听说有鬼怪出没，看我先自拍一张作为纪念，嗯，好，完成，链尉官看这边！给你也来一张——咔擦！"
},
	[4817]={ lines="那个，链尉官，你有没有觉得冷，我觉得周围有东西……你离我再近点……呃，我只是怕那些东西先找上你……好吧我确实有点怕，贴着你比较有安全感。", voice="hero_4514_cv_17.prefab", voice1="hero_4514_cv_17.prefab", lines1="那个，链尉官，你有没有觉得冷，我觉得周围有东西……你离我再近点……呃，我只是怕那些东西先找上你……好吧我确实有点怕，贴着你比较有安全感。"
},
	[4818]={ lines="电影里的鬼怪不是都最喜欢找柔~弱~的~女学生吗？怎么这么久什么都没有，嗯……一定是被我吓到了！或者说因为有你在？什么？你说我看起来一点也不柔弱？难道我扮得不像吗？", voice="hero_4514_cv_18.prefab", voice1="hero_4514_cv_18.prefab", lines1="电影里的鬼怪不是都最喜欢找柔~弱~的~女学生吗？怎么这么久什么都没有，嗯……一定是被我吓到了！或者说因为有你在？什么？你说我看起来一点也不柔弱？难道我扮得不像吗？"
},
	[4901]={ lines="赏金猎人刺玫，为了完成你的委托而来，准备好足够的报酬吧，链尉官。", voice="hero_4515_cv_01.prefab", voice1="hero_4515_cv_01.prefab", lines1="赏金猎人刺玫，为了完成你的委托而来，准备好足够的报酬吧，链尉官。"
},
	[4902]={ lines="我从不让客户失望。", voice="hero_4515_cv_02.prefab", voice1="hero_4515_cv_02.prefab", lines1="我从不让客户失望。"
},
	[4903]={ lines="在这把枪下求饶吧。", voice="hero_4515_cv_03.prefab", voice1="hero_4515_cv_03.prefab", lines1="在这把枪下求饶吧。"
},
	[4904]={ lines="不好意思，我赶时间。", voice="hero_4515_cv_04.prefab", voice1="hero_4515_cv_04.prefab", lines1="不好意思，我赶时间。"
},
	[4905]={ lines="于万千玫瑰下的景色，和我一同欣赏吧。", voice="hero_4515_cv_05.prefab", voice1="hero_4515_cv_05.prefab", lines1="于万千玫瑰下的景色，和我一同欣赏吧。"
},
	[4906]={ lines="委托完成，请按时支付酬劳~", voice="hero_4515_cv_06.prefab", voice1="hero_4515_cv_06.prefab", lines1="委托完成，请按时支付酬劳~"
},
	[4907]={ lines="我们的委托现在就可以开始——前提是我要看到你的诚意。", voice="hero_4515_cv_07.prefab", voice1="hero_4515_cv_07.prefab", lines1="我们的委托现在就可以开始——前提是我要看到你的诚意。"
},
	[4908]={ lines="玫瑰的花香令人心旷神怡，但它的尖刺却又提醒着不可轻易触碰……要小心采摘哦，链尉官？", voice="hero_4515_cv_08.prefab", voice1="hero_4515_cv_08.prefab", lines1="玫瑰的花香令人心旷神怡，但它的尖刺却又提醒着不可轻易触碰……要小心采摘哦，链尉官？"
},
	[4909]={ lines="看在你很可爱的份上，这一单的价格我可以给你打个……九折。呵呵~", voice="hero_4515_cv_09.prefab", voice1="hero_4515_cv_09.prefab", lines1="看在你很可爱的份上，这一单的价格我可以给你打个……九折。呵呵~"
},
	[4910]={ lines="一份成功交易的订单，一杯酣战后的佳酿——人生如此，足够了。", voice="hero_4515_cv_10.prefab", voice1="hero_4515_cv_10.prefab", lines1="一份成功交易的订单，一杯酣战后的佳酿——人生如此，足够了。"
},
	[4911]={ lines="过去有人说我是叛徒，有人说我十恶不赦……呵，我不在乎这些没有意义的评价，因为这不会影响我拿到的赏金，哪怕是一分一厘都不会。", voice="hero_4515_cv_11.prefab", voice1="hero_4515_cv_11.prefab", lines1="过去有人说我是叛徒，有人说我十恶不赦……呵，我不在乎这些没有意义的评价，因为这不会影响我拿到的赏金，哪怕是一分一厘都不会。"
},
	[4912]={ lines="看你这样，是想要约我吗？可以啊，我也不想把你当做单纯的生意伙伴了，正好借此机会了解一下真正的你……呵呵。", voice="hero_4515_cv_12.prefab", voice1="hero_4515_cv_12.prefab", lines1="看你这样，是想要约我吗？可以啊，我也不想把你当做单纯的生意伙伴了，正好借此机会了解一下真正的你……呵呵。"
},
	[4913]={ lines="除了赚钱和购物，我还喜欢投资各种各样大大小小的项目，可惜的是它们大都失败了，不过令我惊喜的是……我在你身上的投资带来的收益，足以覆盖掉所有的失败。", voice="hero_4515_cv_13.prefab", voice1="hero_4515_cv_13.prefab", lines1="除了赚钱和购物，我还喜欢投资各种各样大大小小的项目，可惜的是它们大都失败了，不过令我惊喜的是……我在你身上的投资带来的收益，足以覆盖掉所有的失败。"
},
	[4914]={ lines="你这么关心我，是希望我给你一些折扣么？呵呵，如果是你的话……我可以不要赏金，只要你吻住我的嘴唇，品尝玫瑰的味道……", voice="hero_4515_cv_14.prefab", voice1="hero_4515_cv_14.prefab", lines1="你这么关心我，是希望我给你一些折扣么？呵呵，如果是你的话……我可以不要赏金，只要你吻住我的嘴唇，品尝玫瑰的味道……"
},
	[4915]={ lines="为我种下一簇红玫瑰吧，链尉官，当玫瑰盛放的时候，我便会回到你的身边——这是我和你一生都不会结束的委托。", voice="hero_4515_cv_15.prefab", voice1="hero_4515_cv_15.prefab", lines1="为我种下一簇红玫瑰吧，链尉官，当玫瑰盛放的时候，我便会回到你的身边——这是我和你一生都不会结束的委托。"
},
	[4916]={ lines="唉，为了等你，我身上都被晒的有些发烫呢……你可要负起责任哦？来帮我涂防晒乳吧。", voice="", voice1="hero_4515_cv_16.prefab", lines1="唉，为了等你，我身上都被晒的有些发烫呢……你可要负起责任哦？来帮我涂防晒乳吧，不只是背上和腿上，这里……也要好好地涂上才行呢。"
},
	[4917]={ lines="没想到你的委托居然是要我陪你来海边度假呢，难道说……其实你很想看到我的泳装？呵呵，你的小心思我还看不出来么，那么……怎么样？好看吗？", voice="", voice1="hero_4515_cv_17.prefab", lines1="没想到你的委托居然是要我陪你来海边度假呢，难道说……其实你很想看到我的泳装？呵呵，你的小心思我还看不出来么，那么……怎么样？好看吗？"
},
	[4918]={ lines="这根带子有些勒呢，要是影响我们接下来的活动就不好了……我是说，沙滩排球……", voice="", voice1="hero_4515_cv_18.prefab", lines1="这根带子有些勒衣服呢，要是影响我们接下来的活动就不好了……链尉官，帮我拉一下好吗？嗯……就是这里……"
},
	[4919]={ lines="被你抓到了呢……那么，你想要从我这里获得什么呢？情报，金钱，又或者……是别的一些什么……", voice="", voice1="hero_4515_cv_19.prefab", lines1="被你抓到了呢……那么，你想要从我这里获得什么呢？情报，金钱，又或者……是别的私人要求呢，警官大人~"
},
	[4920]={ lines="你想要怎么审问我呢？警官大人？", voice="", voice1="hero_4515_cv_20.prefab", lines1="呜……审问的方式有一些特别呢……还是说，这就是你的喜好……？"
},
	[4921]={ lines="既然你我二人兴致这么高，不如好好演完这一场角色扮演。", voice="", voice1="hero_4515_cv_21.prefab", lines1="既然你我二人兴致这么高，不如好好演完这一场角色扮演，毕竟剧情的高潮也是需要前戏铺垫的~呵呵~"
},
	[5001]={ lines="链尉官，哪怕这条路的未来依旧充满艰险，我也想和你继续走下去……请接受我全新的力量吧。", voice="hero_4516_cv_01.prefab", voice1="hero_4516_cv_01.prefab", lines1="链尉官，哪怕这条路的未来依旧充满艰险，我也想和你继续走下去……请接受我全新的力量吧。"
},
	[5002]={ lines="交给我吧，我已经能独当一面了。", voice="hero_4516_cv_02.prefab", voice1="hero_4516_cv_02.prefab", lines1="交给我吧，我已经能独当一面了。"
},
	[5003]={ lines="反抗只是徒劳。", voice="hero_4516_cv_03.prefab", voice1="hero_4516_cv_03.prefab", lines1="反抗只是徒劳。"
},
	[5004]={ lines="放弃挣扎吧。", voice="hero_4516_cv_04.prefab", voice1="hero_4516_cv_04.prefab", lines1="放弃挣扎吧。"
},
	[5005]={ lines="以此剑，昭示我的决心！", voice="hero_4516_cv_05.prefab", voice1="hero_4516_cv_05.prefab", lines1="以此剑，昭示我的决心！"
},
	[5006]={ lines="我会贯彻自己的信念，保护我所爱的一切。", voice="hero_4516_cv_06.prefab", voice1="hero_4516_cv_06.prefab", lines1="我会贯彻自己的信念，保护我所爱的一切。"
},
	[5007]={ lines="出发吧，我会一直在你身边。", voice="hero_4516_cv_07.prefab", voice1="hero_4516_cv_07.prefab", lines1="出发吧，我会一直在你身边。"
},
	[5008]={ lines="链尉官，你在忙吗？我没事，只是想在你旁边看着你忙的样子——嗯，很帅气，我很喜欢。", voice="hero_4516_cv_08.prefab", voice1="hero_4516_cv_08.prefab", lines1="链尉官，你在忙吗？我没事，只是想在你旁边看着你忙的样子——嗯，很帅气，我很喜欢。"
},
	[5009]={ lines="即便我拥有了新的力量，也依旧是那个属于你的艾丽西亚……唯独这点，我不想让你忘记。", voice="hero_4516_cv_09.prefab", voice1="hero_4516_cv_09.prefab", lines1="即便我拥有了新的力量，也依旧是那个属于你的艾丽西亚……唯独这点，我不想让你忘记。"
},
	[5010]={ lines="我做了许多新的danchey，大多都是按照你的模样缝制的——本来只是想做一个送给你，但不知不觉就做完了许多……", voice="hero_4516_cv_10.prefab", voice1="hero_4516_cv_10.prefab", lines1="我做了许多新的danchey，大多都是按照你的模样缝制的——本来只是想做一个送给你，但不知不觉就做完了许多……"
},
	[5011]={ lines="这身新的衣装，好看吗？这是我按照小时候你遇见我时，我穿的衣服改制的。我想让你现在看见的时候，也能回忆起那段美好的时光。", voice="hero_4516_cv_11.prefab", voice1="hero_4516_cv_11.prefab", lines1="这身新的衣装，好看吗？这是我按照小时候你遇见我时，我穿的衣服改制的。我想让你现在看见的时候，也能回忆起那段美好的时光。"
},
	[5012]={ lines="未来的一切都是不可知的，但因为有你在，我不会感到害怕和迷茫……和你一起走过的这条道路，是我最珍贵的宝物。", voice="hero_4516_cv_12.prefab", voice1="hero_4516_cv_12.prefab", lines1="未来的一切都是不可知的，但因为有你在，我不会感到害怕和迷茫……和你一起走过的这条道路，是我最珍贵的宝物。"
},
	[5013]={ lines="当我重新拥有了过往的记忆后，我想，如果我早点告诉你的话，说不定早就——不过，现在也为时不晚……所以，我们现在去约会吧，链尉官。……我是不是有点心急了？哼哼，我完全不这么认为，我已经想明白了，必须要提前出手才行。", voice="hero_4516_cv_13.prefab", voice1="hero_4516_cv_13.prefab", lines1="当我重新拥有了过往的记忆后，我想，如果我早点告诉你的话，说不定早就——不过，现在也为时不晚……所以，我们现在去约会吧，链尉官。……我是不是有点心急了？哼哼，我完全不这么认为，我已经想明白了，必须要提前出手才行。"
},
	[5014]={ lines="我永远不会忘记那片“星之角”，尽管时间会洗去一切，但它会被定格在我的心中，因为……我在那个地方知晓了什么是爱。", voice="hero_4516_cv_14.prefab", voice1="hero_4516_cv_14.prefab", lines1="我永远不会忘记那片“星之角”，尽管时间会洗去一切，但它会被定格在我的心中，因为……我在那个地方知晓了什么是爱。"
},
	[5015]={ lines="你总是这样，让我体会到许多美好的第一次，但我却越来越贪心，直到现在，我已经不想只是站在你的身边了，我希望你的爱情能全部属于我，为此，我也愿意……献上我的所有。", voice="hero_4516_cv_15.prefab", voice1="hero_4516_cv_15.prefab", lines1="你总是这样，让我体会到许多美好的第一次，但我却越来越贪心，直到现在，我已经不想只是站在你的身边了，我希望你的爱情能全部属于我，为此，我也愿意……献上我的所有。"
},
	[5016]={ lines="等到宴会典礼结束后，为我脱下这身礼装吧。我想在你面前做回我自己，做回只想在你怀中的艾丽西亚。", voice="hero_4516_cv_16.prefab", voice1="hero_4516_cv_16.prefab", lines1="等到宴会典礼结束后，为我脱下这身礼装吧。我想在你面前做回我自己，做回只想在你怀中的艾丽西亚。"
},
	[5017]={ lines="走了一会，脚有些疼……把鞋子脱掉吗？我知道了……嗯……没关系，链尉官揉的很舒服，手掌的温度，从脚心传了上来……很温暖。", voice="hero_4516_cv_17.prefab", voice1="hero_4516_cv_17.prefab", lines1="走了一会，脚有些疼……把鞋子脱掉吗？我知道了……嗯……没关系，链尉官揉的很舒服，手掌的温度，从脚心传了上来……很温暖。"
},
	[5018]={ lines="尽情放松吧，链尉官，这段时间里没有人会打扰你，如果有的话……我也会宣示主权的。", voice="hero_4516_cv_18.prefab", voice1="hero_4516_cv_18.prefab", lines1="尽情放松吧，链尉官，这段时间里没有人会打扰你，如果有的话……我也会宣示主权的。"
},
	[5019]={ lines="新年快乐，链尉官。听说这是星火那边的年俗，所以我也给你准备了一份……嗯……里面除了钱，还有别的东西……是什么……你打开看看就知道了……", voice="hero_4516_cv_19.prefab", voice1="hero_4516_cv_19.prefab", lines1="新年快乐，链尉官。听说这是星火那边的年俗，所以我也给你准备了一份……嗯……里面除了钱，还有别的东西……是什么……你打开看看就知道了……"
},
	[5020]={ lines="心间眷眷萦怀语，尽是无限相思意……回想起过去的点点滴滴，竟然都好像是刚刚发生的一样。一起守岁吧链尉官，这是今年最后一个夜晚了……也会是一个尽兴的夜晚……", voice="hero_4516_cv_20.prefab", voice1="hero_4516_cv_20.prefab", lines1="心间眷眷萦怀语，尽是无限相思意……回想起过去的点点滴滴，竟然都好像是刚刚发生的一样。一起守岁吧链尉官，这是今年最后一个夜晚了……也会是一个尽兴的夜晚……"
},
	[5021]={ lines="链尉官？……呀被你提前看到了，本来还想梳洗完毕给你一个惊喜的……你喜欢就好，我想要为了你去尝试更多不一样的风格……嗯，年年如今日，我们会一直走下去的。", voice="hero_4516_cv_21.prefab", voice1="hero_4516_cv_21.prefab", lines1="链尉官？……呀被你提前看到了，本来还想梳洗完毕给你一个惊喜的……你喜欢就好，我想要为了你去尝试更多不一样的风格……嗯，年年如今日，我们会一直走下去的。"
},
	[5022]={ lines="梦中期待的那个画面，今天终于实现了……戴上这枚戒指，我和链尉官的关系也终于结出了“果实”呢。", voice="hero_4516_cv_22.prefab", voice1="hero_4516_cv_22.prefab", lines1="梦中期待的那个画面，今天终于实现了……戴上这枚戒指，我和链尉官的关系也终于结出了“果实”呢。"
},
	[5023]={ lines="等仪式结束，就要迎来我们最重要的一夜了呢……我也准备好了哦，亲·爱·的~", voice="hero_4516_cv_23.prefab", voice1="hero_4516_cv_23.prefab", lines1="等仪式结束，就要迎来我们最重要的一夜了呢……我也准备好了哦，亲·爱·的~"
},
	[5024]={ lines="无论是你的战员、你的伴侣、还是你的爱人……往后的每一天，我都是只属于你的艾丽西亚——那么，余生也请多指教了，链尉官。", voice="hero_4516_cv_24.prefab", voice1="hero_4516_cv_24.prefab", lines1="无论是你的战员、你的伴侣、还是你的爱人……往后的每一天，我都是只属于你的艾丽西亚——那么，余生也请多指教了，链尉官。"
},
	[5051]={ lines="终于等到了这一天呢……", voice="", voice1="hero_4516_cv_1001.prefab", lines1="终于等到了这一天呢……"
},
	[5052]={ lines="我戴上去好看吗？", voice="", voice1="hero_4516_cv_1002.prefab", lines1="我戴上去好看吗？"
},
	[5053]={ lines="亲爱的喜欢什么样的曲子呢？", voice="", voice1="hero_4516_cv_1003.prefab", lines1="亲爱的喜欢什么样的曲子呢？"
},
	[5054]={ lines="这首曲子……里面都是我们的幸福回忆呢……", voice="", voice1="hero_4516_cv_1004.prefab", lines1="这首曲子……里面都是我们的幸福回忆呢……"
},
	[5055]={ lines="亲爱的来推我吗？那我就恭敬不如从命了~", voice="", voice1="hero_4516_cv_1005.prefab", lines1="亲爱的来推我吗？那我就恭敬不如从命了~"
},
	[5056]={ lines="亲爱的会喜欢偶尔调皮的我吗？……嗯，我也最喜欢你了……", voice="", voice1="hero_4516_cv_1006.prefab", lines1="亲爱的会喜欢偶尔调皮的我吗？……嗯，我也最喜欢你了……"
},
	[5057]={ lines="现在……是只属于我们的时间呢。", voice="", voice1="hero_4516_cv_1007.prefab", lines1="现在……是只属于我们的时间呢。"
},
	[5058]={ lines="亲爱的~想要做些什么呢……", voice="", voice1="hero_4516_cv_1008.prefab", lines1="亲爱的~想要做些什么呢……"
},
	[5059]={ lines="", voice="", voice1="hero_4516_cv_1009_1.prefab", lines1=""
},
	[5060]={ lines="", voice="", voice1="hero_4516_cv_1009_2.prefab", lines1=""
},
	[5061]={ lines="", voice="", voice1="hero_4516_cv_1009_3.prefab", lines1=""
},
	[5062]={ lines="", voice="", voice1="hero_4516_cv_1009_4.prefab", lines1=""
},
	[5063]={ lines="", voice="", voice1="hero_4516_cv_1009_5.prefab", lines1=""
},
	[5064]={ lines="", voice="", voice1="hero_4516_cv_1009_6.prefab", lines1=""
},
	[5065]={ lines="", voice="", voice1="hero_4516_cv_1010_1.prefab", lines1=""
},
	[5066]={ lines="", voice="", voice1="hero_4516_cv_1010_2.prefab", lines1=""
},
	[5067]={ lines="", voice="", voice1="hero_4516_cv_1010_3.prefab", lines1=""
},
	[5068]={ lines="", voice="", voice1="hero_4516_cv_1010_4.prefab", lines1=""
},
	[5069]={ lines="今天的一切……我一生都不会忘记，亲爱的也是这样吗？", voice="", voice1="hero_4516_cv_1011.prefab", lines1="今天的一切……我一生都不会忘记，亲爱的也是这样吗？"
},
	[5070]={ lines="唔嗯？！你也会有粗鲁的一面呢……不，不过……我也很喜欢……", voice="", voice1="hero_4516_cv_1012.prefab", lines1="唔嗯？！你也会有粗鲁的一面呢……不，不过……我也很喜欢……"
},
	[5071]={ lines="链尉官的心意我已经收到了哦，那么，请你听好我的回答：我愿意和你一起跨过时间和生死，共享所有的幸福与美好，生生世世，永不分离。", voice="hero_4516_cv_2001.prefab", voice1="hero_4516_cv_2001.prefab", lines1="链尉官的心意我已经收到了哦，那么，请你听好我的回答：我愿意和你一起跨过时间和生死，共享所有的幸福与美好，生生世世，永不分离。"
},
	[5101]={ lines="自我介绍？要再来一遍吗？大家都认识我了，也知道你是我的投资人……好吧，亲爱的链尉官大人，作为最忠诚专一的下属，西娜卡，代号阿尔戈，前来向你报道。", voice="hero_4517_cv_01.prefab", voice1="hero_4517_cv_01.prefab", lines1="自我介绍？要再来一遍吗？大家都认识我了，也知道你是我的投资人……好吧，亲爱的链尉官大人，作为最忠诚专一的下属，西娜卡，代号阿尔戈，前来向你报道。"
},
	[5102]={ lines="欸？是需要我的帮助吗？出钱还是出力……嘿嘿，总之！阿尔戈遵命！听从链尉官调遣，一定完成任务。", voice="hero_4517_cv_02.prefab", voice1="hero_4517_cv_02.prefab", lines1="欸？是需要我的帮助吗？出钱还是出力……嘿嘿，总之！阿尔戈遵命！听从链尉官调遣，一定完成任务。"
},
	[5103]={ lines="阿尔戈激光，发——射——", voice="hero_4517_cv_03.prefab", voice1="hero_4517_cv_03.prefab", lines1="阿尔戈激光，发——射——"
},
	[5104]={ lines="嘻嘻，看看这个是什么~我的手里、还、有、呢！", voice="hero_4517_cv_04.prefab", voice1="hero_4517_cv_04.prefab", lines1="嘻嘻，看看这个是什么~我的手里、还、有、呢！"
},
	[5105]={ lines="给你看个大宝贝~不收钱哦~", voice="hero_4517_cv_05.prefab", voice1="hero_4517_cv_05.prefab", lines1="给你看个大宝贝~不收钱哦~"
},
	[5106]={ lines="我果然没有让你失望吧！你会怎么奖励我呢？", voice="hero_4517_cv_06.prefab", voice1="hero_4517_cv_06.prefab", lines1="我果然没有让你失望吧！你会怎么奖励我呢？"
},
	[5107]={ lines="大忙人链尉官终于舍得回来啦~有想我吗？我可非常想你呢，欸？作为下属惦记着长官，难道不是应该的吗？", voice="hero_4517_cv_07.prefab", voice1="hero_4517_cv_07.prefab", lines1="大忙人链尉官终于舍得回来啦~有想我吗？我可非常想你呢，欸？作为下属惦记着长官，难道不是应该的吗？"
},
	[5108]={ lines="有个好消息和一个坏消息，想先听哪个？好消息是我的身份审查报告通过了！坏消息嘛……一看到你我就把它给忘啦！", voice="hero_4517_cv_08.prefab", voice1="hero_4517_cv_08.prefab", lines1="有个好消息和一个坏消息，想先听哪个？好消息是我的身份审查报告通过了！坏消息嘛……一看到你我就把它给忘啦！"
},
	[5109]={ lines="你……你怎么回来了？！没有没有我手里什么都没有……好吧，只是稍微降了一点点点价格而已，怎么就说我非法竞争了啊！！", voice="hero_4517_cv_09.prefab", voice1="hero_4517_cv_09.prefab", lines1="你……你怎么回来了？！没有没有我手里什么都没有……好吧，只是稍微降了一点点点价格而已，怎么就说我非法竞争了啊！！"
},
	[5110]={ lines="顾客来来好运来来……我在做什么？当然是给自己求好运许愿生意兴隆了，百试百灵，不信你来试试！", voice="hero_4517_cv_10.prefab", voice1="hero_4517_cv_10.prefab", lines1="顾客来来好运来来……我在做什么？当然是给自己求好运许愿生意兴隆了，百试百灵，不信你来试试！"
},
	[5111]={ lines="想知道最近市场上最流行的货品是什么？坐到我身边来，和我一起看完这份报表你就明白了！我可一点坏心思都没有呢，真的！", voice="hero_4517_cv_11.prefab", voice1="hero_4517_cv_11.prefab", lines1="想知道最近市场上最流行的货品是什么？坐到我身边来，和我一起看完这份报表你就明白了！我可一点坏心思都没有呢，真的！"
},
	[5112]={ lines="一边四处旅行一边搜集稀有货品，在合适的时间和地点把它们卖出去一个好价钱，于是我有了现在这样富裕的生活……最重要的是我还在这个过程中遇到你了呢，我的好链尉官！", voice="hero_4517_cv_12.prefab", voice1="hero_4517_cv_12.prefab", lines1="一边四处旅行一边搜集稀有货品，在合适的时间和地点把它们卖出去一个好价钱，于是我有了现在这样富裕的生活……最重要的是我还在这个过程中遇到你了呢，我的好链尉官！"
},
	[5113]={ lines="石飞蜓的鞘翅售价三十万泰诺币一克，但尤赞坦的顶尖宝石一克拉就要十几万泰诺币，假如我要为你买一枚最上等的月光石……唔让我算算，我要卖多少份鞘翅呢？", voice="hero_4517_cv_13.prefab", voice1="hero_4517_cv_13.prefab", lines1="石飞蜓的鞘翅售价三十万泰诺币一克，但尤赞坦的顶尖宝石一克拉就要十几万泰诺币，假如我要为你买一枚最上等的月光石……唔让我算算，我要卖多少份鞘翅呢？"
},
	[5114]={ lines="我的愿望吗？赚很多很多钱，这样就可以得到想要的一切了。但是遇到你之后，我又有了新的愿望，链尉官，我希望你能一直陪在我身边，你会愿意答应我吗？", voice="hero_4517_cv_14.prefab", voice1="hero_4517_cv_14.prefab", lines1="我的愿望吗？赚很多很多钱，这样就可以得到想要的一切了。但是遇到你之后，我又有了新的愿望，链尉官，我希望你能一直陪在我身边，你会愿意答应我吗？"
},
	[5115]={ lines="人类可真是一种贪婪的生物！只要活着一天，欲望就一天无法被满足……嗯……我是在说经商赚钱啦……（别扭，害羞的短暂沉默）好吧，我承认我有点不满足于现状了，我想要更多，我想和你在一起……就……就算是偷偷摸摸也可以，只要你答应我！", voice="hero_4517_cv_15.prefab", voice1="hero_4517_cv_15.prefab", lines1="人类可真是一种贪婪的生物！只要活着一天，欲望就一天无法被满足……嗯……我是在说经商赚钱啦……（别扭，害羞的短暂沉默）好吧，我承认我有点不满足于现状了，我想要更多，我想和你在一起……就……就算是偷偷摸摸也可以，只要你答应我！"
},
	[5116]={ lines="今天好像有点热，感觉出了一身的汗……还好我提前买了果茶，冰冰凉凉，甜度不多也不少，就像是爱情一样……欸？不信的话你尝一口~", voice="hero_4517_cv_16.prefab", voice1="hero_4517_cv_16.prefab", lines1="今天好像有点热，感觉出了一身的汗……还好我提前买了果茶，冰冰凉凉，甜度不多也不少，就像是爱情一样……欸？不信的话你尝一口~"
},
	[5117]={ lines="这个娃娃是我特别定制的哦~只要把它带在身边，做什么事情我都会很有安全感，不过现在不需要了……因为它的原型，你，就在我身边，链尉官，我可以直接拥抱你吗？", voice="hero_4517_cv_17.prefab", voice1="hero_4517_cv_17.prefab", lines1="这个娃娃是我特别定制的哦~只要把它带在身边，做什么事情我都会很有安全感，不过现在不需要了……因为它的原型，你，就在我身边，链尉官，我可以直接拥抱你吗？"
},
	[5118]={ lines="摩天轮马上就到最高处了，快许个愿吧……今晚不会有工作打扰我们的，就像之前说好的那样，我的时间完完全全只属于你，做什么、去哪儿，全部都听链尉官你的安排。", voice="hero_4517_cv_18.prefab", voice1="hero_4517_cv_18.prefab", lines1="摩天轮马上就到最高处了，快许个愿吧……今晚不会有工作打扰我们的，就像之前说好的那样，我的时间完完全全只属于你，做什么、去哪儿，全部都听链尉官你的安排。"
},
	[5201]={ lines="我是辉月，来自护星骑士团——在月光的指引下，我会全力协助你，链尉官。", voice="hero_4518_cv_01.prefab", voice1="hero_4518_cv_01.prefab", lines1="我是辉月，来自护星骑士团——在月光的指引下，我会全力协助你，链尉官。"
},
	[5202]={ lines="月夜已至。", voice="hero_4518_cv_02.prefab", voice1="hero_4518_cv_02.prefab", lines1="月夜已至。"
},
	[5203]={ lines="卑劣之人。", voice="hero_4518_cv_03.prefab", voice1="hero_4518_cv_03.prefab", lines1="卑劣之人。"
},
	[5204]={ lines="因寒冷而颤抖了么？", voice="hero_4518_cv_04.prefab", voice1="hero_4518_cv_04.prefab", lines1="因寒冷而颤抖了么？"
},
	[5205]={ lines="无垠的月光啊，请回应我的祈求——", voice="hero_4518_cv_05.prefab", voice1="hero_4518_cv_05.prefab", lines1="无垠的月光啊，请回应我的祈求——"
},
	[5206]={ lines="月光会回到每一个在夜晚徘徊的人心中。", voice="hero_4518_cv_06.prefab", voice1="hero_4518_cv_06.prefab", lines1="月光会回到每一个在夜晚徘徊的人心中。"
},
	[5207]={ lines="链尉官，今晚的月色也很美丽，要去外面走走吗？", voice="hero_4518_cv_07.prefab", voice1="hero_4518_cv_07.prefab", lines1="链尉官，今晚的月色也很美丽，要去外面走走吗？"
},
	[5208]={ lines="时常在晚上见到我？我喜欢月下的静谧世界，这能让我内心感到惬意。", voice="hero_4518_cv_08.prefab", voice1="hero_4518_cv_08.prefab", lines1="时常在晚上见到我？我喜欢月下的静谧世界，这能让我内心感到惬意。"
},
	[5209]={ lines="这本小说情节跌宕起伏，渲染的氛围让人心有共鸣……推荐给你，链尉官。", voice="hero_4518_cv_09.prefab", voice1="hero_4518_cv_09.prefab", lines1="这本小说情节跌宕起伏，渲染的氛围让人心有共鸣……推荐给你，链尉官。"
},
	[5210]={ lines="如果你因迷茫而迷失了方向，那就遵循月光的指引吧，我会在那光芒下找到你。", voice="hero_4518_cv_10.prefab", voice1="hero_4518_cv_10.prefab", lines1="如果你因迷茫而迷失了方向，那就遵循月光的指引吧，我会在那光芒下找到你。"
},
	[5211]={ lines="月有阴晴圆缺，人也有悲欢离合，阅读将这些情感波折撰写而成的故事，是我的兴趣爱好。", voice="hero_4518_cv_11.prefab", voice1="hero_4518_cv_11.prefab", lines1="月有阴晴圆缺，人也有悲欢离合，阅读将这些情感波折撰写而成的故事，是我的兴趣爱好。"
},
	[5212]={ lines="如你所见，我正在尝试着创作爱情小说，但最近却有些灵感枯竭……听蒂雅说你的情感经历很丰富，可以向你讨教一下么？", voice="hero_4518_cv_12.prefab", voice1="hero_4518_cv_12.prefab", lines1="如你所见，我正在尝试着创作爱情小说，但最近却有些灵感枯竭……听蒂雅说你的情感经历很丰富，可以向你讨教一下么？"
},
	[5213]={ lines="我参考你提供的经历，写好了一部分，不过却有些疑惑的地方……也许是因为我不是这些经历里的女主角，所以不能体会到她们的心情。要怎么做才能切身感受呢……", voice="hero_4518_cv_13.prefab", voice1="hero_4518_cv_13.prefab", lines1="我参考你提供的经历，写好了一部分，不过却有些疑惑的地方……也许是因为我不是这些经历里的女主角，所以不能体会到她们的心情。要怎么做才能切身感受呢……"
},
	[5214]={ lines="哪怕只是和你在星都月下巡游，我的心依旧澎湃万分，原来这就是我想要写的东西……所以，我想积累更多的素材……就，就从……牵，牵手开始？还是，更进一步的……唔……！你这样太犯规了……", voice="hero_4518_cv_14.prefab", voice1="hero_4518_cv_14.prefab", lines1="哪怕只是和你在星都月下巡游，我的心依旧澎湃万分，原来这就是我想要写的东西……所以，我想积累更多的素材……就，就从……牵，牵手开始？还是，更进一步的……唔……！你这样太犯规了……"
},
	[5215]={ lines="我想过许多词语来形容你在我心里的份量，可我绞尽脑汁也想象不出来最适合的那一个……后来我终于明白，你就是你，就像如水月光一样独一无二，倒映着我生命的全部……在月夜的见证下，我可以做你的女主角吗？", voice="hero_4518_cv_15.prefab", voice1="hero_4518_cv_15.prefab", lines1="我想过许多词语来形容你在我心里的份量，可我绞尽脑汁也想象不出来最适合的那一个……后来我终于明白，你就是你，就像如水月光一样独一无二，倒映着我生命的全部……在月夜的见证下，我可以做你的女主角吗？"
},
	[5216]={ lines="……是你吗链尉官？我一直在等你……诶，为什么躺在地上？因为地板软软的，很舒服……快来跟我一起吧，链尉官……", voice="", voice1="hero_4518_cv_16.prefab", lines1="……是你吗链尉官？我一直在等你……诶，为什么躺在地上？因为地板软软的，很舒服……快来跟我一起吧，链尉官，还是说……你想去床上……？"
},
	[5217]={ lines="送我礼物吗？我也有礼物送给你……她们说你喜欢兔子，那你喜欢我这样的兔兔吗？嘿嘿……送给你~", voice="", voice1="hero_4518_cv_17.prefab", lines1="送我礼物吗？我也有礼物送给你……她们说你喜欢兔子，那你喜欢我这样的兔兔吗？嘿嘿……送给你~"
},
	[5218]={ lines="粉色的房间，微醺的气氛，昏暗的灯光……听说这些都是小说里推进情节发展的必要措施……是这样的吗？链尉官？", voice="", voice1="hero_4518_cv_18.prefab", lines1="心形的大床，微醺的气氛，昏暗的灯光……这些都是，推进情节发展的必要措施……身为男主角的你，猜到要继续做什么了吗？链尉官？"
},
	[5219]={ lines="被你这样注视着，感觉自己都有点不好意思了……这样的我，你会喜欢吗？", voice="", voice1="hero_4518_cv_19.prefab", lines1="啊嗯……被你这样注视着，感觉身体都变得更加兴奋了……这样的我，你会喜欢吗？"
},
	[5220]={ lines="唔……酒怎么洒出来了……就这样没关系的……", voice="", voice1="hero_4518_cv_20.prefab", lines1="唔……它怎么……洒出来了……就这样没关系的……是你给我的……"
},
	[5221]={ lines="杯酒未酌，我却已经有些醉了……链尉官，我有些话想要悄悄说给你听……", voice="", voice1="hero_4518_cv_21.prefab", lines1="杯酒未酌，我却已经有些醉了……链尉官，今夜你我共宿于此，我也有些话想要悄悄说给你听……"
},
	[5301]={ lines="就是说，以后我要陪在你身边了吗？谢谢……我不会辜负你的信任。", voice="hero_4519_cv_01.prefab", voice1="hero_4519_cv_01.prefab", lines1="就是说，以后我要陪在你身边了吗？谢谢……我不会辜负你的信任。"
},
	[5302]={ lines="我会做你最趁手的一件兵器。", voice="hero_4519_cv_02.prefab", voice1="hero_4519_cv_02.prefab", lines1="我会做你最趁手的一件兵器。"
},
	[5303]={ lines="毫无意义。", voice="hero_4519_cv_03.prefab", voice1="hero_4519_cv_03.prefab", lines1="毫无意义。"
},
	[5304]={ lines="将予你烬灭。", voice="hero_4519_cv_04.prefab", voice1="hero_4519_cv_04.prefab", lines1="将予你烬灭。"
},
	[5305]={ lines="不必畏惧这一瞬的灼烧，它将与你一同消逝。", voice="hero_4519_cv_05.prefab", voice1="hero_4519_cv_05.prefab", lines1="不必畏惧这一瞬的灼烧，它将与你一同消逝。"
},
	[5306]={ lines="链尉官，我做的还让你满意吗？", voice="hero_4519_cv_06.prefab", voice1="hero_4519_cv_06.prefab", lines1="链尉官，我做的还让你满意吗？"
},
	[5307]={ lines="她们说，我等在这里，就能在你回来时第一个见到你。", voice="hero_4519_cv_07.prefab", voice1="hero_4519_cv_07.prefab", lines1="她们说，我等在这里，就能在你回来时第一个见到你。"
},
	[5308]={ lines="我偶然看到了一篇很有意思的旅游攻略，那儿的风景很好，我想在有空的时候，和你一起去那里走走……这算是好好生活的一种表现吗？", voice="hero_4519_cv_08.prefab", voice1="hero_4519_cv_08.prefab", lines1="我偶然看到了一篇很有意思的旅游攻略，那儿的风景很好，我想在有空的时候，和你一起去那里走走……这算是好好生活的一种表现吗？"
},
	[5309]={ lines="鳞片……漂亮吗？偶尔会有自然的脱落，我把它们都收集了起来，做成了这个……等完成的那一天，我希望你可以收下，这样它就可以代替我陪在你身边了。", voice="hero_4519_cv_09.prefab", voice1="hero_4519_cv_09.prefab", lines1="鳞片……漂亮吗？偶尔会有自然的脱落，我把它们都收集了起来，做成了这个……等完成的那一天，我希望你可以收下，这样它就可以代替我陪在你身边了。"
},
	[5310]={ lines="一看到你，心跳就会不由自主地变快，从很久以前就是这样了……链尉官，你可以再走近一点吗？我快要按捺不住自己了，我觉得我的心马上就要跳出来了……！", voice="hero_4519_cv_10.prefab", voice1="hero_4519_cv_10.prefab", lines1="一看到你，心跳就会不由自主地变快，从很久以前就是这样了……链尉官，你可以再走近一点吗？我快要按捺不住自己了，我觉得我的心马上就要跳出来了……！"
},
	[5311]={ lines="早安，午安，晚安——希望每一天的早上、中午还有睡前，我都可以微笑着向你问好。", voice="hero_4519_cv_11.prefab", voice1="hero_4519_cv_11.prefab", lines1="早安，午安，晚安——希望每一天的早上、中午还有睡前，我都可以微笑着向你问好。"
},
	[5312]={ lines="对未来的期待吗？和你一起读书、跳舞，还有拯救世界，和你一起做所有曾经想过的事情……其他的吗？没有……我所有和未来有关的畅想都和你密不可分。", voice="hero_4519_cv_12.prefab", voice1="hero_4519_cv_12.prefab", lines1="对未来的期待吗？和你一起读书、跳舞，还有拯救世界，和你一起做所有曾经想过的事情……其他的吗？没有……我所有和未来有关的畅想都和你密不可分。"
},
	[5313]={ lines="偶尔在深夜的时候，我会难以抑制地冒出离开这个世界的想法……但是想到对你的承诺、想到要和你一起走向新生活，这种念头就会马上消失……我想你了，我想见你一面。", voice="hero_4519_cv_13.prefab", voice1="hero_4519_cv_13.prefab", lines1="偶尔在深夜的时候，我会难以抑制地冒出离开这个世界的想法……但是想到对你的承诺、想到要和你一起走向新生活，这种念头就会马上消失……我想你了，我想见你一面。"
},
	[5314]={ lines="我可以邀请你吗？我最近在试着学习跳一支舞蹈，等你来了我的房子里，我可以跳给你看……为什么是房子，而不是家？只有你在的地方，才可以称为我的家。", voice="hero_4519_cv_14.prefab", voice1="hero_4519_cv_14.prefab", lines1="我可以邀请你吗？我最近在试着学习跳一支舞蹈，等你来了我的房子里，我可以跳给你看……为什么是房子，而不是家？只有你在的地方，才可以称为我的家。"
},
	[5315]={ lines="你真的就在我的旁边，是我触手可及的爱人……链尉官，请你用炽热的爱将我的心填满，让我空洞的灵魂找到寄托……这样我才能相信，相遇之后的一切都不是梦……对吗？", voice="", voice1="hero_4519_cv_15.prefab", lines1="你真的就在我的旁边，是我触手可及的爱人……链尉官，请你用炽热的爱将我填满，让我空洞的灵魂找到寄托……这样我才能相信，相遇之后的一切都不是梦……对吗？"
},
	[5316]={ lines="嗯哼哼……好痒……快要站不住了……", voice="", voice1="hero_4519_cv_16.prefab", lines1="嗯哼哼……好痒……快要站不住了……不要玩儿了……"
},
	[5317]={ lines="……都听你的，这是只有我和你独处的时光，只要你喜欢，我什么都可以……", voice="", voice1="hero_4519_cv_17.prefab", lines1="……都听你的，这是只有我和你独处的时光，只要你喜欢，我什么都可以……"
},
	[5318]={ lines="好想和你在一起……想要和你拥抱，还有很多话想要对你说……链尉官，再靠近我一点好吗？", voice="", voice1="hero_4519_cv_18.prefab", lines1="不够……还不够……想要得到更多……想要被你抚摸、拥抱，还有很多话想要对你说……链尉官，再靠近我一点好吗？"
},
	[5319]={ lines="周围的装饰品太多了，链尉官可以帮我拿开吗？", voice="", voice1="hero_4519_cv_19.prefab", lines1="呜嗯……！牛奶要滴到脸上了，链尉官可以帮我清理一下吗，我现在……有些不方便……"
},
	[5320]={ lines="链尉官觉得我这条新裙子好看吗？就像糖霜一样。", voice="", voice1="hero_4519_cv_20.prefab", lines1="啊……链尉官还是像往常那样抚摸我呢……"
},
	[5321]={ lines="亮晶晶的星星，亮晶晶的链尉官……感觉连自己的心情都变得不一样了……", voice="", voice1="hero_4519_cv_21.prefab", lines1="唔嗯？！！嗯，没关系……只是因为这个姿势，身体更敏感了一些……"
},
	[5401]={ lines="现在的我，既是骑士，也是莱斯坦斯的战员。但无论是哪一种身份，我都会为你倾尽所能，链尉官。", voice="hero_4520_cv_01.prefab", voice1="hero_4520_cv_01.prefab", lines1="现在的我，既是骑士，也是莱斯坦斯的战员。但无论是哪一种身份，我都会为你倾尽所能，链尉官。"
},
	[5402]={ lines="我不会辜负你的信任。", voice="hero_4520_cv_02.prefab", voice1="hero_4520_cv_02.prefab", lines1="我不会辜负你的信任。"
},
	[5403]={ lines="没有理由放过你。", voice="hero_4520_cv_03.prefab", voice1="hero_4520_cv_03.prefab", lines1="没有理由放过你。"
},
	[5404]={ lines="倒在这剑下，你不会有任何痛苦。", voice="hero_4520_cv_04.prefab", voice1="hero_4520_cv_04.prefab", lines1="倒在这剑下，你不会有任何痛苦。"
},
	[5405]={ lines="我将以骑士之誓，挥舞晨光，斩碎黑暗！", voice="hero_4520_cv_05.prefab", voice1="hero_4520_cv_05.prefab", lines1="我将以骑士之誓，挥舞晨光，斩碎黑暗！"
},
	[5406]={ lines="有你在我身后，我不会退缩一步。", voice="hero_4520_cv_06.prefab", voice1="hero_4520_cv_06.prefab", lines1="有你在我身后，我不会退缩一步。"
},
	[5407]={ lines="工作结束了？如果累了，就去休息吧，我会守在门外。", voice="hero_4520_cv_07.prefab", voice1="hero_4520_cv_07.prefab", lines1="工作结束了？如果累了，就去休息吧，我会守在门外。"
},
	[5408]={ lines="自此之后，我已知晓属于我的前路，最重要的是……还能继续与你同行，链尉官。", voice="hero_4520_cv_08.prefab", voice1="hero_4520_cv_08.prefab", lines1="自此之后，我已知晓属于我的前路，最重要的是……还能继续与你同行，链尉官。"
},
	[5409]={ lines="这柄剑，老师说代表着传承和守护，我曾经无法理解，而现在……是你让我知道了它的意义。", voice="hero_4520_cv_09.prefab", voice1="hero_4520_cv_09.prefab", lines1="这柄剑，老师说代表着传承和守护，我曾经无法理解，而现在……是你让我知道了它的意义。"
},
	[5410]={ lines="维拉提亚需要我的时候，我会出现，这并非情理，而是你所说的那样，是一种义务。", voice="hero_4520_cv_10.prefab", voice1="hero_4520_cv_10.prefab", lines1="维拉提亚需要我的时候，我会出现，这并非情理，而是你所说的那样，是一种义务。"
},
	[5411]={ lines="这身武装给我的感觉既熟悉又陌生，也许这就是身份转换带来的不适感……还是那个熟悉的朝晖么……？呵呵，有你这句话，我安心了不少。", voice="hero_4520_cv_11.prefab", voice1="hero_4520_cv_11.prefab", lines1="这身武装给我的感觉既熟悉又陌生，也许这就是身份转换带来的不适感……还是那个熟悉的朝晖么……？呵呵，有你这句话，我安心了不少。"
},
	[5412]={ lines="哪怕是穿上这身武装，我也不会想要回到骑士团——嗯，那里曾经是我的家，但也已经是过去的记忆……现在的我，只想待在和你有关的地方。你在哪，我就在哪。", voice="hero_4520_cv_12.prefab", voice1="hero_4520_cv_12.prefab", lines1="哪怕是穿上这身武装，我也不会想要回到骑士团——嗯，那里曾经是我的家，但也已经是过去的记忆……现在的我，只想待在和你有关的地方。你在哪，我就在哪。"
},
	[5413]={ lines="星澜花的幼苗……？呵呵，原来你还记得。嗯，开花的时间就在这两天了，我们一起去看吧。", voice="hero_4520_cv_13.prefab", voice1="hero_4520_cv_13.prefab", lines1="星澜花的幼苗……？呵呵，原来你还记得。嗯，开花的时间就在这两天了，我们一起去看吧。"
},
	[5414]={ lines="所谓骑士，每个人的理解都会各自有所区别。在我的理解里，这四个字的意义就是为你举枪，为你挥剑——我是只属于你的骑士，链尉官。", voice="hero_4520_cv_14.prefab", voice1="hero_4520_cv_14.prefab", lines1="所谓骑士，每个人的理解都会各自有所区别。在我的理解里，这四个字的意义就是为你举枪，为你挥剑——我是只属于你的骑士，链尉官。"
},
	[5415]={ lines="虽然骑士的准则是默默地守护，但你的这些举动，总是在挑拨着我想要迈出那一步的神经……唉，你知不知道我忍了有多久？我再问你一遍，你，应该，知道，我的意思是什么吧……？", voice="hero_4520_cv_15.prefab", voice1="hero_4520_cv_15.prefab", lines1="虽然骑士的准则是默默地守护，但你的这些举动，总是在挑拨着我想要迈出那一步的神经……唉，你知不知道我忍了有多久？我再问你一遍，你，应该，知道，我的意思是什么吧……？"
},
	[5416]={ lines="链尉官？嗯，如你所见，空调似乎坏了，所以我脱掉了外套，让自己凉快一些，那么接下来的工作安排……诶？衣服也打湿了？那是雨水……！", voice="", voice1="hero_4520_cv_16.prefab", lines1="链尉官？嗯，如你所见，空调似乎坏了，所以我脱掉了外套，让自己凉快一些，那么接下来的工作安排……诶？衣服也打湿了？那是雨水……！"
},
	[5417]={ lines="房间里的温度好像越来越高了……链尉官，如果你热的话就把衣服脱下来吧——", voice="", voice1="hero_4520_cv_17.prefab", lines1="房间里的温度好像越来越高了……链尉官，如果你热的话就把衣服脱下来吧——我也一起？！你啊……目的太明显了吧？不过既然是你的要求，那就……袜，袜子也要吗？！"
},
	[5418]={ lines="你的脸很红，是因为太热了么，去淋浴室冲个凉吧？", voice="", voice1="hero_4520_cv_18.prefab", lines1="你的脸很红，是因为太热了么，还是说……呵呵，不用这么着急，离工作开始还有一些时间……结束之后一起去淋浴室吧？"
},
	[5419]={ lines="这样就结束了么，链尉官？我本以为，你会有更重的好奇心，比如说……听我讲讲书里其他的故事……", voice="", voice1="hero_4520_cv_19.prefab", lines1="哈……哈……这样就结束了么，链尉官？我本以为，你会有更重的好奇心，比如说……离我更近一些的地方……"
},
	[5420]={ lines="呀……好凉！呼，幸亏没洒到书上——还好你帮我挡住了。", voice="", voice1="hero_4520_cv_20.prefab", lines1="呀……好凉！呼，幸亏没洒到书上——原来……你都计算好了，呵呵，链尉官果然技高一筹呢。"
},
	[5421]={ lines="为什么会在书房？……或许是换个心情，或许是你和我心有灵犀，其实，你早就看穿我的想法了吧，但你还是如约而至……那么，就像这本书一样，摘下封套，打开首页，摩挲我的心意吧。", voice="", voice1="hero_4520_cv_21.prefab", lines1="为什么会在书房？……或许是换个心情，或许是你和我心有灵犀，其实，你早就看穿我的想法了吧，但你还是如约而至……那么，就像这本书一样，摘下封套，打开首页，摩挲我的心意吧。"
},
	[5501]={ lines="我叫双，好事成双的双，代号云篆。算卦、画符、解梦、做饭都是我的业务范围……价格……嗯，链尉官你的话，通通免费好了~", voice="hero_4521_cv_01.prefab", voice1="hero_4521_cv_01.prefab", lines1="我叫双，好事成双的双，代号云篆。算卦、画符、解梦、做饭都是我的业务范围……价格……嗯，链尉官你的话，通通免费好了~"
},
	[5502]={ lines="我掐指一算，此战必胜~", voice="hero_4521_cv_02.prefab", voice1="hero_4521_cv_02.prefab", lines1="我掐指一算，此战必胜~"
},
	[5503]={ lines="霄戈暮止，心字结诚。", voice="hero_4521_cv_03.prefab", voice1="hero_4521_cv_03.prefab", lines1="霄戈暮止，心字结诚。"
},
	[5504]={ lines="藏风聚水，灵云自跃。", voice="hero_4521_cv_04.prefab", voice1="hero_4521_cv_04.prefab", lines1="藏风聚水，灵云自跃。"
},
	[5505]={ lines="八方玄冥，四时吉凶，得我诏令，急行切止！", voice="hero_4521_cv_05.prefab", voice1="hero_4521_cv_05.prefab", lines1="八方玄冥，四时吉凶，得我诏令，急行切止！"
},
	[5506]={ lines="如此，你便可高枕而卧也~", voice="hero_4521_cv_06.prefab", voice1="hero_4521_cv_06.prefab", lines1="如此，你便可高枕而卧也~"
},
	[5507]={ lines="瞧你眉间红光熠熠，是遇到什么开心的事情了吗？", voice="hero_4521_cv_07.prefab", voice1="hero_4521_cv_07.prefab", lines1="瞧你眉间红光熠熠，是遇到什么开心的事情了吗？"
},
	[5508]={ lines="糖、油、蛋、新鲜牛乳、还缺什么呢……让我想想……欸链尉官你回来的正好，你说，一份糖蒸酥酪里再加点什么好呢？杏仁怎么样？", voice="hero_4521_cv_08.prefab", voice1="hero_4521_cv_08.prefab", lines1="糖、油、蛋、新鲜牛乳、还缺什么呢……让我想想……欸链尉官你回来的正好，你说，一份糖蒸酥酪里再加点什么好呢？杏仁怎么样？"
},
	[5509]={ lines="……泱泱灵神，闻我微志，求告天地八方神灵显真言——噫，链尉官不许偷看！但是在解卦前，你可以先猜一下是凶相呢还是吉运呢~", voice="hero_4521_cv_09.prefab", voice1="hero_4521_cv_09.prefab", lines1="……泱泱灵神，闻我微志，求告天地八方神灵显真言——噫，链尉官不许偷看！但是在解卦前，你可以先猜一下是凶相呢还是吉运呢~"
},
	[5510]={ lines="小仙我夜观天象，见天上千星结阵，如此异象实在罕见，恐有……咦？你说那就是空天星链……唔，如此说来，那这必然是吉兆了！", voice="hero_4521_cv_10.prefab", voice1="hero_4521_cv_10.prefab", lines1="小仙我夜观天象，见天上千星结阵，如此异象实在罕见，恐有……咦？你说那就是空天星链……唔，如此说来，那这必然是吉兆了！"
},
	[5511]={ lines="饿了的话随时来找我，我这边什么好吃的都有……嗯……不饿的话也欢迎来找我算卦聊天呀！我随时奉陪~", voice="hero_4521_cv_11.prefab", voice1="hero_4521_cv_11.prefab", lines1="饿了的话随时来找我，我这边什么好吃的都有……嗯……不饿的话也欢迎来找我算卦聊天呀！我随时奉陪~"
},
	[5512]={ lines="链尉官，我看不透你，甚至卦象都只能看到你的过去，无法预测你的将来……我从来没有见过像你这样特别的命格，感觉你身上的谜团真的越来越多了……", voice="hero_4521_cv_12.prefab", voice1="hero_4521_cv_12.prefab", lines1="链尉官，我看不透你，甚至卦象都只能看到你的过去，无法预测你的将来……我从来没有见过像你这样特别的命格，感觉你身上的谜团真的越来越多了……"
},
	[5513]={ lines="卦上说，我最近运势不济，需要和一个吉运的人待在一起才行……那个人就是你啦，接下来几天拜托你多多关照，链尉官~", voice="hero_4521_cv_13.prefab", voice1="hero_4521_cv_13.prefab", lines1="卦上说，我最近运势不济，需要和一个吉运的人待在一起才行……那个人就是你啦，接下来几天拜托你多多关照，链尉官~"
},
	[5514]={ lines="柴米油盐酱醋茶，琴棋书画诗酒花，再加上一个你，对我来说，就是完美人生啦！", voice="hero_4521_cv_14.prefab", voice1="hero_4521_cv_14.prefab", lines1="柴米油盐酱醋茶，琴棋书画诗酒花，再加上一个你，对我来说，就是完美人生啦！"
},
	[5515]={ lines="喂，我说你什么时候把生辰八字给我？做什么……当然是算姻缘啦，我们都这么亲近了，下一步就是挑良辰吉日、写合婚庚帖，成此好事，然后洞房花烛夜啦~", voice="hero_4521_cv_15.prefab", voice1="hero_4521_cv_15.prefab", lines1="喂，我说你什么时候把生辰八字给我？做什么……当然是算姻缘啦，我们都这么亲近了，下一步就是挑良辰吉日、写合婚庚帖，成此好事，然后洞房花烛夜啦~"
},
	[5516]={ lines="旧年佳兆，新景未央，朝歌暮颂，别时尽欢，日月明兮人曰富昌，舞雩柔兮万事太康，嘿嘿~链尉官，送你一个岁岁顺意，吉吉~利利~", voice="hero_4521_cv_16.prefab", voice1="hero_4521_cv_16.prefab", lines1="旧年佳兆，新景未央，朝歌暮颂，别时尽欢，日月明兮人曰富昌，舞雩柔兮万事太康，嘿嘿~链尉官，送你一个岁岁顺意，吉吉~利利~"
},
	[5517]={ lines="啊，你来啦~忙碌了这么久，可算是能歇歇了。所谓偷得浮生半日闲，想来你应当也会认同我这句话吧，若没什么别的安排的话，今夜……与我一道守岁如何？是属于你我二人的良夜呢~", voice="hero_4521_cv_17.prefab", voice1="hero_4521_cv_17.prefab", lines1="啊，你来啦~忙碌了这么久，可算是能歇歇了。所谓偷得浮生半日闲，想来你应当也会认同我这句话吧，若没什么别的安排的话，今夜……与我一道守岁如何？是属于你我二人的良夜呢~"
},
	[5518]={ lines="咿呀——你这人怎么这样，若是想要温酒，大可拿个炉子来嘛……唉……如此你可就满意了，在你把这些酒喝干净之前，我可什么都做不了了……诶呀你慢点喝啦~", voice="hero_4521_cv_18.prefab", voice1="hero_4521_cv_18.prefab", lines1="咿呀——你这人怎么这样，若是想要温酒，大可拿个炉子来嘛……唉……如此你可就满意了，在你把这些酒喝干净之前，我可什么都做不了了……诶呀你慢点喝啦~"
},
	[5601]={ lines="我已打破虫茧，羽化成蝶。这次，我会站在你的身边，链尉官。", voice="hero_4522_cv_01.prefab", voice1="hero_4522_cv_01.prefab", lines1="我已打破虫茧，羽化成蝶。这次，我会站在你的身边，链尉官。"
},
	[5602]={ lines="系统调试完毕，能源储备充足，闪蝶，准备就绪。", voice="hero_4522_cv_02.prefab", voice1="hero_4522_cv_02.prefab", lines1="系统调试完毕，能源储备充足，闪蝶，准备就绪。"
},
	[5603]={ lines="浮游炮出击，瘫痪他们的武装！", voice="hero_4522_cv_03.prefab", voice1="hero_4522_cv_03.prefab", lines1="浮游炮出击，瘫痪他们的武装！"
},
	[5604]={ lines="消弭在等离子风暴的威光中吧！", voice="hero_4522_cv_04.prefab", voice1="hero_4522_cv_04.prefab", lines1="消弭在等离子风暴的威光中吧！"
},
	[5605]={ lines="破茧，新生，闪蝶于此起舞！", voice="hero_4522_cv_05.prefab", voice1="hero_4522_cv_05.prefab", lines1="破茧，新生，闪蝶于此起舞！"
},
	[5606]={ lines="终、终于结束了……柠檬水柠檬水……", voice="hero_4522_cv_06.prefab", voice1="hero_4522_cv_06.prefab", lines1="终、终于结束了……柠檬水柠檬水……"
},
	[5607]={ lines="早上好，链尉官。要尝尝我新做的点心……呃！不要紧，只是撞到脚了……", voice="hero_4522_cv_07.prefab", voice1="hero_4522_cv_07.prefab", lines1="早上好，链尉官。要尝尝我新做的点心……呃！不要紧，只是撞到脚了……"
},
	[5608]={ lines="早在神光重科时，我就听说莱斯坦斯在源晶武装的研究上有着独树一帜的优势，参与到研究后才发现果然如此。", voice="hero_4522_cv_08.prefab", voice1="hero_4522_cv_08.prefab", lines1="早在神光重科时，我就听说莱斯坦斯在源晶武装的研究上有着独树一帜的优势，参与到研究后才发现果然如此。"
},
	[5609]={ lines="“闪蝶”，它曾是我对未来的寄托，是我那高高在上又不切实际的幻想……嗯，现在的它就叫“扑棱蛾子”，挺好的。", voice="hero_4522_cv_09.prefab", voice1="hero_4522_cv_09.prefab", lines1="“闪蝶”，它曾是我对未来的寄托，是我那高高在上又不切实际的幻想……嗯，现在的它就叫“扑棱蛾子”，挺好的。"
},
	[5610]={ lines="链尉官你一直盯着我看，是我穿错衣服了吗？这是刺玫姐给我推荐的衣服，她说如果我这么穿，你会非常高兴……我、我搞砸了吗？", voice="hero_4522_cv_10.prefab", voice1="hero_4522_cv_10.prefab", lines1="链尉官你一直盯着我看，是我穿错衣服了吗？这是刺玫姐给我推荐的衣服，她说如果我这么穿，你会非常高兴……我、我搞砸了吗？"
},
	[5611]={ lines="呼~啊——通宵一晚上把设备调试好了……呀？！链尉官你、你怎么来了！我、我还没洗脸，让我整理一下！", voice="hero_4522_cv_11.prefab", voice1="hero_4522_cv_11.prefab", lines1="呼~啊——通宵一晚上把设备调试好了……呀？！链尉官你、你怎么来了！我、我还没洗脸，让我整理一下！"
},
	[5612]={ lines="链尉官，可以帮你打扫一下房间吗？不用客气，打扫房间对我而言是很好的整理心情的方法，而且……这样，我就可以光明正大地和你独处了。", voice="hero_4522_cv_12.prefab", voice1="hero_4522_cv_12.prefab", lines1="链尉官，可以帮你打扫一下房间吗？不用客气，打扫房间对我而言是很好的整理心情的方法，而且……这样，我就可以光明正大地和你独处了。"
},
	[5613]={ lines="再过不久，我就要和神光重科谈判了……我的手在抖？是啊，我感觉自己像是又变回了那只缩在虫茧里的毛毛虫，想要逃离……链尉官，我好害怕，你能像上次那样抱住我，给我对抗黑夜的勇气吗？", voice="hero_4522_cv_13.prefab", voice1="hero_4522_cv_13.prefab", lines1="再过不久，我就要和神光重科谈判了……我的手在抖？是啊，我感觉自己像是又变回了那只缩在虫茧里的毛毛虫，想要逃离……链尉官，我好害怕，你能像上次那样抱住我，给我对抗黑夜的勇气吗？"
},
	[5614]={ lines="童话故事里，公主并不一定是被王子所救才能爱上王子，或许是王子本就光彩照人，才会让公主心怀向往。我好像明白我心中这份炽热的憧憬是什么了，链尉官。", voice="hero_4522_cv_14.prefab", voice1="hero_4522_cv_14.prefab", lines1="童话故事里，公主并不一定是被王子所救才能爱上王子，或许是王子本就光彩照人，才会让公主心怀向往。我好像明白我心中这份炽热的憧憬是什么了，链尉官。"
},
	[5615]={ lines="我不懂太多的社交礼仪，但我知道，坦诚是我唯一的武器……我，我爱你，链尉官。从你愿意做那只扑向凶鸟的黑蝴蝶开始，我的心便只属于你一个人了。我愿化作闪蝶，永远停在你的肩头。", voice="hero_4522_cv_15.prefab", voice1="hero_4522_cv_15.prefab", lines1="我不懂太多的社交礼仪，但我知道，坦诚是我唯一的武器……我，我爱你，链尉官。从你愿意做那只扑向凶鸟的黑蝴蝶开始，我的心便只属于你一个人了。我愿化作闪蝶，永远停在你的肩头。"
},
	[5616]={ lines="可以……关上灯吗，链尉官？嗯……窗外的月光会把您的影子拉长，将我完全笼罩进去...我喜欢这种被您覆盖的感觉，很安心。", voice="hero_4522_cv_16.prefab", voice1="hero_4522_cv_16.prefab", lines1="可以……关上灯吗，链尉官？嗯……窗外的月光会把您的影子拉长，将我完全笼罩进去...我喜欢这种被您覆盖的感觉，很安心。"
},
	[5617]={ lines="对着星星许愿会成功吗？唔，其实我的愿望已经实现了，你就在我身边……", voice="hero_4522_cv_17.prefab", voice1="hero_4522_cv_17.prefab", lines1="别、别那么心急嘛……你已经抓到我了，我不会逃跑的……诶？想让我教你怎么解开这个……唔，链尉官真是坏心眼……"
},
	[5618]={ lines="呜……你今天会留下来吗……嗯，你在的话，晚上睡得很香…………", voice="hero_4522_cv_18.prefab", voice1="hero_4522_cv_18.prefab", lines1="呜……链尉官的眼神，好、好可怕，像是要把我整个吞掉一样……没关系的，其实，我有点喜欢这样……只是，能不能温柔一点……别弄疼我了…………"
},
	[5701]={ lines="妾身名唤红叶，乃是虚蚀猎人中的一员，自极北之地前来协助于您——呵呵，可以的话，能让妾身叫您小少爷吗？", voice="hero_4523_cv_01.prefab", voice1="hero_4523_cv_01.prefab", lines1="妾身名唤红叶，乃是虚蚀猎人中的一员，自极北之地前来协助于您——呵呵，可以的话，能让妾身叫您小少爷吗？"
},
	[5702]={ lines="需要妾身斩杀何物？", voice="hero_4523_cv_02.prefab", voice1="hero_4523_cv_02.prefab", lines1="需要妾身斩杀何物？"
},
	[5703]={ lines="扫清诸恶！", voice="hero_4523_cv_03.prefab", voice1="hero_4523_cv_03.prefab", lines1="扫清诸恶！"
},
	[5704]={ lines="彼岸已至！", voice="hero_4523_cv_04.prefab", voice1="hero_4523_cv_04.prefab", lines1="彼岸已至！"
},
	[5705]={ lines="以噬命之咒为引，焚尽此剑作炬——生死妄念，都将归于黄泉！", voice="hero_4523_cv_05.prefab", voice1="hero_4523_cv_05.prefab", lines1="以噬命之咒为引，焚尽此剑作炬——生死妄念，都将归于黄泉！"
},
	[5706]={ lines="万物归终，不过一瞬间而已。", voice="hero_4523_cv_06.prefab", voice1="hero_4523_cv_06.prefab", lines1="万物归终，不过一瞬间而已。"
},
	[5707]={ lines="呵呵，小少爷精气神很是充足，看来今天的工作会很顺利呢。", voice="hero_4523_cv_07.prefab", voice1="hero_4523_cv_07.prefab", lines1="呵呵，小少爷精气神很是充足，看来今天的工作会很顺利呢。"
},
	[5708]={ lines="这世间有人追求永恒，有人贪恋古旧……而妾身，更好那一瞬间的绚烂。", voice="hero_4523_cv_08.prefab", voice1="hero_4523_cv_08.prefab", lines1="这世间有人追求永恒，有人贪恋古旧……而妾身，更好那一瞬间的绚烂。"
},
	[5709]={ lines="妾身所持之剑只斩强盛之敌，定可护您勇往直前，小少爷。", voice="hero_4523_cv_09.prefab", voice1="hero_4523_cv_09.prefab", lines1="妾身所持之剑只斩强盛之敌，定可护您勇往直前，小少爷。"
},
	[5710]={ lines="枫叶红时多离别，但既是与小少爷结识，妾身便开始期待下一次重逢了。", voice="hero_4523_cv_10.prefab", voice1="hero_4523_cv_10.prefab", lines1="枫叶红时多离别，但既是与小少爷结识，妾身便开始期待下一次重逢了。"
},
	[5711]={ lines="妾身虽被诅咒缠身，如今也已习惯如常，小少爷，请不必因此而对妾身感到忌惮。", voice="hero_4523_cv_11.prefab", voice1="hero_4523_cv_11.prefab", lines1="妾身虽被诅咒缠身，如今也已习惯如常，小少爷，请不必因此而对妾身感到忌惮。"
},
	[5712]={ lines="盛极之时方为绝景，亦如烟花爆裂而上，枫火点亮天边——现在的小少爷，就如同那般美丽。", voice="hero_4523_cv_12.prefab", voice1="hero_4523_cv_12.prefab", lines1="盛极之时方为绝景，亦如烟花爆裂而上，枫火点亮天边——现在的小少爷，就如同那般美丽。"
},
	[5713]={ lines="妾身幼时，最喜听雨打枫叶的声音……现在？现在更偏爱小少爷打着伞，与妾身共赏枫叶时的耳边话语。", voice="hero_4523_cv_13.prefab", voice1="hero_4523_cv_13.prefab", lines1="妾身幼时，最喜听雨打枫叶的声音……现在？现在更偏爱小少爷打着伞，与妾身共赏枫叶时的耳边话语。"
},
	[5714]={ lines="若这腐蚀的诅咒能暂停须臾该有多好，妾身便可用此段光阴与小少爷相伴，哪怕代价是余生的所有时间，妾身也心甘情愿……", voice="hero_4523_cv_14.prefab", voice1="hero_4523_cv_14.prefab", lines1="若这腐蚀的诅咒能暂停须臾该有多好，妾身便可用此段光阴与小少爷相伴，哪怕代价是余生的所有时间，妾身也心甘情愿……"
},
	[5715]={ lines="有人告诉妾身，生命燃烧至盛时固然美丽，凋零后的孤独却寒冷至极——妾身如今才懂这番话的意义……从今往后，无论幸或不幸，妾身定会与小少爷一起，直面诅咒带来的所有命运。", voice="hero_4523_cv_15.prefab", voice1="hero_4523_cv_15.prefab", lines1="有人告诉妾身，生命燃烧至盛时固然美丽，凋零后的孤独却寒冷至极——妾身如今才懂这番话的意义……从今往后，无论幸或不幸，妾身定会与小少爷一起，直面诅咒带来的所有命运。"
},
	[5716]={ lines="小少爷？您来此处，是想和妾身一同赏樱吗？", voice="", voice1="hero_4523_cv_16.prefab", lines1="小少爷？您来此处，是想和妾身一同赏樱吗？还是说，您和妾身一样，有些寂寞了？"
},
	[5717]={ lines="既然是小少爷的要求，妾身又怎会拒绝呢……此处别无他人，小少爷，再多与妾身亲近一些吧……", voice="", voice1="hero_4523_cv_17.prefab", lines1="既然是小少爷的要求，妾身又怎会拒绝呢……此处别无他人，小少爷，再多与妾身亲近一些吧……"
},
	[5718]={ lines="啾……不知妾身心中的那份炽热，是否都传递给小少爷了呢……呵呵呵……", voice="", voice1="hero_4523_cv_18.prefab", lines1="啾……不知妾身心中的那份炽热，是否都传递给小少爷了呢……"
},
	[5719]={ lines="小少爷要坐过来吗？妾身心里有好多话想要告诉您呢……", voice="", voice1="hero_4523_cv_19.prefab", lines1="小少爷要坐过来吗?妾身心里有好多话想要告诉您呢…"
},
	[5720]={ lines="……小少爷新学了魔术吗？妾身很是期待。", voice="", voice1="hero_4523_cv_20.prefab", lines1="啊嗯……！这是……小少爷新学的魔术吗？呵呵，若是这样能让您开心的话……"
},
	[5721]={ lines="嗯……您这样看着妾身……妾身都有些不好意思了。", voice="", voice1="hero_4523_cv_21.prefab", lines1="嗯……您这样用力的话……会撒出来的……等结束了，您可要好好帮妾身擦干净哦……？"
},
	[5722]={ lines="小少爷，妾身等候您多时了呢~", voice="", voice1="hero_4523_cv_1001.prefab", lines1="……，小少爷，妾身等候您多时了呢~"
},
	[5723]={ lines="嗯……小少爷的想法，妾身已经知晓，那么……呵呵，有感受到妾身的心跳吗？", voice="", voice1="hero_4523_cv_1002.prefab", lines1="嗯……小少爷的想法，妾身已经知晓，那么……呵呵，有感受到妾身的心跳吗？"
},
	[5724]={ lines="小少爷，请再靠近妾身一些……啾……小少爷的味道，妾身记住了~", voice="", voice1="hero_4523_cv_1003.prefab", lines1="小少爷，请再靠近妾身一些……啾……小少爷的味道，妾身记住了~"
},
	[5725]={ lines="呵呵，看入迷了吗？……呜！您有些心急呢……没关系，妾身也是如此……", voice="", voice1="hero_4523_cv_1004.prefab", lines1="呵呵，看入迷了吗？……呜！您有些心急呢……没关系，妾身也是如此……"
},
	[5801]={ lines="灰暗之世仅有的绚然，以珂芙尼尔之名点亮第一束光，链尉官，吾已做好准备，将与汝共同卫护这人世。来，订下契约吧~", voice="hero_4524_cv_01.prefab", voice1="hero_4524_cv_01.prefab", lines1="灰暗之世仅有的绚然，以珂芙尼尔之名点亮第一束光，链尉官，吾已做好准备，将与汝共同卫护这人世。来，订下契约吧~"
},
	[5802]={ lines="珂芙尼尔会听从汝每一个指令。", voice="hero_4524_cv_02.prefab", voice1="hero_4524_cv_02.prefab", lines1="珂芙尼尔会听从汝每一个指令。"
},
	[5803]={ lines="当心灵魂被烧掉哦~", voice="hero_4524_cv_03.prefab", voice1="hero_4524_cv_03.prefab", lines1="当心灵魂被烧掉哦~"
},
	[5804]={ lines="见过魔法的光辉吗？", voice="hero_4524_cv_04.prefab", voice1="hero_4524_cv_04.prefab", lines1="见过魔法的光辉吗？"
},
	[5805]={ lines="吾将以真名颂唱，为汝等带来命运的终局。", voice="hero_4524_cv_05.prefab", voice1="hero_4524_cv_05.prefab", lines1="吾将以真名颂唱，为汝等带来命运的终局。"
},
	[5806]={ lines="汝之英姿将与珂芙尼尔之名一起被世人所颂唱~", voice="hero_4524_cv_06.prefab", voice1="hero_4524_cv_06.prefab", lines1="汝之英姿将与珂芙尼尔之名一起被世人所颂唱~"
},
	[5807]={ lines="珂芙尼尔早已静候多时，期待汝之教诲。", voice="hero_4524_cv_07.prefab", voice1="hero_4524_cv_07.prefab", lines1="珂芙尼尔早已静候多时，期待汝之教诲。"
},
	[5808]={ lines="在外人面前，我只是一名普通的学生……但你和他们都不一样，珂芙尼尔从不介意告知你她全部的秘密。", voice="hero_4524_cv_08.prefab", voice1="hero_4524_cv_08.prefab", lines1="在外人面前，我只是一名普通的学生……但你和他们都不一样，珂芙尼尔从不介意告知你她全部的秘密。"
},
	[5809]={ lines="宝石不仅是收藏品，更是某些情绪的寄托……就像是这个，寄托着我赤忱的热爱，我想要把它送给你，你会愿意收下吗？", voice="hero_4524_cv_09.prefab", voice1="hero_4524_cv_09.prefab", lines1="宝石不仅是收藏品，更是某些情绪的寄托……就像是这个，寄托着我赤忱的热爱，我想要把它送给你，你会愿意收下吗？"
},
	[5810]={ lines="吾看到了……关于世界的秘密，万物的真相，哦呵呵呵……吾之契约者，快走上前来，吾有话要讲。", voice="hero_4524_cv_10.prefab", voice1="hero_4524_cv_10.prefab", lines1="吾看到了……关于世界的秘密，万物的真相，哦呵呵呵……吾之契约者，快走上前来，吾有话要讲。"
},
	[5811]={ lines="汝有听到吗？魔力正在吾的身体里涌动，伸出手来，尝试着安抚它和引导它吧~", voice="hero_4524_cv_11.prefab", voice1="hero_4524_cv_11.prefab", lines1="汝有听到吗？魔力正在吾的身体里涌动，伸出手来，尝试着安抚它和引导它吧~"
},
	[5812]={ lines="被命运选中的人当然会有自身的特别之处，吾即是如此……所以，吾有一位像是汝这样强大的契约者，也就理所应当了。", voice="hero_4524_cv_12.prefab", voice1="hero_4524_cv_12.prefab", lines1="被命运选中的人当然会有自身的特别之处，吾即是如此……所以，吾有一位像是汝这样强大的契约者，也就理所应当了。"
},
	[5813]={ lines="善良、坚韧、勇敢、守护……吾会一直用这些品德砥砺自我，在这期间，吾希望汝可以一直看着吾，直到吾变成汝心中期待的样子。", voice="hero_4524_cv_13.prefab", voice1="hero_4524_cv_13.prefab", lines1="善良、坚韧、勇敢、守护……吾会一直用这些品德砥砺自我，在这期间，吾希望汝可以一直看着吾，直到吾变成汝心中期待的样子。"
},
	[5814]={ lines="吾来此是因为命运的指引，但与汝的相遇、相知，以及彼此订下的契约，比起命运的恩赐，吾更认为那是出于吾的本愿。", voice="hero_4524_cv_14.prefab", voice1="hero_4524_cv_14.prefab", lines1="吾来此是因为命运的指引，但与汝的相遇、相知，以及彼此订下的契约，比起命运的恩赐，吾更认为那是出于吾的本愿。"
},
	[5815]={ lines="以珂芙尼尔的名义，吾向汝发出邀请，汝之真名将与吾一同记录于《珂尼史诗》，自此，吾与汝的灵魂永久相依，再无分离……链尉官，汝愿意答应吗？", voice="hero_4524_cv_15.prefab", voice1="hero_4524_cv_15.prefab", lines1="以珂芙尼尔的名义，吾向汝发出邀请，汝之真名将与吾一同记录于《珂尼史诗》，自此，吾与汝的灵魂永久相依，再无分离……链尉官，汝愿意答应吗？"
},
	[5816]={ lines="链尉官，拉紧吾的手，在这趟旅程的终点，汝会看到足以篆刻入生命的、吾用爱编织出来的奇迹……！", voice="", voice1="hero_4524_cv_16.prefab", lines1="链尉官，拉紧吾的手，在这趟旅程的终点，汝会看到足以篆刻入生命的、吾用爱编织出来的奇迹……！"
},
	[5817]={ lines="链尉官，汝的双手可以抱吾更紧一些……吾带你去赏看这个世界……", voice="", voice1="hero_4524_cv_17.prefab", lines1="链尉官，汝的双手可以抱吾更紧一些……唔……你、你在摸哪里……！等，等等，会掉下去的啦……!"
},
	[5818]={ lines="将指针拨到十二点，让时间就此停歇，这样汝便可以静听吾的心跳，直到世界尽头的钟声再度响起……", voice="", voice1="hero_4524_cv_18.prefab", lines1="将指针拨到十二点，让时间就此停歇，这样汝便可以静听吾的心跳，直到世界尽头的钟声再度响起……"
},
	[5819]={ lines="……哎呀！汝玩球小心一点……倒也不疼啦，只是汝总该做点补偿吧……（害羞）", voice="", voice1="hero_4524_cv_19.prefab", lines1="……哎呀！呜，胸口都红了……倒也不疼啦，只是汝总该做点补偿吧，比如帮吾揉一下……"
},
	[5820]={ lines="嗨，吾之契约者，要与吾在海中来一场竞赛吗？", voice="", voice1="hero_4524_cv_20.prefab", lines1="嗨，吾之契约者，唔——？！汝……是不是都看到了？真是，快点想想办法啦……！"
},
	[5821]={ lines="啊——（舒服地伸懒腰），如此美妙的阳光和海风，真是绝佳享受哪~亲爱的链尉官，汝愿意与吾共同享受这一刻吗？", voice="", voice1="hero_4524_cv_21.prefab", lines1="啊——如此美妙的阳光和海风，真是绝佳享受哪~亲爱的链尉官，汝愿意与吾共同享受这一刻吗？"
},
	[5901]={ lines="你为我打开了无形的翅膀，我无以答谢，在到达你所在的那片碧空前，我将永不止步，链尉官。", voice="hero_4525_cv_01.prefab", voice1="hero_4525_cv_01.prefab", lines1="你为我打开了无形的翅膀，我无以答谢，在到达你所在的那片碧空前，我将永不止步，链尉官。"
},
	[5902]={ lines="风送来了硝烟的味道，我已准备就绪。", voice="hero_4525_cv_02.prefab", voice1="hero_4525_cv_02.prefab", lines1="风送来了硝烟的味道，我已准备就绪。"
},
	[5903]={ lines="看得清我的剑影吗？", voice="hero_4525_cv_03.prefab", voice1="hero_4525_cv_03.prefab", lines1="看得清我的剑影吗？"
},
	[5904]={ lines="狂风呼啸！", voice="hero_4525_cv_04.prefab", voice1="hero_4525_cv_04.prefab", lines1="狂风呼啸！"
},
	[5905]={ lines="在这缥缈的幻影下，随风而逝吧！", voice="hero_4525_cv_05.prefab", voice1="hero_4525_cv_05.prefab", lines1="在这缥缈的幻影下，随风而逝吧！"
},
	[5906]={ lines="我听到了，风已将他们的声音埋葬。", voice="hero_4525_cv_06.prefab", voice1="hero_4525_cv_06.prefab", lines1="我听到了，风已将他们的声音埋葬。"
},
	[5907]={ lines="微风送来了你的脚步声，链尉官。", voice="hero_4525_cv_07.prefab", voice1="hero_4525_cv_07.prefab", lines1="微风送来了你的脚步声，链尉官。"
},
	[5908]={ lines="体能3小时，仪态3小时，还有贯穿全程的心理训练……克洛瓦德仪仗兵的一天，几乎都是这样度过的。", voice="hero_4525_cv_08.prefab", voice1="hero_4525_cv_08.prefab", lines1="体能3小时，仪态3小时，还有贯穿全程的心理训练……克洛瓦德仪仗兵的一天，几乎都是这样度过的。"
},
	[5909]={ lines="一杯好的红茶，便是克洛瓦德上流社会的通行证，而这一杯，是我专门为你冲泡的，小心烫。", voice="hero_4525_cv_09.prefab", voice1="hero_4525_cv_09.prefab", lines1="一杯好的红茶，便是克洛瓦德上流社会的通行证，而这一杯，是我专门为你冲泡的，小心烫。"
},
	[5910]={ lines="如果这样做的话，会不会……唔！力道控制得还是不够精准么……", voice="hero_4525_cv_10.prefab", voice1="hero_4525_cv_10.prefab", lines1="如果这样做的话，会不会……唔！力道控制得还是不够精准么……"
},
	[5911]={ lines="早安，链尉官，没想到您的晨练时间也这么早，要不下次我们一起吧？我可以帮您准备红茶和毛巾，训练完还可以一起吃早饭，您意下如何？", voice="hero_4525_cv_11.prefab", voice1="hero_4525_cv_11.prefab", lines1="早安，链尉官，没想到您的晨练时间也这么早，要不下次我们一起吧？我可以帮您准备红茶和毛巾，训练完还可以一起吃早饭，您意下如何？"
},
	[5912]={ lines="链尉官，下次我站岗的时候可以别对我做鬼脸吗？我要是笑出来的话，仪仗队是会扣工资的……如果你想看，我可以单独笑给你看。", voice="hero_4525_cv_12.prefab", voice1="hero_4525_cv_12.prefab", lines1="链尉官，下次我站岗的时候可以别对我做鬼脸吗？我要是笑出来的话，仪仗队是会扣工资的……如果你想看，我可以单独笑给你看。"
},
	[5913]={ lines="克洛瓦德外面的世界如此之大、如此之精彩，那是蜷缩在宅邸中的我无法想象的景色……而现在，我只要踮起脚尖，天空下的一切都近在咫尺。链尉官，我该如何回报你，回报这份馈赠？", voice="hero_4525_cv_13.prefab", voice1="hero_4525_cv_13.prefab", lines1="克洛瓦德外面的世界如此之大、如此之精彩，那是蜷缩在宅邸中的我无法想象的景色……而现在，我只要踮起脚尖，天空下的一切都近在咫尺。链尉官，我该如何回报你，回报这份馈赠？"
},
	[5914]={ lines="我不止一次回想，如果不是那个猩甜的吻，恐怕我早已死在了工厂的地下。链尉官，我已伸展翅膀，正向着你所在的彼方竭力飞翔，等我到达了你的身边，可以听我讲述这一路的旅途吗？", voice="hero_4525_cv_14.prefab", voice1="hero_4525_cv_14.prefab", lines1="我不止一次回想，如果不是那个猩甜的吻，恐怕我早已死在了工厂的地下。链尉官，我已伸展翅膀，正向着你所在的彼方竭力飞翔，等我到达了你的身边，可以听我讲述这一路的旅途吗？"
},
	[5915]={ lines="即便是在最猛烈的暴风雨中，只要想到你的面庞，思绪便会化作力量充盈我的全身，让我有勇气迎着风浪扑打翅膀……现在我来到了你的身边，胸口这份未名的悸动……终于有了结果。", voice="hero_4525_cv_15.prefab", voice1="hero_4525_cv_15.prefab", lines1="即便是在最猛烈的暴风雨中，只要想到你的面庞，思绪便会化作力量充盈我的全身，让我有勇气迎着风浪扑打翅膀……现在我来到了你的身边，胸口这份未名的悸动……终于有了结果。"
},
	[5916]={ lines="海风为我送来了你的气味，让我明白你一直在我身边，链尉官。只要能与你一同仰望天空，我就心满意足了。", voice="", voice1="hero_4525_cv_16.prefab", lines1="海风为我送来了你的气味，让我明白你一直在我身边，链尉官。只要能与你一同仰望天空，我就心满意足了。"
},
	[5917]={ lines="来一起拍个照片……唔，这样笑怎么样……对不起链尉官让你见笑了……", voice="", voice1="hero_4525_cv_17.prefab", lines1="来一起拍个照片……诶，泳衣怎么掉下来……对不起链尉官，让你见笑了……诶？你怎么……抓着我的手……"
},
	[5918]={ lines="要……要现在就开始比一局吗……链尉官比之前……更强硬了呢……好，我准备好了……我不会输的……", voice="", voice1="hero_4525_cv_18.prefab", lines1="要……要从这边开始吗……链尉官比之前……更强硬了呢……好，我准备好了……无论什么样的链尉官，我都很期待……"
},
	[6001]={ lines="如今获得重生的我，终于能和哥哥一起见识更多美丽的风景了……不过在那之前，就让我来保护哥哥吧。", voice="hero_4526_cv_01.prefab", voice1="hero_4526_cv_01.prefab", lines1="如今获得重生的我，终于能和哥哥一起见识更多美丽的风景了……不过在那之前，就让我来保护哥哥吧。"
},
	[6002]={ lines="支援的任务请交给我吧！", voice="hero_4526_cv_02.prefab", voice1="hero_4526_cv_02.prefab", lines1="支援的任务请交给我吧！"
},
	[6003]={ lines="棱晶，击退恶敌！", voice="hero_4526_cv_03.prefab", voice1="hero_4526_cv_03.prefab", lines1="棱晶，击退恶敌！"
},
	[6004]={ lines="光羽，降下惩罚！", voice="hero_4526_cv_04.prefab", voice1="hero_4526_cv_04.prefab", lines1="光羽，降下惩罚！"
},
	[6005]={ lines="我会和哥哥一起，打破命运的轮回！", voice="hero_4526_cv_05.prefab", voice1="hero_4526_cv_05.prefab", lines1="我会和哥哥一起，打破命运的轮回！"
},
	[6006]={ lines="我们会一直向前走的，哥哥。", voice="hero_4526_cv_06.prefab", voice1="hero_4526_cv_06.prefab", lines1="我们会一直向前走的，哥哥。"
},
	[6007]={ lines="哥哥还在工作吗？要是累了不要勉强，要马上跟我说哦？嗯，我会给哥哥加油的！", voice="hero_4526_cv_07.prefab", voice1="hero_4526_cv_07.prefab", lines1="哥哥还在工作吗？要是累了不要勉强，要马上跟我说哦？嗯，我会给哥哥加油的！"
},
	[6008]={ lines="这是我第一次辅助哥哥工作……我一定会努力，不让哥哥失望的。", voice="hero_4526_cv_08.prefab", voice1="hero_4526_cv_08.prefab", lines1="这是我第一次辅助哥哥工作……我一定会努力，不让哥哥失望的。"
},
	[6009]={ lines="哥哥如果有什么烦恼的话，都可以跟我说哦？看到你烦恼，我也会不开心……", voice="hero_4526_cv_09.prefab", voice1="hero_4526_cv_09.prefab", lines1="哥哥如果有什么烦恼的话，都可以跟我说哦？看到你烦恼，我也会不开心……"
},
	[6010]={ lines="因为哥哥，我获得了新的人生……我和哥哥连接的金色丝线，永远都不会断开。", voice="hero_4526_cv_10.prefab", voice1="hero_4526_cv_10.prefab", lines1="因为哥哥，我获得了新的人生……我和哥哥连接的金色丝线，永远都不会断开。"
},
	[6011]={ lines="离开星都以后我才发现世界原来这么大，我想要去看到更多的风景……可以和我一起吗，哥哥？", voice="hero_4526_cv_11.prefab", voice1="hero_4526_cv_11.prefab", lines1="离开星都以后我才发现世界原来这么大，我想要去看到更多的风景……可以和我一起吗，哥哥？"
},
	[6012]={ lines="安全局的姐姐们教会了我很多知识，还有一些和哥哥也有关呢——想知道是什么？嘻嘻，保密~", voice="hero_4526_cv_12.prefab", voice1="hero_4526_cv_12.prefab", lines1="安全局的姐姐们教会了我很多知识，还有一些和哥哥也有关呢——想知道是什么？嘻嘻，保密~"
},
	[6013]={ lines="我现在真的很幸福哦，不仅能看到星都之外的景色，更重要的是，哥哥也会一直在我身边……这些幸福的瞬间都是哥哥带给我的——（亲吻）嗯，我也最喜欢哥哥了。", voice="hero_4526_cv_13.prefab", voice1="hero_4526_cv_13.prefab", lines1="我现在真的很幸福哦，不仅能看到星都之外的景色，更重要的是，哥哥也会一直在我身边……这些幸福的瞬间都是哥哥带给我的——（亲吻）嗯，我也最喜欢哥哥了。"
},
	[6014]={ lines="明明是想让哥哥越来越依赖我的，结果反而我自己深陷其中了……不过，这也是理所当然的事吧？毕竟我和哥哥的身体里流着一样的血，是名义上的“亲人”呢——妹妹依赖哥哥，也很合理吧？", voice="hero_4526_cv_14.prefab", voice1="hero_4526_cv_14.prefab", lines1="明明是想让哥哥越来越依赖我的，结果反而我自己深陷其中了……不过，这也是理所当然的事吧？毕竟我和哥哥的身体里流着一样的血，是名义上的“亲人”呢——妹妹依赖哥哥，也很合理吧？"
},
	[6015]={ lines="——我知道你心里想的是什么哦，哥哥。我们的关系早就不是生死能丈量的了，关于我，关于泽菲琳的一切，从发梢到指尖，早就全都是哥哥的了……", voice="hero_4526_cv_15.prefab", voice1="hero_4526_cv_15.prefab", lines1="——我知道你心里想的是什么哦，哥哥。我们的关系早就不是生死能丈量的了，关于我，关于泽菲琳的一切，从发梢到指尖，早就全都是哥哥的了……"
},
	[6016]={ lines="这件衣服是悄悄给哥哥准备的惊喜哦，哥哥喜欢吗？——嘻嘻，身为妹妹，我也不能输给其他姐姐们呢。", voice="hero_4526_cv_16.prefab", voice1="hero_4526_cv_16.prefab", lines1="这件衣服是悄悄给哥哥准备的惊喜哦，哥哥喜欢吗？——嘻嘻，身为妹妹，我也不能输给其他姐姐们呢。"
},
	[6017]={ lines="只要是哥哥喜欢的，我都不讨厌的……", voice="hero_4526_cv_17.prefab", voice1="hero_4526_cv_17.prefab", lines1="原来哥哥喜欢这里啊……嗯……！没，没关系，只要是哥哥喜欢的，我都不讨厌……"
},
	[6018]={ lines="水沾在皮肤上，感觉有些凉凉的……哥哥可以帮我擦干净吗？", voice="hero_4526_cv_18.prefab", voice1="hero_4526_cv_18.prefab", lines1="水沾在皮肤上，感觉有些凉凉的……哥哥可以帮我擦干净吗？嗯，从哪开始都行……"
},
	[6019]={ lines="节日快乐哦，哥哥，今晚，是一年的最后一天了呢~", voice="hero_4526_cv_19.prefab", voice1="hero_4526_cv_19.prefab", lines1="节日快乐哦，哥哥，今晚，只属于你和我呢……嘻嘻……"
},
	[6020]={ lines="我喜欢和哥哥呆在一起的时光，很开心，很温暖。", voice="hero_4526_cv_20.prefab", voice1="hero_4526_cv_20.prefab", lines1="很喜欢哥哥的温度……这样的话……我也想要向哥哥展现更多……"
},
	[6021]={ lines="如此好的风光，哥哥要和我再靠近一点吗……我有些话想悄悄告诉你……", voice="hero_4526_cv_21.prefab", voice1="hero_4526_cv_21.prefab", lines1="如此好的风光，哥哥可以再靠近我一些吗……我有些话想悄悄告诉你……"
},
	[6101]={ lines="链尉官，我的长官，我是莱斯坦斯新任战员，瞳光，向您报道……嗯，我如约来到了你的身边，为了能够与你一起创造新的回忆。", voice="hero_4527_cv_01.prefab", voice1="hero_4527_cv_01.prefab", lines1="链尉官，我的长官，我是莱斯坦斯新任战员，瞳光，向您报道……嗯，我如约来到了你的身边，为了能够与你一起创造新的回忆。"
},
	[6102]={ lines="我期待这一天很久了。", voice="hero_4527_cv_02.prefab", voice1="hero_4527_cv_02.prefab", lines1="我期待这一天很久了。"
},
	[6103]={ lines="记录、摹刻、印象写入——", voice="hero_4527_cv_03.prefab", voice1="hero_4527_cv_03.prefab", lines1="记录、摹刻、印象写入——"
},
	[6104]={ lines="解构、重塑、瞬间定格——", voice="hero_4527_cv_04.prefab", voice1="hero_4527_cv_04.prefab", lines1="解构、重塑、瞬间定格——"
},
	[6105]={ lines="在刹那千万的光影中，我窥见了真实的自己。", voice="hero_4527_cv_05.prefab", voice1="hero_4527_cv_05.prefab", lines1="在刹那千万的光影中，我窥见了真实的自己。"
},
	[6106]={ lines="又一次与你一起，创造了奇迹。", voice="hero_4527_cv_06.prefab", voice1="hero_4527_cv_06.prefab", lines1="又一次与你一起，创造了奇迹。"
},
	[6107]={ lines="我还没见过你认真工作的样子呢~我可以拍下来吗？", voice="hero_4527_cv_07.prefab", voice1="hero_4527_cv_07.prefab", lines1="我还没见过你认真工作的样子呢~我可以拍下来吗？"
},
	[6108]={ lines="每到一个新的地方，我都会想要拍下周围的景致，尤其是这里，充满你生活气息的地方，想到这儿，我就马上按下了快门……", voice="hero_4527_cv_08.prefab", voice1="hero_4527_cv_08.prefab", lines1="每到一个新的地方，我都会想要拍下周围的景致，尤其是这里，充满你生活气息的地方，想到这儿，我就马上按下了快门……"
},
	[6109]={ lines="我一直认为，人活着的意义就是为了和美好的一切相遇。看着你，我忍不住又想起了这句话……", voice="hero_4527_cv_09.prefab", voice1="hero_4527_cv_09.prefab", lines1="我一直认为，人活着的意义就是为了和美好的一切相遇。看着你，我忍不住又想起了这句话……"
},
	[6110]={ lines="相片可以记录下许多转瞬即逝的美好，纸质的相簿又为这份美好增添了一些拿在手中的实感，链尉官，你要一起看吗？", voice="hero_4527_cv_10.prefab", voice1="hero_4527_cv_10.prefab", lines1="相片可以记录下许多转瞬即逝的美好，纸质的相簿又为这份美好增添了一些拿在手中的实感，链尉官，你要一起看吗？"
},
	[6111]={ lines="理解并承认自己的固执，然后接纳它所带来的一切结果，我早已重新审视自己，并会背负着过去的一切，继续往前。", voice="hero_4527_cv_11.prefab", voice1="hero_4527_cv_11.prefab", lines1="理解并承认自己的固执，然后接纳它所带来的一切结果，我早已重新审视自己，并会背负着过去的一切，继续往前。"
},
	[6112]={ lines="所有的相遇都弥足珍贵，而我会用手中的相机记录下每一个重要的瞬间，这样，无论何时何地，我们都能重新看到那一刻的惊喜与悸动……", voice="hero_4527_cv_12.prefab", voice1="hero_4527_cv_12.prefab", lines1="所有的相遇都弥足珍贵，而我会用手中的相机记录下每一个重要的瞬间，这样，无论何时何地，我们都能重新看到那一刻的惊喜与悸动……"
},
	[6113]={ lines="对未来的规划吗？其实和以前没什么变化，我还是会像过去一样，按部就班地生活吧，非要说变化的话，可能就是多了你这么一个可以无话不谈的人？", voice="hero_4527_cv_13.prefab", voice1="hero_4527_cv_13.prefab", lines1="对未来的规划吗？其实和以前没什么变化，我还是会像过去一样，按部就班地生活吧，非要说变化的话，可能就是多了你这么一个可以无话不谈的人？"
},
	[6114]={ lines="我曾经孑然一身，以为未来一片灰暗，但你的出现照亮了它，如今我已不再踌躇，你愿意让我陪在你身边，与你一起经历人生的苦乐忧喜吗？", voice="hero_4527_cv_14.prefab", voice1="hero_4527_cv_14.prefab", lines1="我曾经孑然一身，以为未来一片灰暗，但你的出现照亮了它，如今我已不再踌躇，你愿意让我陪在你身边，与你一起经历人生的苦乐忧喜吗？"
},
	[6115]={ lines="即使只是看着你的照片，心跳都会忍不住地加速，这是我从来没有体会过的心动，我想要让它得到答案，所以我做出了这个大胆的决定……", voice="hero_4527_cv_15.prefab", voice1="hero_4527_cv_15.prefab", lines1="即使只是看着你的照片，心跳都会忍不住地加速，这是我从来没有体会过的心动，我想要让它得到答案，所以我做出了这个大胆的决定……"
},
	[6116]={ lines="是你，我的……支配者，你会为我带来怎样的命运呢……我当然有所期待，因为是你啊……", voice="", voice1="hero_4527_cv_16.prefab", lines1="是你，我的……支配者，你会为我带来怎样的命运呢……我当然有所期待，因为是你啊……"
},
	[6117]={ lines="……", voice="", voice1="hero_4527_cv_17_1.prefab", lines1="……"
},
	[6118]={ lines="……！", voice="", voice1="hero_4527_cv_17_2.prefab", lines1="……！"
},
	[6119]={ lines="……嗯……从来没有试过的游戏，很期待的角色扮演呀……", voice="", voice1="hero_4527_cv_17_3.prefab", lines1="……嗯……你这样……我没办法招……呜……"
},
	[6120]={ lines="唔……你是一位好的演员，亲爱的链尉官~", voice="", voice1="hero_4527_cv_18.prefab", lines1="唔……有点痛……但是不讨厌……"
},
	[6201]={ lines="高奈莉娅·冯·霍亨索伦，前来履行对你的承诺了，链尉官。迷雾之国的白蔷薇，将只为你一人绽放！", voice="hero_4528_cv_01.prefab", voice1="hero_4528_cv_01.prefab", lines1="高奈莉娅·冯·霍亨索伦，前来履行对你的承诺了，链尉官。迷雾之国的白蔷薇，将只为你一人绽放！"
},
	[6202]={ lines="于我麾下集结！", voice="hero_4528_cv_02.prefab", voice1="hero_4528_cv_02.prefab", lines1="于我麾下集结！"
},
	[6203]={ lines="我意已决！", voice="hero_4528_cv_03.prefab", voice1="hero_4528_cv_03.prefab", lines1="我意已决！"
},
	[6204]={ lines="灭亡，绽放！", voice="hero_4528_cv_04.prefab", voice1="hero_4528_cv_04.prefab", lines1="灭亡，绽放！"
},
	[6205]={ lines="在次元的彼岸，归于湮灭吧！", voice="hero_4528_cv_05.prefab", voice1="hero_4528_cv_05.prefab", lines1="在次元的彼岸，归于湮灭吧！"
},
	[6206]={ lines="你将消逝在历史的尘埃中，不复存在！", voice="hero_4528_cv_06.prefab", voice1="hero_4528_cv_06.prefab", lines1="你将消逝在历史的尘埃中，不复存在！"
},
	[6207]={ lines="嘿！猜猜我是谁？我先说下，可不许猜中。", voice="hero_4528_cv_07.prefab", voice1="hero_4528_cv_07.prefab", lines1="嘿！猜猜我是谁？我先说下，可不许猜中。"
},
	[6208]={ lines="来支舞吧，链尉官。将你的高傲、从容与强大，一并展现给我看吧。", voice="hero_4528_cv_08.prefab", voice1="hero_4528_cv_08.prefab", lines1="来支舞吧，链尉官。将你的高傲、从容与强大，一并展现给我看吧。"
},
	[6209]={ lines="链尉官，帮我看看衣服上有开线的地方吗？看仔细点哦，特别是……这里，呵呵。", voice="hero_4528_cv_09.prefab", voice1="hero_4528_cv_09.prefab", lines1="链尉官，帮我看看衣服上有开线的地方吗？看仔细点哦，特别是……这里，呵呵。"
},
	[6210]={ lines="比一下枪法吧，链尉官。我有自信，我不会输给你。", voice="hero_4528_cv_10.prefab", voice1="hero_4528_cv_10.prefab", lines1="比一下枪法吧，链尉官。我有自信，我不会输给你。"
},
	[6211]={ lines="皇女的日常？你想知道的是例行的文件审批和公务出席呢，还是……对自己心上人日渐加深的思念呢，链·尉·官·？", voice="hero_4528_cv_11.prefab", voice1="hero_4528_cv_11.prefab", lines1="皇女的日常？你想知道的是例行的文件审批和公务出席呢，还是……对自己心上人日渐加深的思念呢，链·尉·官·？"
},
	[6212]={ lines="诶？！链尉官你什么时候来的……嗯，刚刚完成一件好作品。我现在正好穿着它，猜猜是哪件？猜中的话……我就把它送给你！", voice="hero_4528_cv_12.prefab", voice1="hero_4528_cv_12.prefab", lines1="诶？！链尉官你什么时候来的……嗯，刚刚完成一件好作品。我现在正好穿着它，猜猜是哪件？猜中的话……我就把它送给你！"
},
	[6213]={ lines="我的理想是在我真正即位的那天，把所有和皇族相关的东西全都扔掉，隐姓埋名来黎苏根做服装店老板，或者……做你专属的服装设计师，怎么样？", voice="hero_4528_cv_13.prefab", voice1="hero_4528_cv_13.prefab", lines1="我的理想是在我真正即位的那天，把所有和皇族相关的东西全都扔掉，隐姓埋名来黎苏根做服装店老板，或者……做你专属的服装设计师，怎么样？"
},
	[6214]={ lines="遇见你之后，“白蔷薇”才算从这副救国皇女的躯壳中觉醒。这是我第一次诞生了对某个人的向往，这念头，让我几度着魔……我该如何才能靠近你，我该怎样才能拥有你？", voice="hero_4528_cv_14.prefab", voice1="hero_4528_cv_14.prefab", lines1="遇见你之后，“白蔷薇”才算从这副救国皇女的躯壳中觉醒。这是我第一次诞生了对某个人的向往，这念头，让我几度着魔……我该如何才能靠近你，我该怎样才能拥有你？"
},
	[6215]={ lines="我跨越尸山血海，舍弃一切世俗的枷锁，终于来到了你的身边，链尉官。啊……胸口的这团烈火几乎将我吞噬，这都是你的错，你可要好好的……补偿我……", voice="hero_4528_cv_15.prefab", voice1="hero_4528_cv_15.prefab", lines1="我跨越尸山血海，舍弃一切世俗的枷锁，终于来到了你的身边，链尉官。啊……胸口的这团烈火几乎将我吞噬，这都是你的错，你可要好好的……补偿我……"
},
	[6216]={ lines="动动眼睛，链尉官，别光看这一个地方……", voice="", voice1="hero_4528_cv_16.prefab", lines1="动动眼睛，帅哥，别光看这一个地方……别浪费你所拥有的……我的一切。"
},
	[6217]={ lines="你要做什……哎呀……唔，真是坏心眼，快把我的东西还回来~", voice="", voice1="hero_4528_cv_17.prefab", lines1="你要做什……哎呀……唔，真是坏心眼。快把它给我……我想要了……"
},
	[6218]={ lines="对，就是这样。你的手，挠得我痒痒的……", voice="", voice1="hero_4528_cv_18.prefab", lines1="啊……对，就是这样。蹂躏我、掠夺我，将我整个吃掉！……一口都别剩下。"
},
	[6219]={ lines="让我猜猜你会怎么选呢……嗯哼，我很喜欢呢~", voice="hero_4528_cv_19.prefab", voice1="hero_4528_cv_19.prefab", lines1="让我猜猜你会怎么选呢……嗯哼，我很喜欢呢~"
},
	[6220]={ lines="……诶呀？它掉了呢~帮帮我，或者……做你想做的事情~", voice="hero_4528_cv_20.prefab", voice1="hero_4528_cv_20.prefab", lines1="……诶呀？它掉了呢~帮帮我，或者……做你想做的事情~"
},
	[6221]={ lines="甜点是悠闲午后最好的伴侣……嗯……你也来尝一尝吧，链尉官~", voice="hero_4528_cv_21.prefab", voice1="hero_4528_cv_21.prefab", lines1="甜点是悠闲午后最好的伴侣……嗯……你也来尝一尝吧，链尉官~"
},
	[6301]={ lines="风雪为我带来了你的故事，链尉官。我是弦枝，“黄金时代”最后的吟游诗人，我很期待因你而生的谱曲里，会藏着怎样的风景。", voice="hero_4529_cv_01.prefab", voice1="hero_4529_cv_01.prefab", lines1="风雪为我带来了你的故事，链尉官。我是弦枝，“黄金时代”最后的吟游诗人，我很期待因你而生的谱曲里，会藏着怎样的风景。"
},
	[6302]={ lines="就由我为各位的旅途演奏一首序曲吧。", voice="hero_4529_cv_02.prefab", voice1="hero_4529_cv_02.prefab", lines1="就由我为各位的旅途演奏一首序曲吧。"
},
	[6303]={ lines="倾听吧。", voice="hero_4529_cv_03.prefab", voice1="hero_4529_cv_03.prefab", lines1="倾听吧。"
},
	[6304]={ lines="完美的节奏。", voice="hero_4529_cv_04.prefab", voice1="hero_4529_cv_04.prefab", lines1="完美的节奏。"
},
	[6305]={ lines="此刻正是，纵情演奏之时。", voice="hero_4529_cv_05.prefab", voice1="hero_4529_cv_05.prefab", lines1="此刻正是，纵情演奏之时。"
},
	[6306]={ lines="这场胜利，是写给黎明的序章。", voice="hero_4529_cv_06.prefab", voice1="hero_4529_cv_06.prefab", lines1="这场胜利，是写给黎明的序章。"
},
	[6307]={ lines="链尉官，今天你会为我带来怎样的故事呢？", voice="hero_4529_cv_07.prefab", voice1="hero_4529_cv_07.prefab", lines1="链尉官，今天你会为我带来怎样的故事呢？"
},
	[6308]={ lines="我喜欢倾听这片大地上发生的故事，将其编成传唱的歌谣——每一个音符，每一个节拍，都是一段传说的回响。", voice="hero_4529_cv_08.prefab", voice1="hero_4529_cv_08.prefab", lines1="我喜欢倾听这片大地上发生的故事，将其编成传唱的歌谣——每一个音符，每一个节拍，都是一段传说的回响。"
},
	[6309]={ lines="累了吗？那就坐下来好好休息，听我为你弹唱一曲吧——你想听重金属？啊哈哈，那个我不是很擅长呢……", voice="hero_4529_cv_09.prefab", voice1="hero_4529_cv_09.prefab", lines1="累了吗？那就坐下来好好休息，听我为你弹唱一曲吧——你想听重金属？啊哈哈，那个我不是很擅长呢……"
},
	[6310]={ lines="嗯……嗯……！只是这么看着你的模样，我就又有了许多创作的灵光涌现呢~", voice="hero_4529_cv_10.prefab", voice1="hero_4529_cv_10.prefab", lines1="嗯……嗯……！只是这么看着你的模样，我就又有了许多创作的灵光涌现呢~"
},
	[6311]={ lines="深入灯塔寻找失落文明的秘密，登上大船扬帆远航……呵呵，与你初次相遇就是这般波澜壮阔的篇章，我更期待有你在的未来会有多精彩了。", voice="hero_4529_cv_11.prefab", voice1="hero_4529_cv_11.prefab", lines1="深入灯塔寻找失落文明的秘密，登上大船扬帆远航……呵呵，与你初次相遇就是这般波澜壮阔的篇章，我更期待有你在的未来会有多精彩了。"
},
	[6312]={ lines="对吟游诗人来说，能让诗歌永远留在人们心中并传唱下去，就是最好的认可。所以终有一天，我也会把你的故事谱写成一首绝妙的诗歌，传遍整个世界。", voice="hero_4529_cv_12.prefab", voice1="hero_4529_cv_12.prefab", lines1="对吟游诗人来说，能让诗歌永远留在人们心中并传唱下去，就是最好的认可。所以终有一天，我也会把你的故事谱写成一首绝妙的诗歌，传遍整个世界。"
},
	[6313]={ lines="说起来，以链尉官的故事而创作的诗歌里，女主角应该是谁比较好呢？不止一个人……？要是链尉官愿意的话，当然可以。", voice="hero_4529_cv_13.prefab", voice1="hero_4529_cv_13.prefab", lines1="说起来，以链尉官的故事而创作的诗歌里，女主角应该是谁比较好呢？不止一个人……？要是链尉官愿意的话，当然可以。"
},
	[6314]={ lines="吟游诗人往往寻风而居、与自然为伴——但请你不必担心，我们之间早有专属的曲调，当它响起时，我就会循着旋律，回到你的身边。", voice="hero_4529_cv_14.prefab", voice1="hero_4529_cv_14.prefab", lines1="吟游诗人往往寻风而居、与自然为伴——但请你不必担心，我们之间早有专属的曲调，当它响起时，我就会循着旋律，回到你的身边。"
},
	[6315]={ lines="唯愿你的夏天永不凋零，唯愿你的传说永不落幕——我曾想过要以怎样的诗歌，才能写下我对你的爱意……但此时此刻，我不再想纠结如何落笔，只想和你相拥入怀，让每一分的呼吸与心跳，代替所有的字词与吟唱……", voice="hero_4529_cv_15.prefab", voice1="hero_4529_cv_15.prefab", lines1="唯愿你的夏天永不凋零，唯愿你的传说永不落幕——我曾想过要以怎样的诗歌，才能写下我对你的爱意……但此时此刻，我不再想纠结如何落笔，只想和你相拥入怀，让每一分的呼吸与心跳，代替所有的字词与吟唱……"
},
	[6316]={ lines="误闯雪林魔女的城堡，你可知道要付出怎样的代价……呵呵，今晚就待在这里，和我一起创作只属于今夜的诗歌吧~", voice="hero_4529_cv_16.prefab", voice1="hero_4529_cv_16.prefab", lines1="误闯雪林魔女的城堡，你可知道要付出怎样的代价……呵呵，今晚就待在这里，和我一起创作只属于今夜的诗歌吧~"
},
	[6317]={ lines="嗯……！这也是旋律的一种呢。", voice="hero_4529_cv_17_1.prefab", voice1="hero_4529_cv_17_1.prefab", lines1="嗯……！这也是旋律的一种呢。"
},
	[6318]={ lines="嗯……！这也是旋律的一种呢。", voice="hero_4529_cv_17_2.prefab", voice1="hero_4529_cv_17_2.prefab", lines1="嗯……！这也是旋律的一种呢。"
},
	[6319]={ lines="嗯……！这也是旋律的一种呢。", voice="hero_4529_cv_17_3.prefab", voice1="hero_4529_cv_17_3.prefab", lines1="嗯……！这也是旋律的一种呢。"
},
	[6320]={ lines="故事的高潮想要选在这里吗？", voice="hero_4529_cv_18.prefab", voice1="hero_4529_cv_18.prefab", lines1="故事的高潮想要选在这里吗？"
},
	[6321]={ lines="嗯……链尉官的抚摸，就像粼粼涌动的水浪拍打在身上，令人舒适呢~", voice="hero_4529_cv_19.prefab", voice1="hero_4529_cv_19.prefab", lines1="嗯……链尉官的抚摸，就像粼粼涌动的水浪拍打在身上，令人舒适呢~"
},
	[6322]={ lines="链尉官……？呜嗯？！哎呀，用鱼儿来使坏……看到了链尉官的另一面呢~", voice="hero_4529_cv_20.prefab", voice1="hero_4529_cv_20.prefab", lines1="链尉官……？呜嗯？！哎呀，用鱼儿来使坏……看到了链尉官的另一面呢~"
},
	[6323]={ lines="循着歌声而来的冒险者，想要和我一同探寻这静谧的深海吗？这样是不是一个美妙的故事开头呢~", voice="hero_4529_cv_21.prefab", voice1="hero_4529_cv_21.prefab", lines1="循着歌声而来的冒险者，想要和我一同探寻这静谧的深海吗？这样是不是一个美妙的故事开头呢~"
},
	[6401]={ lines="鸣晔，冒昧拜谒，如有什么用得上我的地方，尽管吩咐便好。", voice="hero_4530_cv_01.prefab", voice1="hero_4530_cv_01.prefab", lines1="鸣晔，冒昧拜谒，如有什么用得上我的地方，尽管吩咐便好。"
},
	[6402]={ lines="听凭差遣。", voice="hero_4530_cv_02.prefab", voice1="hero_4530_cv_02.prefab", lines1="听凭差遣。"
},
	[6403]={ lines="拟此青山一貌，乃作浮沉一渺。", voice="hero_4530_cv_03.prefab", voice1="hero_4530_cv_03.prefab", lines1="拟此青山一貌，乃作浮沉一渺。"
},
	[6404]={ lines="四时如我尽意，赐尔恒久弥新。", voice="hero_4530_cv_04.prefab", voice1="hero_4530_cv_04.prefab", lines1="四时如我尽意，赐尔恒久弥新。"
},
	[6405]={ lines="浮云渺远，气象更迭，可知——大梦将晓？", voice="hero_4530_cv_05.prefab", voice1="hero_4530_cv_05.prefab", lines1="浮云渺远，气象更迭，可知——大梦将晓？"
},
	[6406]={ lines="花开万千，汝自凋零。", voice="hero_4530_cv_06.prefab", voice1="hero_4530_cv_06.prefab", lines1="花开万千，汝自凋零。"
},
	[6407]={ lines="日安，我看外边风景正好，可要一同观赏么？", voice="hero_4530_cv_07.prefab", voice1="hero_4530_cv_07.prefab", lines1="日安，我看外边风景正好，可要一同观赏么？"
},
	[6408]={ lines="……总说世间种种皆似幻梦，万事无足轻重，但正因如此，你我所坚定选择的将来才更为珍贵，不是吗？", voice="hero_4530_cv_08.prefab", voice1="hero_4530_cv_08.prefab", lines1="……总说世间种种皆似幻梦，万事无足轻重，但正因如此，你我所坚定选择的将来才更为珍贵，不是吗？"
},
	[6409]={ lines="嘘，噤声……与我一起闭眼，聆听万物的低语……还有我的心声……在你身边时，它跳得有些快。", voice="hero_4530_cv_09.prefab", voice1="hero_4530_cv_09.prefab", lines1="嘘，噤声……与我一起闭眼，聆听万物的低语……还有我的心声……在你身边时，它跳得有些快。"
},
	[6410]={ lines="你想要知道它的来历吗？嗯……这个故事会有些长，好在我有很多时间可以慢慢讲给你听。", voice="hero_4530_cv_10.prefab", voice1="hero_4530_cv_10.prefab", lines1="你想要知道它的来历吗？嗯……这个故事会有些长，好在我有很多时间可以慢慢讲给你听。"
},
	[6411]={ lines="祭祀、祈福，求仙告神，桩桩件件，都曾是我的责任和使命，你若是好奇其中的玄妙，不妨随我前来，认真体会一番如何？", voice="hero_4530_cv_11.prefab", voice1="hero_4530_cv_11.prefab", lines1="祭祀、祈福，求仙告神，桩桩件件，都曾是我的责任和使命，你若是好奇其中的玄妙，不妨随我前来，认真体会一番如何？"
},
	[6412]={ lines="世间诸事，各有因果勾连，我本无意驻足，但在遇见你之后，心绪忽而有了改变。", voice="hero_4530_cv_12.prefab", voice1="hero_4530_cv_12.prefab", lines1="世间诸事，各有因果勾连，我本无意驻足，但在遇见你之后，心绪忽而有了改变。"
},
	[6413]={ lines="往事俱作风烟散，我心澄似琉璃净，万般风霜再不惧。链尉官，我所窥见的前路，每一步都与你密不可分。", voice="hero_4530_cv_13.prefab", voice1="hero_4530_cv_13.prefab", lines1="往事俱作风烟散，我心澄似琉璃净，万般风霜再不惧。链尉官，我所窥见的前路，每一步都与你密不可分。"
},
	[6414]={ lines="天际的长风、远方的故土，还有更多被我眷恋之物，其间种种，我都想邀你同看。", voice="hero_4530_cv_14.prefab", voice1="hero_4530_cv_14.prefab", lines1="天际的长风、远方的故土，还有更多被我眷恋之物，其间种种，我都想邀你同看。"
},
	[6415]={ lines="有道是“浮生一觉方知梦，半盏人间茶未凉”，哪怕真是如此，你在我心中留下的印记也已无可磨灭，但只是铭记总还不够，链尉官，我可否与你……嗯，有些更深层次的羁绊呢……", voice="hero_4530_cv_15.prefab", voice1="hero_4530_cv_15.prefab", lines1="有道是“浮生一觉方知梦，半盏人间茶未凉”，哪怕真是如此，你在我心中留下的印记也已无可磨灭，但只是铭记总还不够，链尉官，我可否与你……嗯，有些更深层次的羁绊呢……"
},
	[6416]={ lines="家乡习俗如此，祈祝你来年康健，我当然也该为你献上此物……", voice="", voice1="hero_4530_cv_16.prefab", lines1="家乡习俗如此，祈祝你来年康健，我当然也该为你献上此物……嗯哼……"
},
	[6417]={ lines="按摩吗……诶呀……稍微重一点也没关系的……", voice="", voice1="hero_4530_cv_17.prefab", lines1="这里吗……还是那儿……稍微重一点也没关系的……"
},
	[6418]={ lines="呀……你有没有觉得……天气有点点热？我都出汗了呢……", voice="", voice1="hero_4530_cv_18.prefab", lines1="呀……你这样子……该你了……还是……要一起呢……"
},
	[6431]={ lines="洞天福地现，林深待客来。欢迎你，链尉官，寒舍简陋，你屈驾而来，请随意就好，我会尽心招待。", voice="", voice1="hero_4530_cv_1001.prefab", lines1="洞天福地现，林深待客来。欢迎你，链尉官，寒舍简陋，你屈驾而来，请随意就好，我会尽心招待。"
},
	[6432]={ lines="呵呵，既是如此良宵，和你在一起，我也心情舒畅了许多。", voice="", voice1="hero_4530_cv_1002.prefab", lines1="呵呵，既是如此良宵，情意浓时……嗯……你我都该尽兴，不是么……"
},
	[6433]={ lines="要做什么？", voice="", voice1="hero_4530_cv_1003.prefab", lines1="嗯……！"
},
	[6434]={ lines="唔……", voice="", voice1="hero_4530_cv_1004.prefab", lines1="唔……"
},
	[6435]={ lines="在我旁边吗……？", voice="", voice1="hero_4530_cv_1005.prefab", lines1="哈嗯……"
},
	[6436]={ lines="呵呵……", voice="", voice1="hero_4530_cv_1006.prefab", lines1="嗯呀……"
},
	[6437]={ lines="哎呀？", voice="", voice1="hero_4530_cv_1007.prefab", lines1="呜嗯？！"
},
	[6438]={ lines="还是有些疲劳的感觉么……呵呵，那就再多休息一会吧。", voice="", voice1="hero_4530_cv_1008.prefab", lines1="想要用另一种方式获得满足么……哈嗯！呵呵，我也意犹未尽呢……"
},
	[6439]={ lines="我也有些渴了呢。", voice="", voice1="hero_4530_cv_1009.prefab", lines1="我也有些渴了呢。"
},
	[6440]={ lines="想要我一口气喝下去么？那便恭敬不如从命了……呵呵，一滴不剩呢。", voice="", voice1="hero_4530_cv_1010.prefab", lines1="想要我一口气喝下去么？那便恭敬不如从命了……呵呵，一滴不剩呢。"
},
	[6441]={ lines="茶水浸润肌肤的触感有些冰凉 ，和你的手指……温度不太一样……", voice="", voice1="hero_4530_cv_1011.prefab", lines1="茶水浸润肌肤的触感有些冰凉 ，和你的……温度不太一样……"
},
	[6442]={ lines="歇息足了，便想要看到不一样的我么？呵呵……来点简单的小花样如何？", voice="", voice1="hero_4530_cv_1012.prefab", lines1="歇息足了，便想要看到不一样的我么？呵呵……来点简单的小花样如何？"
},
	[6443]={ lines="小胜一局~", voice="", voice1="hero_4530_cv_1013.prefab", lines1="小胜一局~"
},
	[6444]={ lines="哼，不过是暂时输了而已……", voice="", voice1="hero_4530_cv_1014.prefab", lines1="哼，不过是半解衣裳而已……"
},
	[6445]={ lines="优势在我~", voice="", voice1="hero_4530_cv_1015.prefab", lines1="优势在我~"
},
	[6446]={ lines="大意了……", voice="", voice1="hero_4530_cv_1016.prefab", lines1="大意了……"
},
	[6447]={ lines="胜局已定~", voice="", voice1="hero_4530_cv_1017.prefab", lines1="胜局已定~"
},
	[6448]={ lines="呜……这就是失败的滋味么……", voice="", voice1="hero_4530_cv_1018.prefab", lines1="呜……这就是失败的滋味么……"
},
	[6449]={ lines="愿赌服输……下次的胜者一定是我。", voice="", voice1="hero_4530_cv_1019.prefab", lines1="愿赌服输……我便满足你的要求……呜嗯……哈啊！！"
},
	[6450]={ lines="女为悦己者容，我当然也一样，想要叫你看到自己最好的那一面。", voice="", voice1="hero_4530_cv_1020.prefab", lines1="女为悦己者容，我当然也一样，想要叫你看到自己最好的那一面。"
},
	[6451]={ lines="嗯……？", voice="", voice1="hero_4530_cv_1021_1.prefab", lines1="嗯……？"
},
	[6452]={ lines="嗯……？", voice="", voice1="hero_4530_cv_1021_2.prefab", lines1="嗯……？"
},
	[6453]={ lines="嗯……？", voice="", voice1="hero_4530_cv_1021_3.prefab", lines1="嗯……？"
},
	[6454]={ lines="不要捉弄我了哦~", voice="", voice1="hero_4530_cv_1022.prefab", lines1="呜嗯……痒痒的。"
},
	[6455]={ lines="呵呵 ……想要再一起待会么？……我当然也是……", voice="", voice1="hero_4530_cv_1023.prefab", lines1="呵呵 ……你就这样迫不及待了吗……我当然也是……"
},
	[6456]={ lines="心情变得躁动，衣服也有些乱了呢，我来帮你整理。", voice="", voice1="hero_4530_cv_1024.prefab", lines1="心情变得躁动，衣服也有些乱了呢，我来帮你整理吧……"
},
	[6457]={ lines="……嗯？", voice="", voice1="hero_4530_cv_1025.prefab", lines1="哼！"
},
	[6458]={ lines="", voice="", voice1="hero_4530_cv_1026.prefab", lines1=""
},
	[6459]={ lines="", voice="", voice1="hero_4530_cv_1027.prefab", lines1=""
},
	[6501]={ lines="“天使计划”——座天使雾涅尔。主人，愿您的光辉照耀“阿卡狄亚”，为吾等带去现世的祝福！", voice="hero_4531_cv_01.prefab", voice1="hero_4531_cv_01.prefab", lines1="“天使计划”——座天使雾涅尔。主人，愿您的光辉照耀“阿卡狄亚”，为吾等带去现世的祝福！"
},
	[6502]={ lines="谨遵主命！", voice="hero_4531_cv_02.prefab", voice1="hero_4531_cv_02.prefab", lines1="谨遵主命！"
},
	[6503]={ lines="全部锁定！", voice="hero_4531_cv_03.prefab", voice1="hero_4531_cv_03.prefab", lines1="全部锁定！"
},
	[6504]={ lines="定向密钥，激活！", voice="hero_4531_cv_04.prefab", voice1="hero_4531_cv_04.prefab", lines1="定向密钥，激活！"
},
	[6505]={ lines="阿卡夏之心，全域名封锁！", voice="hero_4531_cv_05.prefab", voice1="hero_4531_cv_05.prefab", lines1="阿卡夏之心，全域名封锁！"
},
	[6506]={ lines="在虚拟的世界中，你赢不了我！", voice="hero_4531_cv_06.prefab", voice1="hero_4531_cv_06.prefab", lines1="在虚拟的世界中，你赢不了我！"
},
	[6507]={ lines="欢迎来到新的一天，主人。需要我侍奉您起床穿衣服吗？", voice="hero_4531_cv_07.prefab", voice1="hero_4531_cv_07.prefab", lines1="欢迎来到新的一天，主人。需要我侍奉您起床穿衣服吗？"
},
	[6508]={ lines="万能的阿卡夏之心，请你告诉我，我要怎么做才能让主人开心呢？", voice="hero_4531_cv_08.prefab", voice1="hero_4531_cv_08.prefab", lines1="万能的阿卡夏之心，请你告诉我，我要怎么做才能让主人开心呢？"
},
	[6509]={ lines="唔唔……嗯，主人？休息时间了，一起来吃点蛋糕吧，甜甜的很好吃哦。", voice="hero_4531_cv_09.prefab", voice1="hero_4531_cv_09.prefab", lines1="唔唔……嗯，主人？休息时间了，一起来吃点蛋糕吧，甜甜的很好吃哦。"
},
	[6510]={ lines="对、对不起，我不是故意把电脑弄坏的，主人的数据我会帮忙找回来的！", voice="hero_4531_cv_10.prefab", voice1="hero_4531_cv_10.prefab", lines1="对、对不起，我不是故意把电脑弄坏的，主人的数据我会帮忙找回来的！"
},
	[6511]={ lines="桌子上的文件？那些我已经帮主人处理好了，就按照平常的样子……诶？那些是特殊文件？！对不起我不是故意的不要怪我！！！", voice="hero_4531_cv_11.prefab", voice1="hero_4531_cv_11.prefab", lines1="桌子上的文件？那些我已经帮主人处理好了，就按照平常的样子……诶？那些是特殊文件？！对不起我不是故意的不要怪我！！！"
},
	[6512]={ lines="主人，看！这是食堂的姐姐们教我做的草莓蛋糕，我终于成功了！快尝尝看，如果好吃的话我就再做点！", voice="hero_4531_cv_12.prefab", voice1="hero_4531_cv_12.prefab", lines1="主人，看！这是食堂的姐姐们教我做的草莓蛋糕，我终于成功了！快尝尝看，如果好吃的话我就再做点！"
},
	[6513]={ lines="主人，不可以欺负女孩子哦……你说没有？那为什么每天晚上，主人的房间里都有女孩子喊得很大声呢？我问谁这个问题她们都不告诉我，艾丽西亚姐姐还红着脸让我出去玩……主人，你每天晚上都在做什么呢？", voice="hero_4531_cv_13.prefab", voice1="hero_4531_cv_13.prefab", lines1="主人，不可以欺负女孩子哦……你说没有？那为什么每天晚上，主人的房间里都有女孩子喊得很大声呢？我问谁这个问题她们都不告诉我，艾丽西亚姐姐还红着脸让我出去玩……主人，你每天晚上都在做什么呢？"
},
	[6514]={ lines="海玟姐姐预见了我和主人的相遇，但她一定想不到主人为我带来的改变……崭新的使命、触手可及的明天。如果没遇到主人，我无法想象“幸福”居然如此美好。", voice="hero_4531_cv_14.prefab", voice1="hero_4531_cv_14.prefab", lines1="海玟姐姐预见了我和主人的相遇，但她一定想不到主人为我带来的改变……崭新的使命、触手可及的明天。如果没遇到主人，我无法想象“幸福”居然如此美好。"
},
	[6515]={ lines="主人，我的胸口又热又痛，这是我从未检索到的信息……我好想永远留在你的身边，主人。我好喜欢你，我喜欢你喜欢得无法自拔……这就是人类所说的……爱吗？你愿意接受一个虚数生命的爱吗？", voice="hero_4531_cv_15.prefab", voice1="hero_4531_cv_15.prefab", lines1="主人，我的胸口又热又痛，这是我从未检索到的信息……我好想永远留在你的身边，主人。我好喜欢你，我喜欢你喜欢得无法自拔……这就是人类所说的……爱吗？你愿意接受一个虚数生命的爱吗？"
},
	[6516]={ lines="哈……哎呀！呜呜呜，奶油溅得满身都是……好甜！主人……要尝尝吗？", voice="", voice1="hero_4531_cv_16.prefab", lines1="哈……哎呀！呜呜呜，溅得满身都是……好甜！主人……要尝尝吗？"
},
	[6517]={ lines="这、这是我给你准备的惊喜……链尉官，请享用吧……", voice="", voice1="hero_4531_cv_17.prefab", lines1="哎，主人……嗯！……这、这是我给你准备的惊喜……哈……主人，请享用吧……"
},
	[6518]={ lines="链尉官喂我吗，啊——唔……真好吃，已经……吃不动了……", voice="", voice1="hero_4531_cv_18.prefab", lines1="主人喂我吗，啊——唔……唔唔唔？……唔唔噗哈——已经……被填满了……吃不动了……"
},
	[6601]={ lines="虚蚀猎人——序列第五，赫梅克。我们终于见面了，链尉官，按照虚蚀猎人的传统，请让我称呼你为“殿下”，可以吗？", voice="hero_4532_cv_01.prefab", voice1="hero_4532_cv_01.prefab", lines1="虚蚀猎人——序列第五，赫梅克。我们终于见面了，链尉官，按照虚蚀猎人的传统，请让我称呼你为“殿下”，可以吗？"
},
	[6602]={ lines="有我在，天空将属于我们。", voice="hero_4532_cv_02.prefab", voice1="hero_4532_cv_02.prefab", lines1="有我在，天空将属于我们。"
},
	[6603]={ lines="接受死亡。", voice="hero_4532_cv_03.prefab", voice1="hero_4532_cv_03.prefab", lines1="接受死亡。"
},
	[6604]={ lines="苦痛长存。", voice="hero_4532_cv_04.prefab", voice1="hero_4532_cv_04.prefab", lines1="苦痛长存。"
},
	[6605]={ lines="我将化作流星，撕裂长空，为众敌带来毁灭！", voice="hero_4532_cv_05.prefab", voice1="hero_4532_cv_05.prefab", lines1="我将化作流星，撕裂长空，为众敌带来毁灭！"
},
	[6606]={ lines="无垠的天空，将会见证我们的凯旋。", voice="hero_4532_cv_06.prefab", voice1="hero_4532_cv_06.prefab", lines1="无垠的天空，将会见证我们的凯旋。"
},
	[6607]={ lines="殿下，我们何时启程？我已经迫不及待在天空翱翔了。", voice="hero_4532_cv_07.prefab", voice1="hero_4532_cv_07.prefab", lines1="殿下，我们何时启程？我已经迫不及待在天空翱翔了。"
},
	[6608]={ lines="殿下？你的目光一直在我的尾巴上——想要摸一下吗?没关系，我不介意。", voice="hero_4532_cv_08.prefab", voice1="hero_4532_cv_08.prefab", lines1="殿下？你的目光一直在我的尾巴上-一想要摸一下吗?没关系，我不介意。"
},
	[6609]={ lines="殿下，和我一起去外头吹吹风吧?放心，有我抱着你，不用担心会掉下去。", voice="hero_4532_cv_09.prefab", voice1="hero_4532_cv_09.prefab", lines1="殿下，和我一起去外头吹吹风吧?放心，有我抱着你，不用担心会掉下去。"
},
	[6610]={ lines="我的力量虽然与修格尔有关，但并不是修格尔的转生，所以殿下可以放心，我不会把你吃了的。", voice="hero_4532_cv_10.prefab", voice1="hero_4532_cv_10.prefab", lines1="我的力量虽然与修格尔有关，但并不是修格尔的转生，所以殿下可以放心，我不会把你吃了的。"
},
	[6611]={ lines="殿下会做“噩梦”吗？我的噩梦，是一片燃烧着的火海，焰火和浓烟遮住了天空，遮住了一切，让我无法逃脱……每一次醒来，我都庆幸着，自己还能“醒来”。", voice="hero_4532_cv_11.prefab", voice1="hero_4532_cv_11.prefab", lines1="殿下会做“噩梦”吗？我的噩梦，是一片燃烧着的火海，焰火和浓烟遮住了天空，遮住了一切，让我无法逃脱……每一次醒来，我都庆幸着，自己还能“醒来”。"
},
	[6612]={ lines="相比红叶和尤加利，我或许有些不善表达，但是我也……不想让殿下觉得我是一个冷血的人，所以……就像在那塔中一样，再拥抱一次吧，殿下。", voice="hero_4532_cv_12.prefab", voice1="hero_4532_cv_12.prefab", lines1="相比红叶和尤加利，我或许有些不善表达，但是我也……不想让殿下觉得我是一个冷血的人，所以……就像在那塔中一样，再拥抱一次吧，殿下。"
},
	[6613]={ lines="殿下很好奇我的“收藏”？只是一些小物件罢了，不过我可以向殿下保证，这些物件都是独一无二的珍藏——照片？啊，这是殿下的……咳咳！这，这只是我的个人兴趣而已，绝对没有别的意思，绝，绝对没有……", voice="hero_4532_cv_13.prefab", voice1="hero_4532_cv_13.prefab", lines1="殿下很好奇我的“收藏”？只是一些小物件罢了，不过我可以向殿下保证，这些物件都是独一无二的珍藏——照片？啊，这是殿下的……咳咳！这，这只是我的个人兴趣而已，绝对没有别的意思，绝，绝对没有……"
},
	[6614]={ lines="曾经的我，被背叛，被抛弃，沉溺于火海之中无法逃离……是仇恨驱使我继续活下去，告诉我任何人都不值得信任——不过，那已经是曾经的我了，现在的我，会把后背交给我的伙伴，把我的心……交给殿下。", voice="hero_4532_cv_14.prefab", voice1="hero_4532_cv_14.prefab", lines1="曾经的我，被背叛，被抛弃，沉溺于火海之中无法逃离……是仇恨驱使我继续活下去，告诉我任何人都不值得信任——不过，那已经是曾经的我了，现在的我，会把后背交给我的伙伴，把我的心……交给殿下。"
},
	[6615]={ lines="那艘船沉没后，我以为自己再也找不到归宿，只能在复仇的业火中燃尽所有……直到遇见了你，殿下。是你平息了我灵魂深处的怒火，现在的我，已经找到了此生最珍贵的宝物——那就是在你身边的每一刻。这份契约将超越时间和天际，直到万物终结的尽头。", voice="hero_4532_cv_15.prefab", voice1="hero_4532_cv_15.prefab", lines1="那艘船沉没后，我以为自己再也找不到归宿，只能在复仇的业火中燃尽所有……直到遇见了你，殿下。是你平息了我灵魂深处的怒火，现在的我，已经找到了此生最珍贵的宝物——那就是在你身边的每一刻。这份契约将超越时间和天际，直到万物终结的尽头。"
},
	[6616]={ lines="呜嗯……还没到“下班时间”，殿下就已经急不可耐了么……工作需要放松一下？那就请殿下，继续帮我舒缓身体吧。", voice="hero_4532_cv_16.prefab", voice1="hero_4532_cv_16.prefab", lines1="呜嗯……还没到“下班时间”，殿下就已经急不可耐了么……工作需要放松一下？那就请殿下，继续帮我舒缓身体吧。"
},
	[6617]={ lines="呵呵，为了殿下的安全，我必须得更靠近一些才行……这份炽热，希望殿下能仔细感受。", voice="hero_4532_cv_17.prefab", voice1="hero_4532_cv_17.prefab", lines1="呵呵，为了殿下的安全，我必须得更靠近一些才行……这份炽热，希望殿下能仔细感受。"
},
	[6618]={ lines="按照角色剧本的说明，请殿下不要离开我的视线……照顾身心健康？当，当然，这也是我的责任……", voice="hero_4532_cv_18.prefab", voice1="hero_4532_cv_18.prefab", lines1="按照角色剧本的说明，请殿下不要离开我的视线……照顾身心健康？当，当然，这也是我的责任……"
},
	[6619]={ lines="诶？殿下你要做什……新点的贵宾服务？如果是殿下的话……嗯……我愿意……哎呀！", voice="hero_4532_cv_19.prefab", voice1="hero_4532_cv_19.prefab", lines1="诶？殿下你要做什……新点的贵宾服务？如果是殿下的话……嗯……我愿意……哎呀！"
},
	[6620]={ lines="我刚刚学会了新歌……请您……啊……殿、殿下……你又……捉弄我……嗯……", voice="hero_4532_cv_20.prefab", voice1="hero_4532_cv_20.prefab", lines1="我刚刚学会了新歌……请您……啊……殿、殿下……你又……捉弄我……嗯……"
},
	[6621]={ lines="这是……独属于殿下的演唱会，持续时间是……整个夜晚，直到黎明。", voice="hero_4532_cv_21.prefab", voice1="hero_4532_cv_21.prefab", lines1="这是……独属于殿下的演唱会，持续时间是……整个夜晚，直到黎明。"
},
	[6701]={ lines="垂星，从上一个时代而来，为你守望明日。", voice="hero_4533_cv_01.prefab", voice1="hero_4533_cv_01.prefab", lines1="垂星，从上一个时代而来，为你守望明日。"
},
	[6702]={ lines="我将履行我的承诺，为你而战！", voice="hero_4533_cv_02.prefab", voice1="hero_4533_cv_02.prefab", lines1="我将履行我的承诺，为你而战！"
},
	[6703]={ lines="裁决灵魂，裁断罪孽……哈哈哈……", voice="hero_4533_cv_03.prefab", voice1="hero_4533_cv_03.prefab", lines1="裁决灵魂，裁断罪孽……呵呵呵呵……"
},
	[6704]={ lines="安然沉醉吧……在这寂静的葬仪中……呵呵呵呵……", voice="hero_4533_cv_04.prefab", voice1="hero_4533_cv_04.prefab", lines1="安然沉醉吧……在这寂静的葬仪中……哈哈哈"
},
	[6705]={ lines="睁大眼，好好注视着这不可再见的绝景……", voice="hero_4533_cv_05.prefab", voice1="hero_4533_cv_05.prefab", lines1="睁大眼，好好注视着这不可再见的绝景……"
},
	[6706]={ lines="命运，请为我驻足……", voice="hero_4533_cv_06.prefab", voice1="hero_4533_cv_06.prefab", lines1="命运，请为我驻足……"
},
	[6707]={ lines="难怪我的心突然跳得这么快，原来是你回来了。", voice="hero_4533_cv_07.prefab", voice1="hero_4533_cv_07.prefab", lines1="难怪我的心突然跳得这么快，原来是你回来了。"
},
	[6708]={ lines="我曾在不间断的失去中侥幸存活，因而认为遗憾是我余生的全部情绪……幸好遇见了你。", voice="hero_4533_cv_08.prefab", voice1="hero_4533_cv_08.prefab", lines1="我曾在不间断的失去中侥幸存活，因而认为遗憾是我余生的全部情绪……幸好遇见了你。"
},
	[6709]={ lines="这是那个时代的东西，背面曾刻了我的名字……只是这么多年过去，它也早已变得模糊了。", voice="hero_4533_cv_09.prefab", voice1="hero_4533_cv_09.prefab", lines1="这是那个时代的东西，背面曾刻了我的名字……只是这么多年过去，它也早已变得模糊了。"
},
	[6710]={ lines="武器并非只可用作屠戮，在以后的日子里，我会用它为你开拓前路，贯彻名为守护的使命。", voice="hero_4533_cv_10.prefab", voice1="hero_4533_cv_10.prefab", lines1="武器并非只可用作屠戮，在以后的日子里，我会用它为你开拓前路，贯彻名为守护的使命。"
},
	[6711]={ lines="遗忘是通向未来的捷径，铭记却带来苦痛与伤痕，我从来没有后悔过自己的选择，它塑造了如今的我……与你相遇的那个我。", voice="hero_4533_cv_11.prefab", voice1="hero_4533_cv_11.prefab", lines1="遗忘是通向未来的捷径，铭记却带来苦痛与伤痕，我从来没有后悔过自己的选择，它塑造了如今的我……与你相遇的那个我。"
},
	[6712]={ lines="自从与你相识，我眼中的世界便拥有了色彩。我许多次在心中恼恨没能早一点见到你，幸好现在的一切都还不算晚。", voice="hero_4533_cv_12.prefab", voice1="hero_4533_cv_12.prefab", lines1="自从与你相识，我眼中的世界便拥有了色彩。我许多次在心中恼恨没能早一点见到你，幸好现在的一切都还不算晚。"
},
	[6713]={ lines="我见过白昼的崩溃，与之一同毁灭的还有我自己，是你重新带来了黎明，并将我支离破碎的灵魂捡起，然后把它一片片拼凑了起来。", voice="hero_4533_cv_13.prefab", voice1="hero_4533_cv_13.prefab", lines1="我见过白昼的崩溃，与之一同毁灭的还有我自己，是你重新带来了黎明，并将我支离破碎的灵魂捡起，然后把它一片片拼凑了起来。"
},
	[6714]={ lines="猜猜看，此刻的我……又是哪一副面貌呢？嘘，不必说出心中的答案，就像你知道的那样，我一直是我，你的维瑟内特。", voice="hero_4533_cv_14.prefab", voice1="hero_4533_cv_14.prefab", lines1="猜猜看，此刻的我……又是哪一副面貌呢？嘘，不必说出心中的答案，就像你知道的那样，我一直是我，你的维瑟内特。"
},
	[6715]={ lines="除了这腔对你的爱意，我一无所有，能为你献上的不过是一颗真心，倘若它能有足够的份量，就请你将它放上你的棋局，让我能有资格同你一起与命运对弈……", voice="hero_4533_cv_15.prefab", voice1="hero_4533_cv_15.prefab", lines1="除了这腔对你的爱意，我一无所有，能为你献上的不过是一颗真心，倘若它能有足够的份量，就请你将它放上你的棋局，让我能有资格同你一起与命运对弈……"
},
	[6716]={ lines="我享受您赐予我的一切、乃至疼痛与笞责，只恳求您的目光再多为我驻留片刻……", voice="hero_4533_cv_16.prefab", voice1="hero_4533_cv_16.prefab", lines1="我享受您赐予我的一切、乃至疼痛与笞责，只恳求您的目光再多为我驻留片刻……"
},
	[6717]={ lines="这是您加于我身的印记，于我而言，则是无上的恩典……", voice="hero_4533_cv_17.prefab", voice1="hero_4533_cv_17.prefab", lines1="这是您加于我身的印记，于我而言，则是无上的恩典……"
},
	[6718]={ lines="唔……我会坦诚我的罪孽，请您聆听我的忏悔……", voice="hero_4533_cv_18.prefab", voice1="hero_4533_cv_18.prefab", lines1="唔……我会坦诚我的罪孽，请你聆听我的忏悔……"
},
	[6801]={ lines="风带来了你身上独特的气息。链尉官，我叫赫芙蕊娅，很高兴与你缔结契约。", voice="hero_4534_cv_01.prefab", voice1="hero_4534_cv_01.prefab", lines1="风带来了你身上独特的气息。链尉官，我叫赫芙蕊娅，很高兴与你缔结契约。"
},
	[6802]={ lines="交给我，一切都会安稳落幕。", voice="hero_4534_cv_02.prefab", voice1="hero_4534_cv_02.prefab", lines1="交给我，一切都会安稳落幕。"
},
	[6803]={ lines="不必害怕。", voice="hero_4534_cv_03.prefab", voice1="hero_4534_cv_03.prefab", lines1="不必害怕。"
},
	[6804]={ lines="有我在你们身边。", voice="hero_4534_cv_04.prefab", voice1="hero_4534_cv_04.prefab", lines1="有我在你们身边。"
},
	[6805]={ lines="这份特制香息，会为你们隔绝一切伤痛。", voice="hero_4534_cv_05.prefab", voice1="hero_4534_cv_05.prefab", lines1="这份特制香息，会为你们隔绝一切伤痛。"
},
	[6806]={ lines="闻一闻吧，这是敌人败亡的气息。", voice="hero_4534_cv_06.prefab", voice1="hero_4534_cv_06.prefab", lines1="闻一闻吧，这是敌人败亡的气息。"
},
	[6807]={ lines="我刚调配好了新的香薰。若是链尉官疲惫的话，不妨在此稍作停留，这里足够安稳与安心。", voice="hero_4534_cv_07.prefab", voice1="hero_4534_cv_07.prefab", lines1="我刚调配好了新的香薰。若是链尉官疲惫的话，不妨在此稍作停留，这里足够安稳与安心。"
},
	[6808]={ lines="每调出一味新的香水，我都会第一个想起你。想知道，它在你的体温上，会变成什么模样……前调，会不会太冷。尾调，够不够暖。", voice="hero_4534_cv_08.prefab", voice1="hero_4534_cv_08.prefab", lines1="每调出一味新的香水，我都会第一个想起你。想知道，它在你的体温上，会变成什么模样……前调，会不会太冷。尾调，够不够暖。"
},
	[6809]={ lines="你闻到了吗？这层檀香和愈创木的尾调……是“家”的味道。我承诺过，要为在乎的人……守住这片安宁。", voice="hero_4534_cv_09.prefab", voice1="hero_4534_cv_09.prefab", lines1="你闻到了吗？这层檀香和愈创木的尾调……是“家”的味道。我承诺过，要为在乎的人……守住这片安宁。"
},
	[6810]={ lines="人在说谎时，汗水会混合着一种特别的酸涩……就像被碾碎的夹竹桃叶那样。所以，在我面前……最好别说谎哦？", voice="hero_4534_cv_10.prefab", voice1="hero_4534_cv_10.prefab", lines1="人在说谎时，汗水会混合着一种特别的酸涩……就像被碾碎的夹竹桃叶那样。所以，在我面前……最好别说谎哦？"
},
	[6811]={ lines="闻到我身上这款新调制的香氛了吗？迷人馥郁的表层之下，暗藏足以致命的毒意。世间万物，向来皆是如此。", voice="hero_4534_cv_11.prefab", voice1="hero_4534_cv_11.prefab", lines1="闻到我身上这款新调制的香氛了吗？迷人馥郁的表层之下，暗藏足以致命的毒意。世间万物，向来皆是如此。"
},
	[6812]={ lines="闲来无事时我总喜欢调配香氛、照料花园。平淡琐碎的日常，能暂时抚平过往残留在心底的戾气。链尉官若是感兴趣，我可以教你分辨不同香料的气息。", voice="hero_4534_cv_12.prefab", voice1="hero_4534_cv_12.prefab", lines1="闲来无事时我总喜欢调配香氛、照料花园。平淡琐碎的日常，能暂时抚平过往残留在心底的戾气。链尉官若是感兴趣，我可以教你分辨不同香料的气息。"
},
	[6813]={ lines="无论是余烬的家人，还是你……我都希望所有人都能远离纷争与伤痛。这份安稳……我会亲自守护到底。", voice="hero_4534_cv_13.prefab", voice1="hero_4534_cv_13.prefab", lines1="无论是余烬的家人，还是你……我都希望所有人都能远离纷争与伤痛。这份安稳……我会亲自守护到底。"
},
	[6814]={ lines="过往的伤痛无法抹去，未来的前路依旧凶险。但有你在我身边……我不再被过去束缚，也能坦然接纳属于自己的温柔。", voice="hero_4534_cv_14.prefab", voice1="hero_4534_cv_14.prefab", lines1="过往的伤痛无法抹去，未来的前路依旧凶险。但有你在我身边……我不再被过去束缚，也能坦然接纳属于自己的温柔。"
},
	[6815]={ lines="我曾以为黑暗就是我的宿命，余生只会与孤独为伴。现在我终于明了一切……我所奔赴的光明，从来都不是虚无的远方，而是……眼前的你。", voice="hero_4534_cv_15.prefab", voice1="hero_4534_cv_15.prefab", lines1="我曾以为黑暗就是我的宿命，余生只会与孤独为伴。现在我终于明了一切……我所奔赴的光明，从来都不是虚无的远方，而是……眼前的你。"
},
	[6816]={ lines="呀嗯……真是大胆呢，链尉官~想在这无人的海边对我干些什么？我可是会……有点小期待的呢~", voice="hero_4534_cv_16.prefab", voice1="hero_4534_cv_16.prefab", lines1="呀嗯……真是大胆呢，链尉官~想在这无人的海边对我干些什么？我可是会……有点小期待的呢~"
},
	[6817]={ lines="嗯……呜……链尉官，防晒霜可不能只涂这一个地方……嗯~……真是坏心眼的孩子~", voice="hero_4534_cv_17.prefab", voice1="hero_4534_cv_17.prefab", lines1="嗯……呜……链尉官，防晒霜可不能只涂这一个地方……嗯~……真是坏心眼的孩子~"
},
	[6818]={ lines="链尉官的手……好炙热……被链尉官抚摸过的地方，都忍不住躁动起来了呢~", voice="hero_4534_cv_18.prefab", voice1="hero_4534_cv_18.prefab", lines1="链尉官的手……好炙热……被链尉官抚摸过的地方，都忍不住躁动起来了呢~"
},
	[6901]={ lines="神光重科垃圾清洁效率科主任……呃……兼虚蚀猎人队长，涅普露，前来报道！别……别在意，我还要适应一下……", voice="hero_4535_cv_01.prefab", voice1="hero_4535_cv_01.prefab", lines1="神光重科垃圾清洁效率科主任……呃……兼虚蚀猎人队长，涅普露，前来报道！别……别在意，我还要适应一下……"
},
	[6902]={ lines="拥有全新力量的我，是否也有资格与你并肩了呢？", voice="hero_4535_cv_02.prefab", voice1="hero_4535_cv_02.prefab", lines1="拥有全新力量的我，是否也有资格与你并肩了呢？"
},
	[6903]={ lines="躲不掉了哦~", voice="hero_4535_cv_03.prefab", voice1="hero_4535_cv_03.prefab", lines1="躲不掉了哦~"
},
	[6904]={ lines="赤焰疾行！", voice="hero_4535_cv_04.prefab", voice1="hero_4535_cv_04.prefab", lines1="赤焰疾行！"
},
	[6905]={ lines="不死的神鸟啊，焚尽这凛冬吧！", voice="hero_4535_cv_05.prefab", voice1="hero_4535_cv_05.prefab", lines1="不死的神鸟啊，焚尽这凛冬吧！"
},
	[6906]={ lines="烧垃圾这种活儿，我最擅长了！", voice="hero_4535_cv_06.prefab", voice1="hero_4535_cv_06.prefab", lines1="烧垃圾这种活儿，我最擅长了！"
},
	[6907]={ lines="莱斯坦斯真暖和……我是不是到天堂了……", voice="hero_4535_cv_07.prefab", voice1="hero_4535_cv_07.prefab", lines1="莱斯坦斯真暖和……我是不是到天堂了……"
},
	[6908]={ lines="可别小看垃圾清洁效率科哦，链尉官。神光重科发行的扫地机器人可都是我的研究成果呢。", voice="hero_4535_cv_08.prefab", voice1="hero_4535_cv_08.prefab", lines1="可别小看垃圾清洁效率科哦，链尉官。神光重科发行的扫地机器人可都是我的研究成果呢。"
},
	[6909]={ lines="还是很在意我的手吗？其实也挺方便的，现在我烧水都不用开火了！", voice="hero_4535_cv_09.prefab", voice1="hero_4535_cv_09.prefab", lines1="还是很在意我的手吗？其实也挺方便的，现在我烧水都不用开火了！"
},
	[6910]={ lines="回到虚蚀域，就像是回到了老……天呐，我是不是离人类越来越远了……", voice="hero_4535_cv_10.prefab", voice1="hero_4535_cv_10.prefab", lines1="回到虚蚀域，就像是回到了老……天呐，我是不是离人类越来越远了……"
},
	[6911]={ lines="链~尉~官~，我从烈火中，现身……哎哎哎！对不起链尉官我不是故意要烧到你衣服的！我这就去找水！", voice="hero_4535_cv_11.prefab", voice1="hero_4535_cv_11.prefab", lines1="链~尉~官~，我从烈火中，现身……哎哎哎！对不起链尉官我不是故意要烧到你衣服的！我这就去找水！"
},
	[6912]={ lines="垃圾清洁效率科已经变成都市传说了？！那个……我是不是该按时去神光重科露个脸，毕竟和α主任还有合作……诶？没有许可不许离开虚蚀域？好像是哦……", voice="hero_4535_cv_12.prefab", voice1="hero_4535_cv_12.prefab", lines1="垃圾清洁效率科已经变成都市传说了？！那个……我是不是该按时去神光重科露个脸，毕竟和α主任还有合作……诶？没有许可不许离开虚蚀域？好像是哦……"
},
	[6913]={ lines="那场大战过后，我在伊凡城留了一座房子，有空闲的时候我常会偷偷跑回来住几天。链尉官你能理解的吧？不会判我违纪吧？", voice="hero_4535_cv_13.prefab", voice1="hero_4535_cv_13.prefab", lines1="那场大战过后，我在伊凡城留了一座房子，有空闲的时候我常会偷偷跑回来住几天。链尉官你能理解的吧？不会判我违纪吧？"
},
	[6914]={ lines="明明现在的我已经不再是人类了，可我却感到自己正真切地……活在这里，燃烧着，向整片极北释放着温暖……链尉官，这是你点着的火，而且灭不了了呢。", voice="hero_4535_cv_14.prefab", voice1="hero_4535_cv_14.prefab", lines1="明明现在的我已经不再是人类了，可我却感到自己正真切地……活在这里，燃烧着，向整片极北释放着温暖……链尉官，这是你点着的火，而且灭不了了呢。"
},
	[6915]={ lines="看呐链尉官，极北的火焰花又盛开了。我想……我要使用你曾留给我的承诺了。这一次……待到花谢的时候再走……好吗？", voice="hero_4535_cv_15.prefab", voice1="hero_4535_cv_15.prefab", lines1="看呐链尉官，极北的火焰花又盛开了。我想……我要使用你曾留给我的承诺了。这一次……待到花谢的时候再走……好吗？"
},
	[6916]={ lines="链尉官，我……喝不了太多……哎呀，撒出来了……哎！好痒啊链尉官……啊哈哈", voice="hero_4535_cv_16.prefab", voice1="hero_4535_cv_16.prefab", lines1="链尉官，我……喝不了太多……哎呀，撒出来了……哎！好痒啊链尉官……啊哈哈"
},
	[6917]={ lines="想要……这个？那就拿去吧……它早已……属于你了……嗯……", voice="hero_4535_cv_17.prefab", voice1="hero_4535_cv_17.prefab", lines1="想要……这个？那就拿去吧……它早已……属于你了……嗯……"
},
	[6918]={ lines="眼睛紧紧地盯着我呢，链尉官……诶嘿嘿，请再多看看我吧……今晚，只许你看我一人……", voice="hero_4535_cv_18.prefab", voice1="hero_4535_cv_18.prefab", lines1="眼睛紧紧地盯着我呢，链尉官……诶嘿嘿，请再多看看我吧……今晚，只许你看我一人……"
},
	[6931]={ lines="嗯……，是链尉官来啦？嘿嘿，我等你好久了哦……现在，这里只有我们两个人了呢……一起喝一杯吧？", voice="hero_4535_cv_1001.prefab", voice1="hero_4535_cv_1001.prefab", lines1="嗯……，是链尉官来啦？嘿嘿，我等你好久了哦……现在，这里只有我们两个人了呢……一起喝一杯吧？"
},
	[6932]={ lines="", voice="hero_4535_cv_1002.prefab", voice1="hero_4535_cv_1002.prefab", lines1=""
},
	[6933]={ lines="……味道甜甜的，链尉官也要喝一点吗？", voice="hero_4535_cv_1003.prefab", voice1="hero_4535_cv_1003.prefab", lines1="……味道甜甜的，链尉官也要喝一点吗？"
},
	[6934]={ lines="……噗哈！呼……呼……", voice="hero_4535_cv_1004.prefab", voice1="hero_4535_cv_1004.prefab", lines1="……噗哈！呼……呼……"
},
