	[20001]={ lines="在超脱维度的规则中诞生的神明，将向世人揭示，何为净世乐土的天堂--伊甸园。", voice="mon_6316_b_cv_01.prefab", voice1="mon_6316_b_cv_01.prefab", lines1="在超脱维度的规则中诞生的神明，将向世人揭示，何为净世乐土的天堂--伊甸园。"
