	[20002]={ lines="接受毁灭。", voice="mon_6316_b_cv_02.prefab", voice1="mon_6316_b_cv_02.prefab", lines1="接受毁灭。"
},
	[20003]={ lines="将你们完全抹杀。", voice="mon_6316_b_cv_03.prefab", voice1="mon_6316_b_cv_03.prefab", lines1="将你们完全抹杀。"
